--
-- Name: _canonical_caller_in_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._canonical_caller_in_org(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_users
     WHERE organization_id = p_org AND user_id = auth.uid()
  );
$$;


--
-- Name: _canonical_spine_enabled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._canonical_spine_enabled(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT canonical_spine_v1 FROM public.org_settings WHERE organization_id = p_org LIMIT 1),
    false
  );
$$;


--
-- Name: _check_questionnaire_token_rate_limit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._check_questionnaire_token_rate_limit(p_token_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window TIMESTAMPTZ := date_trunc('minute', now()) - make_interval(mins => (extract(minute from now())::int % 5));
  v_count INT;
BEGIN
  INSERT INTO public.questionnaire_token_attempts(token_hash, window_start, count)
  VALUES (p_token_hash, v_window, 1)
  ON CONFLICT (token_hash, window_start)
  DO UPDATE SET count = public.questionnaire_token_attempts.count + 1
  RETURNING count INTO v_count;

  IF v_count > 30 THEN
    RAISE EXCEPTION 'Rate limit exceeded';
  END IF;
END;
$$;


--
-- Name: _hash_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._hash_token(p_token text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT encode(extensions.digest(p_token::bytea, 'sha256'), 'hex')
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: questionnaire_public_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.questionnaire_public_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    questionnaire_instance_id uuid NOT NULL,
    token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: _require_valid_questionnaire_link(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._require_valid_questionnaire_link(p_instance_id uuid, p_token text) RETURNS public.questionnaire_public_links
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hash TEXT;
  v_link public.questionnaire_public_links;
BEGIN
  v_hash := public._hash_token(p_token);

  PERFORM public._check_questionnaire_token_rate_limit(v_hash);

  SELECT * INTO v_link
  FROM public.questionnaire_public_links
  WHERE questionnaire_instance_id = p_instance_id
    AND token_hash = v_hash
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'invalid_token');
    RAISE EXCEPTION 'Invalid questionnaire link';
  END IF;

  IF v_link.revoked_at IS NOT NULL THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'revoked');
    RAISE EXCEPTION 'Questionnaire link has been revoked';
  END IF;

  IF v_link.expires_at <= now() THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'expired');
    RAISE EXCEPTION 'Questionnaire link has expired';
  END IF;

  RETURN v_link;
END;
$$;


--
-- Name: _touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;


--
-- Name: accept_org_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_org_invitation(invitation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inv record;
  new_member_id uuid;
BEGIN
  -- Get invitation
  SELECT * INTO inv
  FROM public.invitations
  WHERE id = invitation_id AND status = 'pending';

  IF inv IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired invitation.';
  END IF;

  -- Verify the current user matches invitation email
  IF inv.email != (SELECT email FROM auth.users WHERE id = auth.uid()) THEN
    RAISE EXCEPTION 'This invitation is not for your account.';
  END IF;

  -- Check not already a member
  IF EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = auth.uid() AND organization_id = inv.organization_id
  ) THEN
    -- Already a member, just mark invitation as accepted
    UPDATE public.invitations SET status = 'accepted', accepted_at = now() WHERE id = invitation_id;
    RETURN (SELECT id FROM public.organization_users WHERE user_id = auth.uid() AND organization_id = inv.organization_id);
  END IF;

  -- Add member
  INSERT INTO public.organization_users (organization_id, user_id, role)
  VALUES (inv.organization_id, auth.uid(), inv.role)
  RETURNING id INTO new_member_id;

  -- Mark invitation accepted
  UPDATE public.invitations SET status = 'accepted', accepted_at = now() WHERE id = invitation_id;

  RETURN new_member_id;
END;
$$;


--
-- Name: acknowledge_failed_email_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_failed_email_safe(p_email_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_email RECORD;
  v_org_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  v_org_id := v_email.organization_id;
  IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: manager+ required');
  END IF;

  IF v_email.status != 'failed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only acknowledge failed emails');
  END IF;

  UPDATE email_queue SET
    status = 'ignored',
    acknowledged_at = now(),
    acknowledged_by = v_user_id,
    updated_at = now()
  WHERE id = p_email_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_org_id, 'email', p_email_id, 'acknowledged_failure', v_user_id,
    jsonb_build_object('last_error', v_email.last_error_message));

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: acknowledge_vat_reconciliation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_vat_reconciliation(p_reconciliation_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reconciliation RECORD;
  v_user_id UUID;
  v_org_role TEXT;
BEGIN
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  -- Fetch reconciliation
  SELECT * INTO v_reconciliation FROM vat_reconciliations WHERE id = p_reconciliation_id;
  
  IF v_reconciliation.id IS NULL THEN
    RAISE EXCEPTION 'Reconciliation not found';
  END IF;
  
  -- Check user has org access and is at least staff
  SELECT role INTO v_org_role FROM organization_users 
  WHERE user_id = v_user_id AND organization_id = v_reconciliation.organization_id;
  
  IF v_org_role IS NULL THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  IF v_org_role NOT IN ('owner', 'admin', 'staff') THEN
    RAISE EXCEPTION 'Only accountants can acknowledge reconciliation differences';
  END IF;
  
  -- Only WARNING classification requires acknowledgement
  IF v_reconciliation.classification != 'WARNING' THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Reconciliation is INFO classification, no acknowledgement required'
    );
  END IF;
  
  -- Already acknowledged?
  IF v_reconciliation.acknowledged THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Reconciliation already acknowledged',
      'acknowledged_by', v_reconciliation.acknowledged_by_user_id,
      'acknowledged_at', v_reconciliation.acknowledged_at
    );
  END IF;
  
  -- Acknowledge
  UPDATE vat_reconciliations
  SET 
    acknowledged = true,
    acknowledged_by_user_id = v_user_id,
    acknowledged_at = now(),
    acknowledgement_note = p_note,
    updated_at = now()
  WHERE id = p_reconciliation_id;
  
  -- Audit log
  INSERT INTO audit_log (
    organization_id, entity_type, entity_id, action, user_id, metadata
  ) VALUES (
    v_reconciliation.organization_id,
    'vat_reconciliation',
    p_reconciliation_id,
    'VAT_RECONCILIATION_ACKNOWLEDGED',
    v_user_id,
    jsonb_build_object(
      'difference', v_reconciliation.difference,
      'classification', v_reconciliation.classification,
      'vat_period_id', v_reconciliation.vat_period_id,
      'model_snapshot_id', v_reconciliation.model_snapshot_id,
      'note', p_note
    )
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'acknowledged_at', now(),
    'acknowledged_by', v_user_id
  );
END;
$$;


--
-- Name: add_org_member(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_org_member(target_org_id uuid, target_user_id uuid, target_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  caller_role text;
  new_id uuid;
BEGIN
  -- Validate role
  IF target_role NOT IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'Invalid role. Only admin or staff can be assigned.';
  END IF;

  -- Check caller is owner of the org
  SELECT role INTO caller_role
  FROM public.organization_users
  WHERE user_id = auth.uid() AND organization_id = target_org_id;

  IF caller_role IS NULL OR caller_role != 'owner' THEN
    RAISE EXCEPTION 'Only owners can add members directly.';
  END IF;

  -- Prevent duplicate
  IF EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = target_user_id AND organization_id = target_org_id
  ) THEN
    RAISE EXCEPTION 'User is already a member of this organization.';
  END IF;

  INSERT INTO public.organization_users (organization_id, user_id, role)
  VALUES (target_org_id, target_user_id, target_role)
  RETURNING id INTO new_id;

  -- Audit log
  INSERT INTO public.audit_log (organization_id, user_id, entity_type, entity_id, action, actor_role, metadata)
  VALUES (target_org_id, auth.uid(), 'organization_user', new_id, 'member_added', caller_role,
    jsonb_build_object('target_user_id', target_user_id, 'assigned_role', target_role));

  RETURN new_id;
END;
$$;


--
-- Name: add_reconciliation_line(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_reconciliation_line(p_reconciliation_id uuid, p_bank_transaction_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
  v_txn public.bank_transactions%ROWTYPE;
  v_line_id uuid;
BEGIN
  SELECT * INTO v_rec FROM public.reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation not found'; END IF;
  IF v_rec.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Reconciliation is not in progress (status=%)', v_rec.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank transaction not found'; END IF;

  IF v_txn.bank_account_id <> v_rec.bank_account_id THEN
    RAISE EXCEPTION 'Transaction belongs to a different bank account';
  END IF;
  IF v_txn.transaction_date < v_rec.statement_start_date
     OR v_txn.transaction_date > v_rec.statement_end_date THEN
    RAISE EXCEPTION 'Transaction date % outside reconciliation period', v_txn.transaction_date;
  END IF;
  IF v_txn.matched_ledger_entry_id IS NULL THEN
    RAISE EXCEPTION 'Transaction must be posted/matched to the ledger before reconciliation';
  END IF;

  -- Prevent duplicate inclusion in any reconciliation
  IF EXISTS (
    SELECT 1 FROM public.reconciliation_lines
    WHERE bank_transaction_id = p_bank_transaction_id
  ) THEN
    RAISE EXCEPTION 'Transaction already included in a reconciliation';
  END IF;

  INSERT INTO public.reconciliation_lines (
    reconciliation_id, bank_transaction_id, ledger_entry_id, match_type, amount
  ) VALUES (
    p_reconciliation_id, p_bank_transaction_id, v_txn.matched_ledger_entry_id, 'auto', v_txn.amount
  ) RETURNING id INTO v_line_id;

  UPDATE public.bank_transactions
     SET status = 'RECONCILED', updated_at = now()
   WHERE id = p_bank_transaction_id;

  RETURN v_line_id;
END;
$$;


--
-- Name: add_service_to_client(uuid, uuid, uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_service_to_client(p_client_id uuid, p_company_id uuid, p_service_id uuid, p_period_start date, p_period_end date, p_period_label text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service_code text;
  v_service_name text;
  v_billing_frequency text;
  v_frequency text;
  v_engagement_id uuid;
  v_job_id uuid;
BEGIN
  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Provide exactly one of client or company';
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Entity not found';
  END IF;
  IF NOT public.user_has_organization_access(v_org) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT code, name, billing_model
    INTO v_service_code, v_service_name, v_billing_frequency
    FROM public.services_catalog WHERE id = p_service_id;
  IF v_service_code IS NULL THEN
    RAISE EXCEPTION 'Service not found';
  END IF;
  v_frequency := CASE WHEN v_billing_frequency = 'monthly' THEN 'monthly' ELSE 'one_off' END;

  SELECT id INTO v_engagement_id
    FROM public.engagements
    WHERE service_id = p_service_id
      AND client_id IS NOT DISTINCT FROM p_client_id
      AND company_id IS NOT DISTINCT FROM p_company_id
    LIMIT 1;
  IF v_engagement_id IS NULL THEN
    INSERT INTO public.engagements
      (organization_id, client_id, company_id, service_id, frequency, start_date, status, activated_at)
    VALUES
      (v_org, p_client_id, p_company_id, p_service_id, v_frequency, CURRENT_DATE, 'active', now())
    RETURNING id INTO v_engagement_id;
  ELSE
    UPDATE public.engagements
      SET status = 'active', activated_at = COALESCE(activated_at, now())
      WHERE id = v_engagement_id;
  END IF;

  v_job_id := public.lifecycle_upsert_job_with_deadlines(
    v_org, p_client_id, p_company_id, v_engagement_id,
    v_service_code, v_service_name, p_period_start, p_period_end, p_period_label,
    'manual_add_service'
  );

  RETURN v_job_id;
END;
$$;


--
-- Name: allocate_credit_note(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_credit_note(p_credit_note_id uuid, p_allocations jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cn record;
  v_alloc jsonb;
  v_doc_id uuid;
  v_amount numeric;
  v_total_alloc numeric := 0;
  v_inv record;
  v_bill record;
  v_new_paid numeric;
  v_new_remaining numeric;
  v_membership boolean;
  v_new_cn_remaining numeric;
  v_new_cn_status text;
BEGIN
  SELECT * INTO v_cn FROM credit_notes WHERE id = p_credit_note_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note not found');
  END IF;

  IF NOT v_cn.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note must be approved before allocating');
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM organization_users
    WHERE organization_id = v_cn.organization_id
      AND user_id = COALESCE(p_user_id, auth.uid())
  ) INTO v_membership;
  IF NOT v_membership THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Not authorized for this organization');
  END IF;

  -- Validate totals first
  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := COALESCE((v_alloc->>'amount')::numeric, 0);
    IF v_amount <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'Allocation amount must be positive');
    END IF;
    v_total_alloc := v_total_alloc + v_amount;
  END LOOP;

  IF v_total_alloc > v_cn.remaining_allocation + 0.005 THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Total allocation exceeds remaining credit');
  END IF;

  -- Apply each allocation
  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_doc_id := (v_alloc->>'document_id')::uuid;
    v_amount := (v_alloc->>'amount')::numeric;

    IF v_cn.credit_note_type = 'SALES' THEN
      SELECT id, organization_id, amount_paid, total_gross
      INTO v_inv FROM invoices WHERE id = v_doc_id FOR UPDATE;
      IF NOT FOUND OR v_inv.organization_id <> v_cn.organization_id THEN
        RETURN jsonb_build_object('success', false, 'error_message', 'Invoice not found / wrong org');
      END IF;

      INSERT INTO credit_note_allocations (
        organization_id, credit_note_id, invoice_id, bill_id,
        amount, allocation_date, created_by
      ) VALUES (
        v_cn.organization_id, v_cn.id, v_doc_id, NULL,
        v_amount, CURRENT_DATE, COALESCE(p_user_id, auth.uid())
      );

      v_new_paid := COALESCE(v_inv.amount_paid, 0) + v_amount;
      v_new_remaining := v_inv.total_gross - v_new_paid;
      UPDATE invoices
      SET amount_paid = v_new_paid,
          remaining_balance = v_new_remaining,
          status = CASE WHEN v_new_remaining <= 0.005 THEN 'PAID' ELSE 'PART_PAID' END,
          updated_at = now()
      WHERE id = v_doc_id;

    ELSE
      SELECT id, organization_id, amount_paid, total_gross
      INTO v_bill FROM bills WHERE id = v_doc_id FOR UPDATE;
      IF NOT FOUND OR v_bill.organization_id <> v_cn.organization_id THEN
        RETURN jsonb_build_object('success', false, 'error_message', 'Bill not found / wrong org');
      END IF;

      INSERT INTO credit_note_allocations (
        organization_id, credit_note_id, invoice_id, bill_id,
        amount, allocation_date, created_by
      ) VALUES (
        v_cn.organization_id, v_cn.id, NULL, v_doc_id,
        v_amount, CURRENT_DATE, COALESCE(p_user_id, auth.uid())
      );

      v_new_paid := COALESCE(v_bill.amount_paid, 0) + v_amount;
      v_new_remaining := v_bill.total_gross - v_new_paid;
      UPDATE bills
      SET amount_paid = v_new_paid,
          remaining_balance = v_new_remaining,
          status = CASE WHEN v_new_remaining <= 0.005 THEN 'PAID' ELSE 'PART_PAID' END,
          updated_at = now()
      WHERE id = v_doc_id;
    END IF;
  END LOOP;

  v_new_cn_remaining := GREATEST(0, v_cn.remaining_allocation - v_total_alloc);
  v_new_cn_status := CASE WHEN v_new_cn_remaining <= 0.005 THEN 'FULLY_ALLOCATED' ELSE 'PARTIALLY_ALLOCATED' END;

  UPDATE credit_notes
  SET remaining_allocation = v_new_cn_remaining,
      status = v_new_cn_status,
      updated_at = now(),
      updated_by = COALESCE(p_user_id, auth.uid())
  WHERE id = p_credit_note_id;

  RETURN jsonb_build_object(
    'success', true,
    'remaining_allocation', v_new_cn_remaining,
    'credit_note_status', v_new_cn_status
  );
END;
$$;


--
-- Name: apply_bank_match(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_bank_match(p_bank_transaction_id uuid, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn RECORD;
  v_alloc JSONB;
  v_doc_id UUID;
  v_doc_type TEXT;
  v_amount NUMERIC;
  v_total_allocated NUMERIC := 0;
  v_journal_id UUID;
  v_settings RECORD;
  v_contra_account_id UUID;
  v_invoice RECORD;
  v_bill RECORD;
  v_entries JSONB := '[]'::jsonb;
  v_user_id UUID := auth.uid();
  v_post_result JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;
  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RAISE EXCEPTION 'Transaction already %', v_txn.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := (v_alloc->>'amount')::numeric;
    IF v_amount <= 0 THEN
      RAISE EXCEPTION 'Allocation amounts must be positive';
    END IF;
    v_total_allocated := v_total_allocated + v_amount;
  END LOOP;

  IF ROUND(v_total_allocated::numeric, 2) <> ROUND(ABS(v_txn.amount)::numeric, 2) THEN
    RAISE EXCEPTION 'Allocations (%) must equal transaction amount (%)',
      v_total_allocated, ABS(v_txn.amount);
  END IF;

  SELECT * INTO v_settings FROM public.org_settings
   WHERE organization_id = v_txn.organization_id
   LIMIT 1;

  v_before := to_jsonb(v_txn);

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_doc_id := (v_alloc->>'document_id')::uuid;
    v_doc_type := v_alloc->>'document_type';
    v_amount := (v_alloc->>'amount')::numeric;

    IF v_doc_type = 'invoice' THEN
      SELECT * INTO v_invoice FROM public.invoices WHERE id = v_doc_id;
      IF NOT FOUND OR v_invoice.organization_id <> v_txn.organization_id THEN
        RAISE EXCEPTION 'Invoice % not found or cross-tenant', v_doc_id;
      END IF;
      IF v_invoice.client_id IS DISTINCT FROM v_txn.client_id
         OR v_invoice.company_id IS DISTINCT FROM v_txn.company_id THEN
        RAISE EXCEPTION 'Invoice % belongs to a different entity', v_doc_id;
      END IF;

      v_contra_account_id := v_settings.ar_control_account_id;
      IF v_contra_account_id IS NULL THEN
        RAISE EXCEPTION 'AR control account not configured in org_settings';
      END IF;

      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_txn.bank_account_id, 'debit', v_amount, 'credit', 0,
                           'description', 'Receipt: invoice ' || COALESCE(v_invoice.invoice_number, v_doc_id::text)),
        jsonb_build_object('account_id', v_contra_account_id, 'debit', 0, 'credit', v_amount,
                           'description', 'Receipt: invoice ' || COALESCE(v_invoice.invoice_number, v_doc_id::text))
      );

      INSERT INTO public.invoice_payments(
        invoice_id, amount, payment_date, bank_account_id,
        bank_transaction_id, reference, payment_type, created_by
      ) VALUES (
        v_doc_id, v_amount, v_txn.transaction_date, v_txn.bank_account_id,
        p_bank_transaction_id,
        'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
        'normal', v_user_id
      );

    ELSIF v_doc_type = 'bill' THEN
      SELECT * INTO v_bill FROM public.bills WHERE id = v_doc_id;
      IF NOT FOUND OR v_bill.organization_id <> v_txn.organization_id THEN
        RAISE EXCEPTION 'Bill % not found or cross-tenant', v_doc_id;
      END IF;
      IF v_bill.client_id IS DISTINCT FROM v_txn.client_id
         OR v_bill.company_id IS DISTINCT FROM v_txn.company_id THEN
        RAISE EXCEPTION 'Bill % belongs to a different entity', v_doc_id;
      END IF;

      v_contra_account_id := v_settings.ap_control_account_id;
      IF v_contra_account_id IS NULL THEN
        RAISE EXCEPTION 'AP control account not configured in org_settings';
      END IF;

      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_contra_account_id, 'debit', v_amount, 'credit', 0,
                           'description', 'Payment: bill ' || COALESCE(v_bill.bill_number, v_doc_id::text)),
        jsonb_build_object('account_id', v_txn.bank_account_id, 'debit', 0, 'credit', v_amount,
                           'description', 'Payment: bill ' || COALESCE(v_bill.bill_number, v_doc_id::text))
      );

      INSERT INTO public.bill_payments(
        bill_id, amount, payment_date, bank_account_id,
        bank_transaction_id, reference, payment_type, created_by
      ) VALUES (
        v_doc_id, v_amount, v_txn.transaction_date, v_txn.bank_account_id,
        p_bank_transaction_id,
        'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
        'normal', v_user_id
      );
    ELSE
      RAISE EXCEPTION 'Unsupported document type: %', v_doc_type;
    END IF;
  END LOOP;

  v_post_result := public.post_to_ledger(
    p_organization_id := v_txn.organization_id,
    p_client_id       := v_txn.client_id,
    p_company_id      := v_txn.company_id,
    p_transaction_date:= v_txn.transaction_date,
    p_description     := 'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
    p_source_type     := 'BANK_TRANSACTION',
    p_source_id       := p_bank_transaction_id,
    p_entries         := v_entries
  );

  v_journal_id := (v_post_result->>'journal_id')::uuid;

  UPDATE public.bank_transactions
     SET status = 'MATCHED',
         matched_ledger_entry_id = v_journal_id
   WHERE id = p_bank_transaction_id;

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_match', v_user_id,
    v_before,
    jsonb_build_object('status','MATCHED','journal_id',v_journal_id),
    jsonb_build_object('allocations', p_allocations)
  );

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: apply_bank_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_bank_rule(p_bank_transaction_id uuid, p_rule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_rule record;
  v_bank record;
  v_actions jsonb;
  v_action jsonb;
  v_account_id uuid;
  v_vat_code_id uuid;
  v_category text;
  v_post_result jsonb;
  v_before jsonb;
  v_actor uuid := auth.uid();
  v_is_member boolean;
BEGIN
  -- Lock the transaction row to serialise concurrent rule applications
  SELECT * INTO v_txn FROM bank_transactions
    WHERE id = p_bank_transaction_id
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  SELECT user_in_organization(v_actor, v_txn.organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Only accountants in this organisation can apply bank rules');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED','CATEGORIZED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_categorized',
                              'error_message', 'Transaction is already categorised');
  END IF;

  BEGIN
    PERFORM assert_no_locked_period_write(
      v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'period_locked',
                              'error_message', SQLERRM);
  END;

  SELECT * INTO v_rule FROM bank_rules WHERE id = p_rule_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'rule_not_found',
                              'error_message', 'Bank rule not found');
  END IF;
  IF v_rule.organization_id <> v_txn.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'org_mismatch',
                              'error_message', 'Rule and transaction belong to different organisations');
  END IF;
  IF v_rule.is_active IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'rule_inactive',
                              'error_message', 'Rule is not active');
  END IF;
  IF v_rule.client_id IS NOT NULL AND v_rule.client_id IS DISTINCT FROM v_txn.client_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'scope_mismatch',
                              'error_message', 'Rule is scoped to a different client');
  END IF;
  IF v_rule.company_id IS NOT NULL AND v_rule.company_id IS DISTINCT FROM v_txn.company_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'scope_mismatch',
                              'error_message', 'Rule is scoped to a different company');
  END IF;
  IF v_rule.bank_account_id IS NOT NULL AND v_rule.bank_account_id IS DISTINCT FROM v_txn.bank_account_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_mismatch',
                              'error_message', 'Rule is scoped to a different bank account');
  END IF;

  v_actions := COALESCE(v_rule.actions, '[]'::jsonb);
  FOR v_action IN SELECT * FROM jsonb_array_elements(v_actions) LOOP
    IF v_action->>'type' = 'set_account' THEN
      v_account_id := NULLIF(v_action->>'value','')::uuid;
    ELSIF v_action->>'type' = 'set_vat_code' THEN
      v_vat_code_id := NULLIF(v_action->>'value','')::uuid;
    ELSIF v_action->>'type' = 'set_category' THEN
      v_category := v_action->>'value';
    END IF;
  END LOOP;

  IF v_account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_account_action',
                              'error_message', 'Rule must define a set_account action');
  END IF;

  SELECT * INTO v_bank FROM bank_accounts WHERE id = v_txn.bank_account_id;
  IF NOT FOUND OR v_bank.organization_id <> v_txn.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_invalid',
                              'error_message', 'Bank account not found or not in this organisation');
  END IF;

  v_before := to_jsonb(v_txn);

  -- REVIEW MODE: stage suggestion only, do not post.
  IF v_rule.requires_review OR NOT v_rule.auto_post THEN
    UPDATE bank_transactions
       SET rule_id = p_rule_id,
           category = COALESCE(v_category, category),
           client_suggested_account_id = v_account_id,
           review_status = 'pending'::bk_review_status,
           status = 'PENDING_REVIEW'
     WHERE id = p_bank_transaction_id;

    INSERT INTO bank_rule_executions(
      organization_id, bank_rule_id, bank_transaction_id, executed_by,
      matched_conditions, applied_actions, result
    ) VALUES (
      v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
      v_rule.conditions, v_rule.actions, 'pending_review'
    );

    INSERT INTO bookkeeping_audit_log(
      organization_id, entity_type, entity_id, action, actor_id,
      before_state, after_state, metadata
    ) VALUES (
      v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule_suggested', v_actor,
      v_before,
      jsonb_build_object('suggested_account_id', v_account_id, 'rule_id', p_rule_id,
                         'category', v_category, 'status', 'PENDING_REVIEW'),
      jsonb_build_object('rule_source', v_rule.source, 'vat_sensitive', v_rule.vat_sensitive)
    );

    UPDATE bank_rules
       SET times_applied = COALESCE(times_applied, 0) + 1,
           last_applied_at = now()
     WHERE id = p_rule_id;

    RETURN jsonb_build_object('success', true, 'mode', 'review',
                              'message', 'Rule staged for accountant review');
  END IF;

  -- AUTO-POST MODE
  v_post_result := post_bank_transaction(
    p_bank_transaction_id := p_bank_transaction_id,
    p_contra_account_id   := v_account_id,
    p_vat_code_id         := v_vat_code_id,
    p_vat_amount          := 0,
    p_description         := COALESCE(v_txn.description, v_rule.rule_name)
  );

  IF v_post_result IS NULL OR (v_post_result->>'success')::boolean IS DISTINCT FROM true THEN
    INSERT INTO bank_rule_executions(
      organization_id, bank_rule_id, bank_transaction_id, executed_by,
      matched_conditions, applied_actions, result, error_message
    ) VALUES (
      v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
      v_rule.conditions, v_rule.actions, 'failed',
      COALESCE(v_post_result->>'error_message', v_post_result->>'error', 'unknown')
    );
    INSERT INTO bookkeeping_audit_log(
      organization_id, entity_type, entity_id, action, actor_id,
      before_state, after_state, metadata
    ) VALUES (
      v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule_failed', v_actor,
      v_before, NULL,
      jsonb_build_object('rule_id', p_rule_id, 'error', v_post_result)
    );
    RETURN v_post_result;
  END IF;

  UPDATE bank_transactions
     SET rule_id = p_rule_id,
         category = COALESCE(v_category, category),
         status = 'MATCHED'
   WHERE id = p_bank_transaction_id;

  INSERT INTO bank_rule_executions(
    organization_id, bank_rule_id, bank_transaction_id, executed_by,
    matched_conditions, applied_actions, result
  ) VALUES (
    v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
    v_rule.conditions, v_rule.actions, 'success'
  );

  UPDATE bank_rules
     SET times_applied = COALESCE(times_applied, 0) + 1,
         last_applied_at = now()
   WHERE id = p_rule_id;

  INSERT INTO bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule', v_actor,
    v_before,
    jsonb_build_object('rule_id', p_rule_id, 'account_id', v_account_id,
                       'vat_code_id', v_vat_code_id, 'category', v_category, 'status', 'MATCHED'),
    jsonb_build_object('post_result', v_post_result, 'rule_source', v_rule.source)
  );

  RETURN v_post_result;
END;
$$;


--
-- Name: apply_ch_diff(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ch_diff(p_diff_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_diff record;
BEGIN
  SELECT * INTO v_diff FROM public.companies_house_diff_staging WHERE id = p_diff_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Diff not found'; END IF;
  IF NOT user_has_organization_access(v_diff.organization_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF v_diff.status <> 'pending' THEN RAISE EXCEPTION 'Diff already decided'; END IF;
  IF p_decision NOT IN ('accept','reject') THEN RAISE EXCEPTION 'Invalid decision'; END IF;

  IF p_decision = 'accept' AND v_diff.company_id IS NOT NULL THEN
    CASE v_diff.field_path
      WHEN 'registered_office_address' THEN
        UPDATE public.companies
          SET registered_office_address = v_diff.incoming_value
          WHERE id = v_diff.company_id;
      WHEN 'sic_codes' THEN
        UPDATE public.companies
          SET sic_codes = CASE
            WHEN v_diff.incoming_value IS NULL OR jsonb_typeof(v_diff.incoming_value) = 'null' THEN NULL
            ELSE ARRAY(SELECT jsonb_array_elements_text(v_diff.incoming_value))
          END
          WHERE id = v_diff.company_id;
      WHEN 'company_type' THEN
        UPDATE public.companies
          SET company_type = NULLIF(v_diff.incoming_value #>> '{}', '')
          WHERE id = v_diff.company_id;
      WHEN 'confirmation_statement_made_up_to' THEN
        UPDATE public.companies
          SET confirmation_statement_made_up_to = NULLIF(v_diff.incoming_value #>> '{}', '')::date
          WHERE id = v_diff.company_id;
      WHEN 'confirmation_statement_next_due' THEN
        UPDATE public.companies
          SET confirmation_statement_next_due = NULLIF(v_diff.incoming_value #>> '{}', '')::date
          WHERE id = v_diff.company_id;
      ELSE
        -- Unknown field path: record but do not write
        NULL;
    END CASE;
  END IF;

  UPDATE public.companies_house_diff_staging
    SET status = CASE WHEN p_decision = 'accept' THEN 'accepted' ELSE 'rejected' END,
        decided_by = auth.uid(),
        decided_at = now(),
        decision_notes = p_notes
  WHERE id = p_diff_id;
END;
$$;


--
-- Name: apply_client_override(uuid, uuid, uuid, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_client_override(p_org_id uuid, p_client_id uuid, p_rule_id uuid, p_chaser_policy_id uuid, p_enabled boolean, p_config jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT user_in_organization(auth.uid(), p_org_id) THEN RAISE EXCEPTION 'not a member'; END IF;
  INSERT INTO automation_client_overrides(organization_id, client_id, rule_id, chaser_policy_id, enabled, config_overrides)
  VALUES (p_org_id, p_client_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
  ON CONFLICT (client_id, rule_id) WHERE rule_id IS NOT NULL
  DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    INSERT INTO automation_client_overrides(organization_id, client_id, rule_id, chaser_policy_id, enabled, config_overrides)
    VALUES (p_org_id, p_client_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
    ON CONFLICT (client_id, chaser_policy_id) WHERE chaser_policy_id IS NOT NULL
    DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;$$;


--
-- Name: apply_job_override(uuid, uuid, uuid, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_job_override(p_org_id uuid, p_job_id uuid, p_rule_id uuid, p_chaser_policy_id uuid, p_enabled boolean, p_config jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT user_in_organization(auth.uid(), p_org_id) THEN RAISE EXCEPTION 'not a member'; END IF;
  INSERT INTO automation_job_overrides(organization_id, job_id, rule_id, chaser_policy_id, enabled, config_overrides)
  VALUES (p_org_id, p_job_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
  ON CONFLICT (job_id, rule_id) WHERE rule_id IS NOT NULL
  DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    INSERT INTO automation_job_overrides(organization_id, job_id, rule_id, chaser_policy_id, enabled, config_overrides)
    VALUES (p_org_id, p_job_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
    ON CONFLICT (job_id, chaser_policy_id) WHERE chaser_policy_id IS NOT NULL
    DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;$$;


--
-- Name: apply_opening_balances(uuid, uuid, uuid, date, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_opening_balances(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_opening_date date, p_entries jsonb, p_lock_period boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_source_id uuid := gen_random_uuid();
  v_actor uuid := auth.uid();
BEGIN
  v_result := post_to_ledger(
    p_organization_id, p_client_id, p_company_id,
    p_opening_date, 'OPENING-BAL', 'Opening balances', 'OPENING_BALANCE',
    'OPENING_BALANCE', v_source_id, 'GBP', 1.0, v_actor, p_entries
  );

  IF COALESCE((v_result->>'success')::boolean, false) AND p_lock_period THEN
    INSERT INTO period_locks (organization_id, client_id, company_id, lock_date, locked_by, reason)
    VALUES (p_organization_id, p_client_id, p_company_id, p_opening_date, v_actor, 'Opening balance period lock')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: approve_bill(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_bill(p_bill_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bill RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_creditors_id uuid;
  v_vat_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF v_bill.status <> 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_status', 'error_message', 'Bill is not in draft status');
  END IF;
  IF v_bill.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_posted', 'error_message', 'Bill already posted');
  END IF;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  SELECT id INTO v_creditors_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE')
   LIMIT 1;
  IF v_creditors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Creditors control account not found');
  END IF;

  SELECT id INTO v_vat_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('VAT_CONTROL','VAT')
   LIMIT 1;

  -- DR expense accounts per line (net)
  FOR v_line IN SELECT * FROM bill_lines WHERE bill_id = p_bill_id ORDER BY line_number LOOP
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_line.account_id,
      'debit', v_line.net_amount,
      'credit', NULL,
      'description', 'Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8)) || ': ' || v_line.description,
      'vat_code_id', v_line.vat_code_id
    ));
  END LOOP;

  IF v_bill.total_vat > 0 AND v_vat_id IS NOT NULL THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_vat_id,
      'debit', v_bill.total_vat,
      'credit', NULL,
      'description', 'VAT on Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
    ));
  END IF;

  -- CR Trade Creditors (gross)
  v_entries := v_entries || jsonb_build_array(jsonb_build_object(
    'account_id', v_creditors_id,
    'debit', NULL,
    'credit', v_bill.total_gross,
    'description', 'Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
  ));

  v_post_result := post_to_ledger(
    p_organization_id := v_bill.organization_id,
    p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_bill.issue_date,
    p_reference       := v_bill.bill_number,
    p_description     := 'BILL posting',
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'BILL',
    p_source_id       := p_bill_id,
    p_currency        := COALESCE(v_bill.currency,'GBP'),
    p_fx_rate         := COALESCE(v_bill.exchange_rate,1.0),
    p_created_by      := v_uid,
    p_entries         := v_entries
  );

  IF NOT (v_post_result->>'success')::boolean THEN
    RAISE EXCEPTION 'Posting failed: %', v_post_result->>'error_message'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE bills
     SET status = 'AWAITING_PAYMENT',
         is_posted = true,
         posted_at = now(),
         posted_by = v_uid,
         updated_at = now()
   WHERE id = p_bill_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_post_result->>'journal_id');
END;
$$;


--
-- Name: approve_bill_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_bill_safe(p_bill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_bill record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_bill.organization_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Manager role required');
  END IF;

  IF v_bill.status != 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT bills can be approved');
  END IF;

  UPDATE bills SET status = 'APPROVED', approved_at = now(), approved_by = v_user_id
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_bill.organization_id, 'bill', p_bill_id, 'approved', v_user_id);

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;


--
-- Name: approve_credit_note(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_credit_note(p_credit_note_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cn record;
  v_org uuid;
  v_entity_type text;
  v_entity_id uuid;
  v_control_subtypes text[];
  v_control_account uuid;
  v_vat_account uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line record;
  v_post_result jsonb;
  v_journal_id uuid;
  v_membership boolean;
BEGIN
  SELECT * INTO v_cn FROM credit_notes WHERE id = p_credit_note_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note not found');
  END IF;

  IF v_cn.status <> 'DRAFT' OR v_cn.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note is not in DRAFT status');
  END IF;

  v_org := v_cn.organization_id;

  -- Membership / tenancy check
  SELECT EXISTS(
    SELECT 1 FROM organization_users
    WHERE organization_id = v_org
      AND user_id = COALESCE(p_user_id, auth.uid())
  ) INTO v_membership;
  IF NOT v_membership THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Not authorized for this organization');
  END IF;

  IF v_cn.client_id IS NOT NULL THEN
    v_entity_type := 'client';
    v_entity_id := v_cn.client_id;
  ELSIF v_cn.company_id IS NOT NULL THEN
    v_entity_type := 'company';
    v_entity_id := v_cn.company_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note has no entity scope');
  END IF;

  -- Resolve control account
  IF v_cn.credit_note_type = 'SALES' THEN
    v_control_subtypes := ARRAY['TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE'];
  ELSE
    v_control_subtypes := ARRAY['TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE'];
  END IF;

  SELECT id INTO v_control_account
  FROM bookkeeping_accounts
  WHERE organization_id = v_org
    AND is_active = true
    AND is_control_account = true
    AND account_subtype = ANY(v_control_subtypes)
    AND ((v_entity_type = 'client' AND client_id = v_entity_id)
      OR (v_entity_type = 'company' AND company_id = v_entity_id))
  LIMIT 1;

  IF v_control_account IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_message',
      'No control account configured for ' || v_cn.credit_note_type);
  END IF;

  -- Resolve VAT control if needed
  IF v_cn.vat_total > 0 THEN
    SELECT id INTO v_vat_account
    FROM bookkeeping_accounts
    WHERE organization_id = v_org
      AND is_active = true
      AND is_control_account = true
      AND account_subtype IN ('VAT_CONTROL','VAT')
      AND ((v_entity_type = 'client' AND client_id = v_entity_id)
        OR (v_entity_type = 'company' AND company_id = v_entity_id))
    LIMIT 1;
    IF v_vat_account IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'VAT control account not configured');
    END IF;
  END IF;

  -- Build entries. SALES credit note REVERSES original sales:
  --   Dr Sales (net), Dr VAT, Cr Debtors (gross)
  -- PURCHASE credit note REVERSES original purchase:
  --   Cr Expense (net), Cr VAT, Dr Creditors (gross)
  FOR v_line IN
    SELECT account_id, net_amount, vat_amount
    FROM credit_note_lines
    WHERE credit_note_id = p_credit_note_id
  LOOP
    IF v_line.account_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'Credit note line missing account');
    END IF;
    IF v_cn.credit_note_type = 'SALES' THEN
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_line.account_id,
        'debit', v_line.net_amount,
        'credit', NULL,
        'description', 'Sales credit',
        'vat_code_id', NULL
      ));
    ELSE
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_line.account_id,
        'debit', NULL,
        'credit', v_line.net_amount,
        'description', 'Purchase credit',
        'vat_code_id', NULL
      ));
    END IF;
  END LOOP;

  IF v_cn.vat_total > 0 THEN
    IF v_cn.credit_note_type = 'SALES' THEN
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_vat_account, 'debit', v_cn.vat_total, 'credit', NULL,
        'description', 'VAT on sales credit', 'vat_code_id', NULL));
    ELSE
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_vat_account, 'debit', NULL, 'credit', v_cn.vat_total,
        'description', 'VAT on purchase credit', 'vat_code_id', NULL));
    END IF;
  END IF;

  -- Control account leg
  IF v_cn.credit_note_type = 'SALES' THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_control_account, 'debit', NULL, 'credit', v_cn.total,
      'description', 'Debtor reduction', 'vat_code_id', NULL));
  ELSE
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_control_account, 'debit', v_cn.total, 'credit', NULL,
      'description', 'Creditor reduction', 'vat_code_id', NULL));
  END IF;

  -- Post atomically
  v_post_result := public.post_to_ledger(
    p_organization_id := v_org,
    p_client_id       := CASE WHEN v_entity_type = 'client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type = 'company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_cn.issue_date,
    p_reference       := COALESCE(v_cn.credit_note_number, 'CN-' || left(v_cn.id::text, 8)),
    p_description     := 'Credit Note ' || COALESCE(v_cn.credit_note_number, ''),
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'CREDIT_NOTE',
    p_source_id       := v_cn.id,
    p_currency        := v_cn.currency,
    p_fx_rate         := COALESCE(v_cn.fx_rate, 1.0),
    p_created_by      := COALESCE(p_user_id, auth.uid()),
    p_entries         := v_entries
  );

  IF NOT COALESCE((v_post_result->>'success')::boolean, false) THEN
    RETURN jsonb_build_object('success', false,
      'error_message', COALESCE(v_post_result->>'error', 'Posting failed'));
  END IF;

  v_journal_id := (v_post_result->>'journal_id')::uuid;

  UPDATE credit_notes
  SET status = 'APPROVED',
      is_posted = true,
      posted_at = now(),
      posted_by = COALESCE(p_user_id, auth.uid()),
      journal_id = v_journal_id,
      remaining_allocation = total,
      updated_at = now(),
      updated_by = COALESCE(p_user_id, auth.uid())
  WHERE id = p_credit_note_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: approve_filing_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_filing_safe(p_filing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing record;
BEGIN
  -- Fetch filing
  SELECT * INTO v_filing FROM filings WHERE id = p_filing_id;
  
  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Filing not found');
  END IF;
  
  -- Check permission
  IF NOT can_approve_filings(auth.uid(), v_filing.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Only managers and above can approve filings');
  END IF;
  
  -- Update filing
  UPDATE filings SET 
    status = 'approved_by_client',
    approved_by = auth.uid(),
    approved_at = now()
  WHERE id = p_filing_id;
  
  -- Write audit log
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, field_name, old_value, new_value, user_id)
  VALUES (v_filing.organization_id, 'filing', p_filing_id, 'approve', 'status', v_filing.status, 'approved_by_client', auth.uid());
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: approve_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_invoice(p_invoice_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_debtors_id uuid;
  v_vat_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Invoice not found');
  END IF;

  IF v_invoice.status <> 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_status', 'error_message', 'Invoice is not in draft status');
  END IF;
  IF v_invoice.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_posted', 'error_message', 'Invoice already posted');
  END IF;

  v_entity_type := CASE WHEN v_invoice.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_invoice.client_id, v_invoice.company_id);

  -- Resolve control accounts (structured taxonomy, not name matching)
  SELECT id INTO v_debtors_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE')
   LIMIT 1;
  IF v_debtors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Debtors control account not found');
  END IF;

  SELECT id INTO v_vat_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('VAT_CONTROL','VAT')
   LIMIT 1;

  -- DR Trade Debtors (gross)
  v_entries := v_entries || jsonb_build_array(jsonb_build_object(
    'account_id', v_debtors_id,
    'debit', v_invoice.total_gross,
    'credit', NULL,
    'description', 'Sales Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8)) || ': ' || COALESCE(v_invoice.contact_name,'')
  ));

  -- CR Sales accounts per line (net)
  FOR v_line IN SELECT * FROM invoice_lines WHERE invoice_id = p_invoice_id ORDER BY line_number LOOP
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_line.account_id,
      'debit', NULL,
      'credit', v_line.net_amount,
      'description', COALESCE(v_invoice.invoice_number,'') || ': ' || v_line.description,
      'vat_code_id', v_line.vat_code_id
    ));
  END LOOP;

  -- CR VAT Control (total VAT)
  IF v_invoice.total_vat > 0 AND v_vat_id IS NOT NULL THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_vat_id,
      'debit', NULL,
      'credit', v_invoice.total_vat,
      'description', 'VAT on Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
    ));
  END IF;

  v_post_result := post_to_ledger(
    p_organization_id := v_invoice.organization_id,
    p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_invoice.issue_date,
    p_reference       := v_invoice.invoice_number,
    p_description     := 'INVOICE posting',
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'INVOICE',
    p_source_id       := p_invoice_id,
    p_currency        := COALESCE(v_invoice.currency,'GBP'),
    p_fx_rate         := COALESCE(v_invoice.exchange_rate,1.0),
    p_created_by      := v_uid,
    p_entries         := v_entries
  );

  IF NOT (v_post_result->>'success')::boolean THEN
    RAISE EXCEPTION 'Posting failed: %', v_post_result->>'error_message'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE invoices
     SET status = 'AWAITING_PAYMENT',
         is_posted = true,
         posted_at = now(),
         posted_by = v_uid,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_post_result->>'journal_id');
END;
$$;


--
-- Name: approve_onboarding_transactional(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_onboarding_transactional(p_application_id uuid, p_actor uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_app record;
  v_core jsonb;
  v_company_id uuid;
  v_client_id uuid;
  v_snapshot_exists boolean;
  v_company_name text;
  v_existing_utr text;
  v_existing_vat text;
  v_paye text;
  v_person jsonb;
  v_target_id uuid;
  v_action text;
  v_name text;
  v_first text;
  v_last text;
  v_existing_dob date;
  v_existing_nino text;
  v_existing_person_utr text;
  v_existing_home text;
  v_idx int := 0;
  v_persons_merged int := 0;
  v_persons_created int := 0;
  v_persons_skipped int := 0;
  v_fields_recorded int := 0;
  v_resolved jsonb := '[]'::jsonb;
  v_masked_persons jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app.id IS NULL THEN
    RAISE EXCEPTION 'onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_app.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.onboarding_approval_snapshots WHERE application_id = p_application_id
  ) INTO v_snapshot_exists;

  IF v_app.status = 'approved' AND v_snapshot_exists THEN
    RETURN jsonb_build_object(
      'idempotent', true,
      'application_id', p_application_id,
      'status', 'approved'
    );
  END IF;

  BEGIN
    SELECT public.lifecycle_approve_onboarding(p_application_id) INTO v_core;

    v_company_id := coalesce(v_app.company_id, (v_core->>'company_id')::uuid);
    v_client_id  := coalesce(v_app.client_id,  (v_core->>'client_id')::uuid);

    IF v_company_id IS NOT NULL THEN
      SELECT company_name, utr, vat_number
        INTO v_company_name, v_existing_utr, v_existing_vat
        FROM public.companies WHERE id = v_company_id;

      IF nullif(v_app.utr, '') IS NOT NULL AND (v_existing_utr IS NULL OR v_existing_utr = '') THEN
        UPDATE public.companies SET utr = v_app.utr WHERE id = v_company_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'company', v_company_id, 'company.utr',
          v_existing_utr, v_app.utr, p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_app.vat_number, '') IS NOT NULL AND (v_existing_vat IS NULL OR v_existing_vat = '') THEN
        UPDATE public.companies SET vat_number = v_app.vat_number WHERE id = v_company_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'company', v_company_id, 'company.vat_number',
          v_existing_vat, v_app.vat_number, p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      v_paye := nullif(v_app.paye_reference, '');
      IF v_paye IS NOT NULL THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.paye_schemes
          WHERE company_id = v_company_id AND employer_paye_reference = v_paye
        ) THEN
          INSERT INTO public.paye_schemes (
            organization_id, company_id, employer_paye_reference, name
          )
          VALUES (
            v_app.organization_id, v_company_id, v_paye,
            coalesce(v_company_name, 'PAYE Scheme')
          );
          PERFORM public.governance_record_merge_field(
            v_app.organization_id, 'company', v_company_id, 'company.paye_reference',
            NULL, v_paye, p_actor);
          v_fields_recorded := v_fields_recorded + 1;
        END IF;
      END IF;
    END IF;

    FOR v_person IN
      SELECT value FROM jsonb_array_elements(coalesce(v_app.personal_details, '[]'::jsonb))
    LOOP
      v_target_id := NULL;
      v_action := NULL;

      IF nullif(v_person->>'person_id', '') IS NOT NULL THEN
        SELECT id INTO v_target_id FROM public.company_persons
          WHERE id = (v_person->>'person_id')::uuid
            AND organization_id = v_app.organization_id;
        IF v_target_id IS NOT NULL THEN v_action := 'merged'; END IF;
      ELSIF nullif(v_person->>'ch_officer_id', '') IS NOT NULL THEN
        SELECT id INTO v_target_id FROM public.company_persons
          WHERE organization_id = v_app.organization_id
            AND ch_officer_id = v_person->>'ch_officer_id'
          LIMIT 1;
        IF v_target_id IS NOT NULL THEN v_action := 'merged'; END IF;
      END IF;

      IF v_target_id IS NULL THEN
        v_name := regexp_replace(trim(coalesce(v_person->>'name', '')), '\s+', ' ', 'g');

        IF v_name = ''
           AND nullif(v_person->>'person_id', '') IS NULL
           AND nullif(v_person->>'ch_officer_id', '') IS NULL THEN
          v_persons_skipped := v_persons_skipped + 1;
          v_idx := v_idx + 1;
          CONTINUE;
        END IF;

        v_first := split_part(v_name, ' ', 1);
        IF position(' ' in v_name) = 0 THEN
          v_last := v_first;
        ELSE
          v_last := trim(substr(v_name, position(' ' in v_name) + 1));
        END IF;
        IF v_last IS NULL OR v_last = '' THEN v_last := v_first; END IF;

        INSERT INTO public.company_persons (organization_id, first_name, last_name)
        VALUES (v_app.organization_id, v_first, v_last)
        RETURNING id INTO v_target_id;
        v_action := 'created';
        v_persons_created := v_persons_created + 1;
      ELSE
        v_persons_merged := v_persons_merged + 1;
      END IF;

      SELECT date_of_birth, nino, utr, residential_address_line_1
        INTO v_existing_dob, v_existing_nino, v_existing_person_utr, v_existing_home
        FROM public.company_persons WHERE id = v_target_id;

      IF nullif(v_person->>'date_of_birth', '') IS NOT NULL AND v_existing_dob IS NULL THEN
        UPDATE public.company_persons
          SET date_of_birth = (v_person->>'date_of_birth')::date
          WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.date_of_birth',
          NULL, v_person->>'date_of_birth', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'nino', '') IS NOT NULL AND (v_existing_nino IS NULL OR v_existing_nino = '') THEN
        UPDATE public.company_persons SET nino = v_person->>'nino' WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.nino',
          v_existing_nino, v_person->>'nino', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'utr', '') IS NOT NULL AND (v_existing_person_utr IS NULL OR v_existing_person_utr = '') THEN
        UPDATE public.company_persons SET utr = v_person->>'utr' WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.utr',
          v_existing_person_utr, v_person->>'utr', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'home_address', '') IS NOT NULL AND (v_existing_home IS NULL OR v_existing_home = '') THEN
        UPDATE public.company_persons
          SET residential_address_line_1 = v_person->>'home_address'
          WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.home_address',
          v_existing_home, v_person->>'home_address', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      v_resolved := v_resolved || jsonb_build_object(
        'index', v_idx, 'person_id', v_target_id, 'action', v_action);

      v_masked_persons := v_masked_persons || jsonb_build_object(
        'name', v_person->>'name',
        'role', v_person->>'role',
        'date_of_birth', public.governance_mask_value('person.date_of_birth', v_person->>'date_of_birth'),
        'nino', public.governance_mask_value('person.nino', v_person->>'nino'),
        'utr', public.governance_mask_value('person.utr', v_person->>'utr'),
        'home_address', public.governance_mask_value('person.home_address', v_person->>'home_address'),
        'person_id', v_person->>'person_id',
        'ch_officer_id', v_person->>'ch_officer_id'
      );

      v_idx := v_idx + 1;
    END LOOP;

    INSERT INTO public.onboarding_approval_snapshots (
      organization_id, application_id, created_by, snapshot
    )
    VALUES (
      v_app.organization_id, p_application_id, p_actor,
      jsonb_build_object(
        'provisional', jsonb_build_object(
          'application_id', p_application_id,
          'organization_id', v_app.organization_id,
          'client_id', v_client_id,
          'company_id', v_company_id,
          'lead_id', v_app.lead_id,
          'paye_reference', v_app.paye_reference,
          'vat_number', v_app.vat_number,
          'utr', v_app.utr,
          'ch_correction_note', v_app.ch_correction_note,
          'personal_details', v_masked_persons
        ),
        'resolved_persons', v_resolved,
        'approved_at', now(),
        'actor', p_actor
      )
    );

    UPDATE public.onboarding_applications
      SET approval_blocked_at = NULL, approval_blocked_reason = NULL
      WHERE id = p_application_id;

    RETURN v_core || jsonb_build_object(
      'governance', jsonb_build_object(
        'persons_merged', v_persons_merged,
        'persons_created', v_persons_created,
        'persons_skipped', v_persons_skipped,
        'fields_recorded', v_fields_recorded
      ),
      'snapshot_written', true
    );

  EXCEPTION WHEN OTHERS THEN
    UPDATE public.onboarding_applications
      SET approval_blocked_at = now(),
          approval_blocked_reason = left(SQLERRM, 500)
      WHERE id = p_application_id;
    RETURN jsonb_build_object(
      'approved', false,
      'blocked', true,
      'reason', left(SQLERRM, 500),
      'application_id', p_application_id
    );
  END;
END;
$$;


--
-- Name: approve_vat_return_for_filing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_vat_return_for_filing(_vat_return_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
  v_snapshot_id uuid := gen_random_uuid();
  v_hash text;
  v_payload jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Access denied: not authenticated';
  END IF;

  SELECT * INTO v_row FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VAT return not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_row.organization_id AND user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'Access denied: not a member of this organization';
  END IF;

  IF v_row.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'VAT return already submitted';
  END IF;

  IF v_row.filing_approved_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_approved', true,
      'model_snapshot_id', v_row.model_snapshot_id,
      'model_snapshot_hash', v_row.model_snapshot_hash,
      'filing_approved_at', v_row.filing_approved_at
    );
  END IF;

  v_payload := jsonb_build_object(
    'vat_return_id', v_row.id,
    'organization_id', v_row.organization_id,
    'client_id', v_row.client_id,
    'company_id', v_row.company_id,
    'period_start', v_row.period_start,
    'period_end', v_row.period_end,
    'box_1_vat_due_sales', v_row.box_1_vat_due_sales,
    'box_2_vat_due_acquisitions', v_row.box_2_vat_due_acquisitions,
    'box_3_total_vat_due', v_row.box_3_total_vat_due,
    'box_4_vat_reclaimed', v_row.box_4_vat_reclaimed,
    'box_5_net_vat', v_row.box_5_net_vat,
    'box_6_total_sales', v_row.box_6_total_sales,
    'box_7_total_purchases', v_row.box_7_total_purchases,
    'box_8_total_supplies_eu', v_row.box_8_total_supplies_eu,
    'box_9_total_acquisitions_eu', v_row.box_9_total_acquisitions_eu
  );

  v_hash := encode(digest(v_payload::text, 'sha256'), 'hex');

  UPDATE public.vat_returns
     SET filing_approved_at = now(),
         filing_approved_by = v_uid,
         model_snapshot_id = v_snapshot_id,
         model_snapshot_hash = v_hash,
         updated_at = now()
   WHERE id = _vat_return_id;

  RETURN jsonb_build_object(
    'ok', true,
    'model_snapshot_id', v_snapshot_id,
    'model_snapshot_hash', v_hash,
    'filing_approved_at', now()
  );
END;
$$;


--
-- Name: assert_no_locked_period_write(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_no_locked_period_write(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_date date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_period_locked(p_organization_id, p_client_id, p_company_id, p_date) THEN
    RAISE EXCEPTION 'Date % is in a locked period', p_date USING ERRCODE = 'check_violation';
  END IF;
END $$;


--
-- Name: audit_bookkeeping_accounts_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_bookkeeping_accounts_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_entity_type text;
  v_entity_id uuid;
BEGIN
  v_entity_type := CASE WHEN COALESCE(NEW.client_id, OLD.client_id) IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(NEW.client_id, OLD.client_id, NEW.company_id, OLD.company_id, COALESCE(NEW.organization_id, OLD.organization_id));

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, before_state, after_state)
  VALUES (COALESCE(NEW.organization_id, OLD.organization_id),
          v_entity_type, v_entity_id,
          'account_' || lower(TG_OP), auth.uid(),
          CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END);
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: audit_journals_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_journals_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_entity_type text;
  v_entity_id uuid;
  v_org uuid;
BEGIN
  v_org := COALESCE(NEW.organization_id, OLD.organization_id);
  v_entity_type := CASE WHEN COALESCE(NEW.client_id, OLD.client_id) IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(NEW.client_id, OLD.client_id, NEW.company_id, OLD.company_id);

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, before_state, after_state)
  VALUES (v_org, v_entity_type, v_entity_id,
          'journal_' || lower(TG_OP), auth.uid(),
          CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END);
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: audit_period_locks_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_period_locks_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_entity_type text;
  v_entity_id uuid;
BEGIN
  v_entity_type := CASE WHEN COALESCE(NEW.client_id, OLD.client_id) IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(NEW.client_id, OLD.client_id, NEW.company_id, OLD.company_id);

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, before_state, after_state, reason)
  VALUES (COALESCE(NEW.organization_id, OLD.organization_id),
          v_entity_type, v_entity_id,
          'period_lock_' || lower(TG_OP), auth.uid(),
          CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END,
          COALESCE(NEW.reason, OLD.reason));
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: auto_verify_aml_on_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_verify_aml_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'approved' AND COALESCE(OLD.status,'') <> 'approved' THEN
    IF COALESCE(NEW.aml_status,'') NOT IN ('verified','failed','manual_review') THEN
      NEW.aml_status := 'verified';
    END IF;
    IF NEW.aml_verified_at IS NULL THEN
      NEW.aml_verified_at := NOW();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: automation_dry_run(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_dry_run(p_rule_id uuid, p_sample_event jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_rule RECORD;
  v_org_id UUID;
  v_would_trigger BOOLEAN := false;
  v_trigger_reason TEXT := '';
  v_actions JSONB := '[]'::JSONB;
  v_placeholders JSONB := '{}'::JSONB;
  v_rate_limit JSONB;
  v_trigger_config JSONB;
  v_event_type TEXT;
  v_entity_type TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rule not found');
  END IF;

  v_org_id := v_rule.organization_id;
  IF NOT user_in_organization(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  v_trigger_config := COALESCE(v_rule.trigger_config, '{}'::JSONB);
  
  -- Extract expected event/entity from sample or trigger config
  IF p_sample_event IS NOT NULL THEN
    v_event_type := p_sample_event->>'event_type';
    v_entity_type := p_sample_event->>'entity_type';
  ELSE
    v_event_type := v_rule.trigger_type;
    v_entity_type := v_trigger_config->>'entity_type';
  END IF;

  -- Evaluate trigger conditions
  IF v_rule.trigger_type = v_event_type THEN
    v_would_trigger := true;
    v_trigger_reason := 'Event type matches rule trigger: ' || v_rule.trigger_type;
    
    -- Check additional conditions from trigger_config
    IF v_trigger_config ? 'status_from' AND p_sample_event IS NOT NULL THEN
      IF p_sample_event->'old_value'->>'status' != v_trigger_config->>'status_from' THEN
        v_would_trigger := false;
        v_trigger_reason := 'Status from condition not met';
      END IF;
    END IF;
    
    IF v_trigger_config ? 'status_to' AND p_sample_event IS NOT NULL THEN
      IF p_sample_event->'new_value'->>'status' != v_trigger_config->>'status_to' THEN
        v_would_trigger := false;
        v_trigger_reason := 'Status to condition not met';
      END IF;
    END IF;
  ELSE
    v_trigger_reason := 'Event type ' || COALESCE(v_event_type, 'NULL') || ' does not match rule trigger: ' || v_rule.trigger_type;
  END IF;

  -- Build actions array with resolved config
  v_actions := jsonb_build_array(
    jsonb_build_object(
      'action_type', v_rule.action_type,
      'action_config', v_rule.action_config,
      'email_mode', COALESCE(v_rule.email_mode, 'queue')
    )
  );

  -- Build sample placeholders
  v_placeholders := jsonb_build_object(
    'client.first_name', '{{client.first_name}}',
    'client.last_name', '{{client.last_name}}',
    'company.company_name', '{{company.company_name}}',
    'job.name', '{{job.name}}',
    'deadline.due_date', '{{deadline.due_date}}'
  );

  -- Check rate limits
  SELECT jsonb_build_object(
    'rule_hour_count', COALESCE((SELECT action_count FROM automation_rate_limits 
      WHERE organization_id = v_org_id AND automation_rule_id = p_rule_id 
      AND window_type = 'hour' AND window_start > now() - interval '1 hour'), 0),
    'rule_hour_limit', 25,
    'rule_day_count', COALESCE((SELECT action_count FROM automation_rate_limits 
      WHERE organization_id = v_org_id AND automation_rule_id = p_rule_id 
      AND window_type = 'day' AND window_start > now() - interval '1 day'), 0),
    'rule_day_limit', 150,
    'org_hour_count', COALESCE((SELECT SUM(action_count) FROM automation_rate_limits 
      WHERE organization_id = v_org_id AND automation_rule_id IS NULL 
      AND window_type = 'hour' AND window_start > now() - interval '1 hour'), 0),
    'org_hour_limit', 250,
    'org_day_count', COALESCE((SELECT SUM(action_count) FROM automation_rate_limits 
      WHERE organization_id = v_org_id AND automation_rule_id IS NULL 
      AND window_type = 'day' AND window_start > now() - interval '1 day'), 0),
    'org_day_limit', 1500
  ) INTO v_rate_limit;

  -- Log dry run to audit
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_org_id, 'automation_rule', p_rule_id, 'dry_run_performed', v_user_id,
    jsonb_build_object('sample_event', p_sample_event, 'would_trigger', v_would_trigger));

  RETURN jsonb_build_object(
    'success', true,
    'would_trigger', v_would_trigger,
    'trigger_reason', v_trigger_reason,
    'resolved_placeholders', v_placeholders,
    'actions_would_execute', v_actions,
    'rule_name', v_rule.name,
    'email_mode', COALESCE(v_rule.email_mode, 'queue'),
    'rate_limit_check', v_rate_limit
  );
END;
$$;


--
-- Name: automation_engine_enabled(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_engine_enabled(_engine text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT enabled FROM public.automation_engine_switches WHERE engine = _engine),
    false
  );
$$;


--
-- Name: backfill_quote_token_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_quote_token_org_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.organization_id IS NULL AND NEW.quote_id IS NOT NULL THEN
    SELECT organization_id INTO NEW.organization_id
    FROM public.quotes
    WHERE id = NEW.quote_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bank_rule_safety_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_rule_safety_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_action jsonb;
  v_has_vat boolean := false;
BEGIN
  -- Detect VAT sensitivity from actions
  IF NEW.actions IS NOT NULL THEN
    FOR v_action IN SELECT * FROM jsonb_array_elements(COALESCE(NEW.actions,'[]'::jsonb)) LOOP
      IF v_action->>'type' = 'set_vat_code' AND COALESCE(v_action->>'value','') <> '' THEN
        v_has_vat := true;
      END IF;
    END LOOP;
  END IF;
  NEW.vat_sensitive := v_has_vat;

  -- Portal-created rules can never auto-post and always require review
  IF NEW.source = 'portal' THEN
    NEW.auto_post := false;
    NEW.requires_review := true;
  END IF;

  -- VAT-sensitive rules default to requires_review unless caller explicitly
  -- set auto_post = true (accountant-confirmed automation).
  IF v_has_vat AND TG_OP = 'INSERT' AND NEW.auto_post IS NOT TRUE THEN
    NEW.requires_review := true;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: block_portal_vat_submit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_portal_vat_submit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_portal_user() THEN
    IF NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
       OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by
       OR NEW.hmrc_receipt IS DISTINCT FROM OLD.hmrc_receipt
       OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('submitted','accepted','filed')) THEN
      RAISE EXCEPTION 'Portal users cannot submit VAT returns' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: block_portal_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_portal_writes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_portal_user() THEN
    RAISE EXCEPTION 'Portal users cannot modify %', TG_TABLE_NAME USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: bookkeeping_accounts_protect_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookkeeping_accounts_protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF COALESCE(OLD.is_system_account, false) THEN
    RAISE EXCEPTION 'Cannot delete system account %', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM ledger_entries WHERE account_id = OLD.id LIMIT 1) THEN
    RAISE EXCEPTION 'Account % is referenced by ledger_entries', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM journal_lines WHERE account_id = OLD.id LIMIT 1) THEN
    RAISE EXCEPTION 'Account % is referenced by journal_lines', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: bulk_apply_active_bank_rules(uuid, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_apply_active_bank_rules(p_organization_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid, p_bank_account_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_member boolean;
  v_txn record;
  v_rule record;
  v_applied int := 0;
  v_skipped int := 0;
  v_failed int := 0;
  v_result jsonb;
  v_matches boolean;
BEGIN
  IF p_client_id IS NULL AND p_company_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_entity',
                              'error_message', 'Either client_id or company_id is required');
  END IF;

  SELECT user_in_organization(v_actor, p_organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Not a member of this organisation');
  END IF;

  FOR v_txn IN
    SELECT * FROM bank_transactions
     WHERE organization_id = p_organization_id
       AND (p_client_id IS NULL OR client_id = p_client_id)
       AND (p_company_id IS NULL OR company_id = p_company_id)
       AND (p_bank_account_id IS NULL OR bank_account_id = p_bank_account_id)
       AND upper(COALESCE(status,'')) = 'UNREVIEWED'
     ORDER BY transaction_date ASC
     LIMIT p_limit
  LOOP
    FOR v_rule IN
      SELECT * FROM bank_rules
       WHERE organization_id = p_organization_id
         AND is_active = true
         AND (client_id IS NULL OR client_id = v_txn.client_id)
         AND (company_id IS NULL OR company_id = v_txn.company_id)
         AND (bank_account_id IS NULL OR bank_account_id = v_txn.bank_account_id)
       ORDER BY priority ASC, created_at ASC
    LOOP
      -- Delegate conditions check to apply_bank_rule (it validates scope);
      -- here we just attempt application and accept first success.
      v_result := apply_bank_rule(v_txn.id, v_rule.id);
      IF (v_result->>'success')::boolean IS TRUE THEN
        v_applied := v_applied + 1;
        EXIT;
      ELSIF v_result->>'error_code' IN ('already_categorized','period_locked') THEN
        v_skipped := v_skipped + 1;
        EXIT;
      ELSE
        -- Try next rule for non-fatal mismatch errors
        IF v_result->>'error_code' NOT IN ('scope_mismatch','bank_account_mismatch','rule_inactive') THEN
          v_failed := v_failed + 1;
          EXIT;
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('success', true,
                            'applied', v_applied,
                            'skipped', v_skipped,
                            'failed', v_failed);
END;
$$;


--
-- Name: calculate_cash_vat_proportion(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_cash_vat_proportion(p_net_amount numeric, p_vat_amount numeric, p_paid_amount numeric, p_gross_amount numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE 
    WHEN p_gross_amount = 0 THEN 0
    ELSE (p_paid_amount / p_gross_amount) * p_vat_amount
  END;
$$;


--
-- Name: calculate_deadline(text, date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_deadline(filing_type text, period_start date, period_end date, metadata jsonb DEFAULT '{}'::jsonb) RETURNS date
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
-- System A (calculate_deadline) is THE active deadline engine; System B
-- (lifecycle_generate_deadlines_for_job + canonical_deadline_rules) is dormant/reference —
-- do not route jobs into B without the dedicated engine-consolidation effort.
DECLARE
  result_date DATE;
  ard DATE;
  made_up_date DATE;
  quarter_end DATE;
BEGIN
  CASE filing_type
    WHEN 'companies_house_accounts' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '9 months';

    WHEN 'companies_house_confirmation' THEN
      made_up_date := (metadata->>'made_up_date')::DATE;
      IF made_up_date IS NULL THEN
        made_up_date := period_end;
      END IF;
      result_date := made_up_date + INTERVAL '12 months';

    WHEN 'corporation_tax_filing' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '12 months';

    WHEN 'corporation_tax_payment' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '9 months' + INTERVAL '1 day';

    WHEN 'self_assessment' THEN
      result_date := DATE_TRUNC('year', period_end)::DATE + INTERVAL '1 year' + INTERVAL '1 month' - INTERVAL '1 day';
      IF EXTRACT(MONTH FROM period_end) < 4 THEN
        result_date := result_date - INTERVAL '1 year';
      END IF;

    WHEN 'mtd_quarter' THEN
      -- MTD-ITSA quarterly update: fixed statutory date = the 7th of the month AFTER the
      -- standard 5th-ending quarter-end (5 Jul→7 Aug, 5 Oct→7 Nov, 5 Jan→7 Feb, 5 Apr→7 May).
      -- Standard 5th-ending quarters only; the calendar-quarter election is out of scope for v1.
      result_date := (DATE_TRUNC('month', period_end) + INTERVAL '1 month' + INTERVAL '6 days')::DATE;

    WHEN 'mtd_itsa_final' THEN
      -- MTD-ITSA final declaration: 31 January following the tax year (mirrors self_assessment;
      -- a tax year ending 5 Apr 2026 → 31 Jan 2027).
      result_date := make_date(EXTRACT(YEAR FROM period_end)::int + 1, 1, 31);

    WHEN 'vat_return' THEN
      quarter_end := period_end;
      result_date := quarter_end + INTERVAL '1 month' + INTERVAL '7 days';

    WHEN 'payroll_fps' THEN
      result_date := period_end;

    WHEN 'payroll_eps' THEN
      result_date := DATE_TRUNC('month', period_end)::DATE + INTERVAL '1 month' + INTERVAL '18 days';

    ELSE
      result_date := period_end + INTERVAL '1 month';
  END CASE;

  RETURN result_date;
END;
$$;


--
-- Name: can_access_shared_mailbox(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_shared_mailbox(_user_id uuid, _org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_enabled BOOLEAN;
BEGIN
  SELECT shared_mailbox_enabled INTO v_enabled
  FROM org_settings
  WHERE organization_id = _org_id;
  
  IF v_enabled IS NOT TRUE THEN
    RETURN FALSE;
  END IF;
  
  -- Staff+ can access shared mailbox when enabled
  RETURN user_has_role_at_least(_user_id, _org_id, 'staff');
END;
$$;


