CREATE FUNCTION public.client_has_portal_access(check_user_id uuid, check_client_id uuid DEFAULT NULL::uuid, check_company_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
