--
-- Name: enforce_ct600_approval_before_filed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_ct600_approval_before_filed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  terminal_new boolean;
  terminal_old boolean;
  is_ct600 boolean;
  has_active_approval boolean;
BEGIN
  terminal_new := NEW.status IN ('submitted', 'filed', 'accepted');
  terminal_old := COALESCE(OLD.status, '') IN ('submitted', 'filed', 'accepted');

  -- Only enforce on a fresh transition INTO a terminal status.
  IF NOT terminal_new OR terminal_old THEN
    RETURN NEW;
  END IF;

  is_ct600 := lower(COALESCE(NEW.filing_type, '')) IN ('ct600', 'corporation_tax');
  IF NOT is_ct600 THEN
    RETURN NEW;
  END IF;

  IF NEW.model_snapshot_id IS NULL THEN
    RAISE EXCEPTION 'CT600 filing % cannot be marked % without an approved model snapshot',
      NEW.id, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.filing_approvals fa
    WHERE fa.filing_id = NEW.id
      AND fa.model_snapshot_id = NEW.model_snapshot_id
      AND COALESCE(fa.revoked_at, NULL) IS NULL
  ) INTO has_active_approval;

  IF NOT has_active_approval THEN
    RAISE EXCEPTION 'CT600 filing % cannot be marked % without an active accountant approval of the attached snapshot',
      NEW.id, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_ct600_filing_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_ct600_filing_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_terminal text[] := ARRAY['submitted','filed','accepted'];
BEGIN
  IF NEW.filing_type IN ('CT600','ct600','corporation_tax','CT600_HMRC','CT600_XML')
     AND NEW.status = ANY(v_terminal)
     AND COALESCE(OLD.status, '') <> ALL(v_terminal)
     AND NEW.model_snapshot_id IS NULL THEN
    RAISE EXCEPTION 'A CT600 cannot be marked submitted/filed without an approved filing snapshot. Approve it for filing first.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_period_lock_journals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_lock_journals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_locked BOOLEAN;
  v_journal_date DATE;
BEGIN
  -- Determine the date to check
  IF TG_OP = 'DELETE' THEN
    v_journal_date := OLD.journal_date;
  ELSE
    v_journal_date := NEW.journal_date;
  END IF;
  
  -- Check if period is locked
  v_is_locked := public.is_period_locked(
    COALESCE(NEW.organization_id, OLD.organization_id),
    COALESCE(NEW.client_id, OLD.client_id),
    COALESCE(NEW.company_id, OLD.company_id),
    v_journal_date
  );
  
  IF v_is_locked THEN
    -- Log the blocked attempt
    INSERT INTO public.audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      user_id,
      old_value,
      new_value,
      metadata
    ) VALUES (
      COALESCE(NEW.organization_id, OLD.organization_id),
      'journal',
      COALESCE(NEW.id, OLD.id),
      'period_lock_blocked',
      auth.uid(),
      CASE WHEN TG_OP = 'DELETE' OR TG_OP = 'UPDATE' THEN OLD.id::TEXT ELSE NULL END,
      CASE WHEN TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN NEW.id::TEXT ELSE NULL END,
      jsonb_build_object(
        'operation', TG_OP,
        'journal_date', v_journal_date,
        'reason', 'Period is locked'
      )
    );
    
    RAISE EXCEPTION 'Cannot % journal: period ending % is locked', 
      LOWER(TG_OP), v_journal_date;
  END IF;
  
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


--
-- Name: enforce_period_lock_ledger_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_lock_ledger_entries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
