$$;


--
-- Name: enforce_signatory_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_signatory_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_signatory THEN
    IF NEW.resigned_at IS NOT NULL THEN
      NEW.is_signatory := false;
    ELSIF (
      SELECT count(*) FROM public.company_officers
      WHERE company_id = NEW.company_id AND is_signatory AND id <> NEW.id
    ) >= 10 THEN
      RAISE EXCEPTION 'A company can have at most 10 signatories';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_vat_filing_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_vat_filing_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.status = 'submitted' AND COALESCE(OLD.status, '') <> 'submitted')
     OR (NEW.submitted_at IS NOT NULL AND OLD.submitted_at IS NULL) THEN
    IF NEW.model_snapshot_id IS NULL OR NEW.filing_approved_at IS NULL THEN
      RAISE EXCEPTION 'A VAT return cannot be submitted without an approved filing snapshot. Approve it for filing first.'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_email(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_email(queue_name text, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$$;


--
-- Name: enqueue_unsubscribe_token(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_unsubscribe_token(p_org_id uuid, p_email text, p_category text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_token text;
BEGIN
  v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  INSERT INTO email_unsubscribe_tokens(organization_id, email, token, category)
  VALUES (p_org_id, p_email, v_token, p_category);
  RETURN v_token;
END;$$;


--
-- Name: ensure_client_document_folder(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_client_document_folder(p_client_id uuid, p_folder_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_folder_id uuid;
  v_org uuid;
BEGIN
  IF p_client_id IS NULL OR p_folder_name IS NULL THEN
    RETURN NULL;
  END IF;

  -- Tolerate absence of document_folders table to avoid breaking environments
  IF to_regclass('public.document_folders') IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT organization_id INTO v_org FROM clients WHERE id = p_client_id;
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  EXECUTE format(
    'SELECT id FROM public.document_folders
       WHERE client_id = %L AND lower(name) = lower(%L)
       LIMIT 1', p_client_id, p_folder_name
  ) INTO v_folder_id;

  IF v_folder_id IS NOT NULL THEN
    RETURN v_folder_id;
  END IF;

  EXECUTE format(
    'INSERT INTO public.document_folders (organization_id, client_id, name)
       VALUES (%L, %L, %L) RETURNING id',
     v_org, p_client_id, p_folder_name
  ) INTO v_folder_id;

  RETURN v_folder_id;
END;
$$;


--
-- Name: ensure_default_templates_for_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_default_templates_for_org(_org_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inserted_count integer := 0;
BEGIN
  IF _org_id IS NULL THEN
    RETURN 0;
  END IF;

  WITH ins AS (
    INSERT INTO public.templates (
      organization_id, name, description, type, service, status,
      tags, content, requires_unsubscribe_link, required_merge_fields,
      recipient_rule, source_template_id, version_number
    )
    SELECT
      _org_id,
      sys.name,
      sys.description,
      sys.type,
      sys.service,
      'inactive',
      sys.tags,
      sys.content,
      sys.requires_unsubscribe_link,
      sys.required_merge_fields,
      sys.recipient_rule,
      sys.id,
      1
    FROM public.templates sys
    WHERE sys.organization_id IS NULL
    ON CONFLICT (organization_id, source_template_id)
      WHERE source_template_id IS NOT NULL AND organization_id IS NOT NULL
      DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO inserted_count FROM ins;

  RETURN inserted_count;
END;
$$;


--
-- Name: ensure_onboarding_access_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_onboarding_access_token() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.access_token IS NULL THEN
    NEW.access_token := public.gen_onboarding_access_token();
  END IF;
  IF NEW.access_token_expires_at IS NULL THEN
    NEW.access_token_expires_at := now() + interval '90 days';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: org_settings; Type: TABLE; Schema: public; Owner: -
