    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    business_hours_start time without time zone DEFAULT '09:00:00'::time without time zone,
    business_hours_end time without time zone DEFAULT '17:30:00'::time without time zone,
    business_days text[] DEFAULT ARRAY['monday'::text, 'tuesday'::text, 'wednesday'::text, 'thursday'::text, 'friday'::text],
    deadline_buffer_days_vat integer DEFAULT 7,
    deadline_buffer_days_sa integer DEFAULT 14,
    deadline_buffer_days_ct integer DEFAULT 14,
    sla_email_response_hours integer DEFAULT 24,
    sla_portal_message_hours integer DEFAULT 24,
    sla_internal_message_hours integer DEFAULT 8,
    sla_task_default_hours integer DEFAULT 72,
