    CONSTRAINT org_settings_email_default_mode_check CHECK ((email_default_mode = ANY (ARRAY['draft_by_default'::text, 'send_by_default'::text])))
);


--
-- Name: ensure_org_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_org_settings(_org_id uuid) RETURNS public.org_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings org_settings;
BEGIN
  SELECT * INTO v_settings FROM org_settings WHERE organization_id = _org_id;
  
  IF v_settings.organization_id IS NULL THEN
    INSERT INTO org_settings (organization_id)
    VALUES (_org_id)
    RETURNING * INTO v_settings;
  END IF;
  
  RETURN v_settings;
END;
$$;


--
-- Name: entity_has_active_bookkeeping(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_has_active_bookkeeping(_client_id uuid, _company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.engagements e
    JOIN public.services_catalog s ON s.id = e.service_id
    WHERE e.status = 'active'
      AND s.code IN ('BOOKKEEPING','BK-MONTHLY','BK-QUARTERLY')
      AND ((_client_id IS NOT NULL AND e.client_id = _client_id)
        OR (_company_id IS NOT NULL AND e.company_id = _company_id))
  );
$$;


--
-- Name: explain_bank_transaction(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explain_bank_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn RECORD;
  v_user_id UUID := auth.uid();
  v_result JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RAISE EXCEPTION 'Transaction is already %; unmatch first', v_txn.status;
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  v_before := to_jsonb(v_txn);

  v_result := public.post_bank_transaction(
    p_bank_transaction_id := p_bank_transaction_id,
    p_contra_account_id   := p_contra_account_id,
    p_vat_code_id         := p_vat_code_id,
    p_vat_amount          := COALESCE(p_vat_amount, 0),
    p_description         := COALESCE(p_description, v_txn.description)
  );

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'explain_bank_transaction', v_user_id,
    v_before,
    jsonb_build_object('contra_account_id', p_contra_account_id, 'vat_code_id', p_vat_code_id,
                       'vat_amount', p_vat_amount),
    jsonb_build_object('post_result', v_result)
  );

  RETURN v_result;
END;
$$;


--
-- Name: finalize_workpaper_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_workpaper_safe(p_workpaper_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_workpaper record;
  v_filing_id uuid;
BEGIN
  -- Fetch workpaper
  SELECT * INTO v_workpaper FROM workpaper_instances WHERE id = p_workpaper_id;
  
  IF v_workpaper.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Workpaper not found');
  END IF;
  
  -- Check permission
  IF NOT can_finalize_workpapers(auth.uid(), v_workpaper.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Only managers and above can finalize workpapers');
  END IF;
  
  -- Update workpaper
  UPDATE workpaper_instances SET 
    status = 'finalised',
    finalised_by = auth.uid(),
    finalised_at = now(),
    locked = true
  WHERE id = p_workpaper_id;
  
  -- Create filing record
  INSERT INTO filings (
    organization_id, job_id, workpaper_instance_id, client_id, company_id,
    filing_type, filing_body, period_start, period_end, tax_year,
    filing_data, status
  ) VALUES (
    v_workpaper.organization_id, v_workpaper.job_id, p_workpaper_id,
    v_workpaper.client_id, v_workpaper.company_id, v_workpaper.service_type,
    'HMRC', v_workpaper.period_start, v_workpaper.period_end,
    v_workpaper.period_label, v_workpaper.field_values, 'draft'
  )
  RETURNING id INTO v_filing_id;
  
  -- Write audit logs
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, field_name, old_value, new_value, user_id)
  VALUES (v_workpaper.organization_id, 'workpaper_instance', p_workpaper_id, 'finalise', 'status', v_workpaper.status, 'finalised', auth.uid());
  
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_workpaper.organization_id, 'filing', v_filing_id, 'create', auth.uid());
  
  RETURN jsonb_build_object('success', true, 'filing_id', v_filing_id);
END;
$$;


--
-- Name: find_entities_by_email(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_entities_by_email(_org_id uuid, _email text) RETURNS TABLE(entity_type text, entity_id uuid, entity_name text, match_source text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  -- Check client primary emails
  SELECT 
    'client'::TEXT as entity_type,
    c.id as entity_id,
    (c.first_name || ' ' || c.last_name)::TEXT as entity_name,
    'primary'::TEXT as match_source
  FROM clients c
  WHERE c.organization_id = _org_id
    AND LOWER(c.email) = LOWER(_email)
  
  UNION ALL
  
  -- Check company primary emails
  SELECT 
    'company'::TEXT,
    co.id,
    co.company_name::TEXT,
    'primary'::TEXT
  FROM companies co
  WHERE co.organization_id = _org_id
    AND LOWER(co.email) = LOWER(_email)
  
  UNION ALL
  
  -- Check contacts linked to clients
  SELECT DISTINCT
    'client'::TEXT,
    ct.client_id,
    (cl.first_name || ' ' || cl.last_name)::TEXT,
    'contact'::TEXT
  FROM contacts ct
  JOIN clients cl ON cl.id = ct.client_id
  WHERE ct.organization_id = _org_id
    AND LOWER(ct.email) = LOWER(_email)
    AND ct.client_id IS NOT NULL
  
  UNION ALL
  
  -- Check contacts linked to companies
  SELECT DISTINCT
    'company'::TEXT,
    ct.company_id,
    co.company_name::TEXT,
    'contact'::TEXT
  FROM contacts ct
  JOIN companies co ON co.id = ct.company_id
  WHERE ct.organization_id = _org_id
    AND LOWER(ct.email) = LOWER(_email)
    AND ct.company_id IS NOT NULL;
END;
$$;


--
-- Name: flag_engagement_letter_on_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flag_engagement_letter_on_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If service_id or service_config (containing fees) changed, flag EL required
  IF (OLD.service_id IS DISTINCT FROM NEW.service_id) OR
     (OLD.service_config IS DISTINCT FROM NEW.service_config) THEN
    NEW.engagement_letter_required := true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: flush_email_queue_now(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flush_email_queue_now(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  UPDATE public.email_queue
     SET scheduled_at = now(),
         updated_at = now()
   WHERE organization_id = p_organization_id
     AND status IN ('pending','queued')
     AND scheduled_at > now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'flushed', v_count);
END;
$$;


