$$;


--
-- Name: get_vat_9box_detail(uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vat_9box_detail(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_boxes jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = p_organization_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of organization %', p_organization_id;
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL)
     OR (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Exactly one of client_id or company_id must be provided';
  END IF;

  -- Pull invoice lines (sales) for the entity in the period
  WITH inv AS (
    SELECT
      il.id,
      i.issue_date AS tx_date,
      i.invoice_number AS doc_ref,
      'invoice'::text AS source_type,
      il.invoice_id AS source_id,
      il.description,
      COALESCE(vc.code, 'UNKNOWN')           AS vat_code,
      COALESCE(vc.rate, il.vat_rate, 0)      AS vat_rate,
      COALESCE(vc.vat_type, 'OUTPUT')        AS vat_type,
      ABS(COALESCE(il.net_amount,0))         AS net_amount,
      ABS(COALESCE(il.vat_amount,0))         AS vat_amount,
      'SALES'::text AS direction
    FROM public.invoice_lines il
    JOIN public.invoices i ON i.id = il.invoice_id
    LEFT JOIN public.vat_codes vc ON vc.id = il.vat_code_id
    WHERE i.organization_id = p_organization_id
      AND i.is_posted = true
      AND i.issue_date BETWEEN p_from AND p_to
      AND ( (p_client_id IS NOT NULL AND i.client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND i.company_id = p_company_id) )
  ),
  bil AS (
    SELECT
      bl.id,
      b.issue_date AS tx_date,
      b.bill_number AS doc_ref,
      'bill'::text AS source_type,
      bl.bill_id AS source_id,
      bl.description,
      COALESCE(vc.code, 'UNKNOWN')          AS vat_code,
      COALESCE(vc.rate, bl.vat_rate, 0)     AS vat_rate,
      COALESCE(vc.vat_type, 'INPUT')        AS vat_type,
      ABS(COALESCE(bl.net_amount,0))        AS net_amount,
      ABS(COALESCE(bl.vat_amount,0))        AS vat_amount,
      'PURCHASES'::text AS direction
    FROM public.bill_lines bl
    JOIN public.bills b ON b.id = bl.bill_id
    LEFT JOIN public.vat_codes vc ON vc.id = bl.vat_code_id
    WHERE b.organization_id = p_organization_id
      AND b.is_posted = true
      AND b.issue_date BETWEEN p_from AND p_to
      AND ( (p_client_id IS NOT NULL AND b.client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND b.company_id = p_company_id) )
  ),
  lines AS (
    SELECT * FROM inv UNION ALL SELECT * FROM bil
  ),
  -- Box mapping helper (mirrors src/lib/vat-ledger-aggregator.ts)
  mapped AS (
    SELECT
      l.*,
      CASE
        WHEN l.direction='SALES'     AND l.vat_code IN ('S20','S5','RC') THEN l.vat_amount ELSE 0 END AS box1,
      CASE
        WHEN l.direction='SALES'     AND l.vat_code = 'EU_GOODS'         THEN l.vat_amount ELSE 0 END AS box2,
      CASE
        WHEN l.direction='PURCHASES' AND l.vat_code IN ('P20','P5','RC','IMP','EU_GOODS') THEN l.vat_amount ELSE 0 END AS box4,
      CASE WHEN l.direction='SALES'     THEN l.net_amount ELSE 0 END AS box6,
      CASE WHEN l.direction='PURCHASES' THEN l.net_amount ELSE 0 END AS box7,
      CASE WHEN l.direction='SALES'     AND l.vat_code='EXP'      THEN l.net_amount ELSE 0 END AS box8,
      CASE WHEN l.direction='PURCHASES' AND l.vat_code='EU_GOODS' THEN l.net_amount ELSE 0 END AS box9
    FROM lines l
  ),
  totals AS (
    SELECT
      ROUND(SUM(box1)::numeric, 2) AS b1,
      ROUND(SUM(box2)::numeric, 2) AS b2,
      ROUND(SUM(box4)::numeric, 2) AS b4,
      ROUND(SUM(box6)::numeric, 0) AS b6,
      ROUND(SUM(box7)::numeric, 0) AS b7,
      ROUND(SUM(box8)::numeric, 0) AS b8,
      ROUND(SUM(box9)::numeric, 0) AS b9
    FROM mapped
  ),
  per_code AS (
    SELECT
      vat_code,
      MAX(vat_rate) AS vat_rate,
      MAX(vat_type) AS vat_type,
      COUNT(*)::int AS line_count,
      ROUND(SUM(net_amount)::numeric, 2) AS total_net,
      ROUND(SUM(vat_amount)::numeric, 2) AS total_vat,
      jsonb_agg(jsonb_build_object(
        'id', id,
        'tx_date', tx_date,
        'doc_ref', doc_ref,
        'source_type', source_type,
        'source_id', source_id,
        'description', description,
        'net_amount', net_amount,
        'vat_amount', vat_amount,
        'direction', direction
      ) ORDER BY tx_date, doc_ref) AS transactions
    FROM mapped
    GROUP BY vat_code
  )
  SELECT jsonb_build_object(
    'period_from', p_from,
    'period_to',   p_to,
    'organization_id', p_organization_id,
    'client_id',  p_client_id,
    'company_id', p_company_id,
    'boxes', (SELECT jsonb_build_object(
        'box1_vat_on_sales',           COALESCE(b1,0),
        'box2_vat_on_acquisitions',    COALESCE(b2,0),
        'box3_total_vat_due',          ROUND((COALESCE(b1,0)+COALESCE(b2,0))::numeric, 2),
        'box4_vat_reclaimed',          COALESCE(b4,0),
        'box5_net_vat_due',            ROUND(ABS((COALESCE(b1,0)+COALESCE(b2,0))-COALESCE(b4,0))::numeric, 2),
        'box6_total_sales_ex_vat',     COALESCE(b6,0),
        'box7_total_purchases_ex_vat', COALESCE(b7,0),
        'box8_goods_supplied_ex_vat',  COALESCE(b8,0),
        'box9_acquisitions_ex_vat',    COALESCE(b9,0)
      ) FROM totals),
    'codes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'vat_code', vat_code,
        'vat_rate', vat_rate,
        'vat_type', vat_type,
        'line_count', line_count,
        'total_net', total_net,
        'total_vat', total_vat,
        'transactions', transactions
      ) ORDER BY vat_code) FROM per_code), '[]'::jsonb),
    'generated_at', now()
  )
  INTO v_boxes;

  RETURN v_boxes;
END;
$$;


--
-- Name: governance_mask_value(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.governance_mask_value(p_field_key text, p_val text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_sens text;
BEGIN
  IF p_val IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT sensitivity INTO v_sens
    FROM public.data_requirements
    WHERE field_key = p_field_key;

  IF v_sens IS NULL OR v_sens = 'sensitive' THEN
    IF p_field_key IN ('person.nino', 'person.utr') THEN
      RETURN '••••' || right(p_val, 2);
    END IF;
    RETURN '••••';
  END IF;

  RETURN p_val;
END;
$$;


--
-- Name: FUNCTION governance_mask_value(p_field_key text, p_val text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.governance_mask_value(p_field_key text, p_val text) IS 'Masked form of a governed field value for audit storage. Mirrors src/lib/onboarding-approval-merge-model.ts::maskSensitiveValue — keep both in lockstep.';


--
-- Name: governance_record_merge_field(uuid, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.governance_record_merge_field(p_organization_id uuid, p_subject_kind text, p_subject_id uuid, p_field_key text, p_old_value text, p_new_value text, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO public.data_point_state (
    organization_id, subject_kind, subject_id, field_key, status, source, updated_at
  )
  VALUES (
    p_organization_id, p_subject_kind, p_subject_id, p_field_key, 'provided', 'client', now()
  )
  ON CONFLICT (organization_id, subject_kind, subject_id, field_key)
  DO UPDATE SET status = 'provided', source = 'client', updated_at = now();

  INSERT INTO public.data_audit_log (
    organization_id, subject_kind, subject_id, field_key,
    old_value_masked, new_value_masked, actor, origin, event_type
  )
  VALUES (
    p_organization_id, p_subject_kind, p_subject_id, p_field_key,
    public.governance_mask_value(p_field_key, p_old_value),
    public.governance_mask_value(p_field_key, p_new_value),
    p_actor, 'onboarding', 'onboarding_merge'
  );
END;
$$;


--
-- Name: grant_person_portal_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_person_portal_access(p_person_id uuid, p_user_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_linked_client_id uuid;
  v_target_user_id uuid;
  v_company record;
  v_granted int := 0;
  v_skipped int := 0;
  v_already_active boolean;
BEGIN
  SELECT organization_id, linked_client_id
  INTO v_organization_id, v_linked_client_id
  FROM public.company_persons WHERE id = p_person_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Person not found: %', p_person_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT id INTO v_target_user_id FROM auth.users WHERE email = p_user_email LIMIT 1;

  IF v_linked_client_id IS NOT NULL THEN
    v_already_active := false;
    IF v_target_user_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM public.portal_access
        WHERE client_id = v_linked_client_id
          AND user_id = v_target_user_id
          AND is_active
          AND status <> 'revoked'
      ) INTO v_already_active;
    END IF;

    IF v_already_active THEN
      v_skipped := v_skipped + 1;
    ELSE
      PERFORM public.lifecycle_grant_portal_access('client', v_linked_client_id, p_user_email);
      v_granted := v_granted + 1;
    END IF;
  END IF;

  FOR v_company IN
    SELECT DISTINCT company_id
    FROM public.company_officers
    WHERE person_id = p_person_id AND resigned_at IS NULL
  LOOP
    v_already_active := false;
    IF v_target_user_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM public.portal_access
        WHERE company_id = v_company.company_id
          AND user_id = v_target_user_id
          AND is_active
          AND status <> 'revoked'
      ) INTO v_already_active;
    END IF;

    IF v_already_active THEN
      v_skipped := v_skipped + 1;
    ELSE
      PERFORM public.lifecycle_grant_portal_access('company', v_company.company_id, p_user_email);
      v_granted := v_granted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'granted', v_granted,
    'skipped', v_skipped
  );
END;
$$;


--
-- Name: handle_accounts_snapshot_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_accounts_snapshot_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing RECORD;
  v_approval RECORD;
  v_ct_snapshot RECORD;
BEGIN
  -- Find all filings that reference this accounts snapshot
  FOR v_filing IN 
    SELECT f.* FROM public.filings f
    WHERE f.accounts_snapshot_id = OLD.id
  LOOP
    -- Revoke ACCOUNTS approval
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = v_filing.id 
      AND approval_scope = 'ACCOUNTS' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.id,
        OLD.snapshot_hash,
        NEW.id,
        NEW.snapshot_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'accounts_snapshot_update')
      );
    END LOOP;
    
    -- Revoke CT600 approval (CT depends on accounts)
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = v_filing.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        v_filing.ct_snapshot_id,
        NULL,
        NULL,
        NULL,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'accounts_snapshot_update', 'cascade', true)
      );
    END LOOP;
    
    -- Regress filing status
    PERFORM public.regress_filing_status(v_filing.id, 'UNDERLYING_ACCOUNTS_CHANGED');
  END LOOP;
  
  RETURN NEW;
END;
$$;


--
-- Name: handle_filing_snapshot_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_filing_snapshot_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_approval RECORD;
  v_old_accounts_hash TEXT;
  v_new_accounts_hash TEXT;
  v_old_ct_hash TEXT;
  v_new_ct_hash TEXT;
BEGIN
  -- Get snapshot hashes for audit
  IF OLD.accounts_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_old_accounts_hash 
    FROM public.accounts_model_snapshots WHERE id = OLD.accounts_snapshot_id;
  END IF;
  
  IF NEW.accounts_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_new_accounts_hash 
    FROM public.accounts_model_snapshots WHERE id = NEW.accounts_snapshot_id;
  END IF;
  
  IF OLD.ct_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_old_ct_hash 
    FROM public.ct_computation_snapshots WHERE id = OLD.ct_snapshot_id;
  END IF;
  
  IF NEW.ct_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_new_ct_hash 
    FROM public.ct_computation_snapshots WHERE id = NEW.ct_snapshot_id;
  END IF;

  -- Case A: Accounts snapshot changed - revoke BOTH approvals
  IF OLD.accounts_snapshot_id IS DISTINCT FROM NEW.accounts_snapshot_id THEN
    -- Revoke ACCOUNTS approval
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'ACCOUNTS' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.accounts_snapshot_id,
        v_old_accounts_hash,
        NEW.accounts_snapshot_id,
        v_new_accounts_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change')
      );
    END LOOP;
    
    -- Revoke CT600 approval (cascade)
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.ct_snapshot_id,
        v_old_ct_hash,
        NEW.ct_snapshot_id,
        v_new_ct_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change', 'cascade', true)
      );
    END LOOP;
    
    -- Regress status
    PERFORM public.regress_filing_status(NEW.id, 'UNDERLYING_ACCOUNTS_CHANGED');
    
  -- Case B: Only CT snapshot changed - revoke CT approval only
  ELSIF OLD.ct_snapshot_id IS DISTINCT FROM NEW.ct_snapshot_id THEN
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.ct_snapshot_id,
        v_old_ct_hash,
        NEW.ct_snapshot_id,
        v_new_ct_hash,
        'CT_COMPUTATION_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change')
      );
    END LOOP;
    
    -- Regress status only if not already filed
    IF NEW.status NOT IN ('filed', 'accepted', 'submitted') THEN
      PERFORM public.regress_filing_status(NEW.id, 'CT_COMPUTATION_CHANGED');
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, email, first_name, last_name)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'first_name', NEW.raw_user_meta_data->>'given_name'),
    COALESCE(NEW.raw_user_meta_data->>'last_name', NEW.raw_user_meta_data->>'family_name')
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: handle_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: has_any_role(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_any_role(_user_id uuid, _org_id uuid, _roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_users
    WHERE user_id = _user_id
      AND organization_id = _org_id
      AND role::text = ANY(_roles)
  )
$$;


--
-- Name: has_organization_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_organization_role(_org_id uuid, _role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users 
    WHERE user_id = auth.uid() 
      AND organization_id = _org_id
      AND role = _role
  );
$$;


--
-- Name: has_portal_role(uuid, public.portal_role, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_portal_role(_user_id uuid, _role public.portal_role, _org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id
      AND role = _role
      AND organization_id = _org_id
  )
$$;


--
-- Name: has_role(uuid, uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role(_user_id uuid, _org_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
