      AND role::text = _role::text
  )
$$;


--
-- Name: increment_automation_rate_limit(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_automation_rate_limit(p_organization_id uuid, p_rule_id uuid, p_increment integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hour_start TIMESTAMPTZ;
  v_day_start TIMESTAMPTZ;
BEGIN
  v_hour_start := date_trunc('hour', now());
  v_day_start := date_trunc('day', now());
  
  -- Upsert hourly count
  INSERT INTO automation_rate_limits (organization_id, automation_rule_id, window_start, window_type, action_count)
  VALUES (p_organization_id, p_rule_id, v_hour_start, 'hour', p_increment)
  ON CONFLICT (organization_id, automation_rule_id, window_start, window_type)
  DO UPDATE SET action_count = automation_rate_limits.action_count + p_increment;
  
  -- Upsert daily count
  INSERT INTO automation_rate_limits (organization_id, automation_rule_id, window_start, window_type, action_count)
  VALUES (p_organization_id, p_rule_id, v_day_start, 'day', p_increment)
  ON CONFLICT (organization_id, automation_rule_id, window_start, window_type)
  DO UPDATE SET action_count = automation_rate_limits.action_count + p_increment;
END;
$$;


--
-- Name: is_active_onboarding_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_onboarding_path(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_parts text[];
  v_org uuid;
  v_app uuid;
  v_status text;
BEGIN
  v_parts := string_to_array(p_name, '/');
  IF array_length(v_parts,1) < 4 THEN RETURN false; END IF;
  IF v_parts[2] <> 'onboarding' THEN RETURN false; END IF;
  BEGIN
    v_org := v_parts[1]::uuid;
    v_app := v_parts[3]::uuid;
  EXCEPTION WHEN others THEN RETURN false; END;
  SELECT status INTO v_status
    FROM public.onboarding_applications
   WHERE id = v_app AND organization_id = v_org;
  IF v_status IS NULL THEN RETURN false; END IF;
  RETURN v_status NOT IN ('approved','rejected','cancelled');
END;
$$;


--
-- Name: is_active_onboarding_upload_path(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_onboarding_upload_path(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_parts text[];
  v_org uuid;
  v_app uuid;
  v_token text;
  v_row record;
BEGIN
  v_parts := string_to_array(p_name, '/');
  -- Expected path: orgId/onboarding/appId/<token>/<filename> (>=5 parts)
  IF array_length(v_parts, 1) < 5 THEN RETURN false; END IF;
  IF v_parts[2] <> 'onboarding' THEN RETURN false; END IF;
  BEGIN
    v_org := v_parts[1]::uuid;
    v_app := v_parts[3]::uuid;
  EXCEPTION WHEN others THEN RETURN false; END;
  v_token := v_parts[4];
  IF v_token IS NULL OR length(v_token) = 0 THEN RETURN false; END IF;

  SELECT status, access_token, access_token_expires_at
    INTO v_row
    FROM public.onboarding_applications
   WHERE id = v_app AND organization_id = v_org;

  IF NOT FOUND THEN RETURN false; END IF;
  IF v_row.status IN ('approved','rejected','cancelled') THEN RETURN false; END IF;
  IF v_row.access_token IS NULL OR v_row.access_token <> v_token THEN RETURN false; END IF;
  IF v_row.access_token_expires_at IS NOT NULL AND v_row.access_token_expires_at <= now() THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


--
-- Name: is_canonical_lifecycle_enabled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_canonical_lifecycle_enabled(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT canonical_lifecycle_enabled FROM public.organizations WHERE id = p_org_id),
    false
  );
$$;


--
-- Name: is_period_locked(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_period_locked(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_target_date date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lock_date DATE;
BEGIN
  -- Find the most restrictive lock date for this entity
  SELECT lock_date INTO v_lock_date
  FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND (
      (p_client_id IS NOT NULL AND client_id = p_client_id)
      OR (p_company_id IS NOT NULL AND company_id = p_company_id)
    )
  ORDER BY lock_date DESC
  LIMIT 1;
  
  -- If no lock exists, period is not locked
  IF v_lock_date IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Period is locked if target date is before or on lock date
  RETURN p_target_date <= v_lock_date;
END;
$$;


--
-- Name: is_portal_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_portal_user() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.portal_access WHERE user_id = auth.uid() AND is_active = true);
$$;


--
-- Name: issue_invoice_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_invoice_safe(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_org_settings record;
  v_invoice_number text;
  v_post jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT (
    (public.user_in_organization(v_user_id, v_invoice.organization_id)
      AND public.can_issue_invoices(v_user_id, v_invoice.organization_id))
    OR (
      public.portal_has_perm(v_invoice.client_id, v_invoice.company_id, 'allow_invoice_send')
      AND NOT COALESCE((
        SELECT require_review_for_invoice_sending FROM public.portal_visibility_settings
        WHERE (v_invoice.client_id IS NOT NULL AND client_id = v_invoice.client_id)
           OR (v_invoice.company_id IS NOT NULL AND company_id = v_invoice.company_id)
        LIMIT 1), false)
    )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: cannot issue invoices');
  END IF;
  IF v_invoice.status != 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT invoices can be issued');
  END IF;
  IF v_invoice.invoice_number IS NULL OR v_invoice.invoice_number = '' THEN
    SELECT * INTO v_org_settings FROM org_settings WHERE organization_id = v_invoice.organization_id FOR UPDATE;
    IF v_org_settings IS NULL THEN
      INSERT INTO org_settings (organization_id) VALUES (v_invoice.organization_id)
      RETURNING * INTO v_org_settings;
    END IF;
    v_invoice_number := COALESCE(v_org_settings.invoice_number_prefix, 'INV-') ||
      LPAD(COALESCE(v_org_settings.invoice_number_next, 1)::text, COALESCE(v_org_settings.invoice_number_padding, 6), '0');
    UPDATE org_settings SET invoice_number_next = COALESCE(invoice_number_next, 1) + 1
    WHERE organization_id = v_invoice.organization_id;
  ELSE
    v_invoice_number := v_invoice.invoice_number;
  END IF;
  UPDATE invoices SET
    invoice_number = v_invoice_number,
    issued_at = now(),
    issued_by = v_user_id,
    locked_fields = '["total_net","total_vat","total_gross","lines"]'::jsonb,
    updated_at = now()
  WHERE id = p_invoice_id;
  v_post := public.approve_invoice(p_invoice_id, v_user_id);
  IF NOT COALESCE((v_post->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'Could not post invoice to the ledger: %',
      COALESCE(v_post->>'error_message', 'posting error')
      USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, before_state, after_state)
  VALUES (v_invoice.organization_id, v_user_id, 'invoice', p_invoice_id, 'issued',
    jsonb_build_object('status', 'DRAFT'),
    jsonb_build_object('status', 'AWAITING_PAYMENT', 'invoice_number', v_invoice_number));
  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id,
                            'invoice_number', v_invoice_number,
                            'journal_id', v_post->>'journal_id');
END;
$$;


--
-- Name: lifecycle_accept_portal_invitation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_accept_portal_invitation(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_current_user_id uuid;
  v_portal_access record;
  v_entity_type text;
  v_entity_id uuid;
BEGIN
  -- Validate authentication
  v_current_user_id := auth.uid();
  
  IF v_current_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'unauthenticated');
  END IF;

  -- Look up portal_access by token
  SELECT * INTO v_portal_access
  FROM portal_access
  WHERE invite_token = p_token
    AND status = 'invited'
    AND (invite_expires_at IS NULL OR invite_expires_at > now());

  -- If not found or expired
  IF v_portal_access.id IS NULL THEN
    -- Check if expired
    IF EXISTS (
      SELECT 1 FROM portal_access
      WHERE invite_token = p_token
        AND status = 'invited'
        AND invite_expires_at IS NOT NULL
        AND invite_expires_at <= now()
    ) THEN
      RETURN jsonb_build_object('success', false, 'reason', 'expired');
    ELSE
      RETURN jsonb_build_object('success', false, 'reason', 'not_found');
    END IF;
  END IF;

  -- Validate no user_id conflict (prevent invite hijacking)
  IF v_portal_access.user_id IS NOT NULL AND v_portal_access.user_id != v_current_user_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'user_mismatch');
  END IF;

  -- Determine entity type and ID
  IF v_portal_access.client_id IS NOT NULL THEN
    v_entity_type := 'client';
    v_entity_id := v_portal_access.client_id;
  ELSIF v_portal_access.company_id IS NOT NULL THEN
    v_entity_type := 'company';
    v_entity_id := v_portal_access.company_id;
  END IF;

  -- Deactivate any duplicate active invites for this user + entity
  UPDATE portal_access
  SET 
    status = 'revoked_by_system',
    is_active = false,
    updated_at = now()
  WHERE user_id = v_current_user_id
    AND (
      (client_id = v_portal_access.client_id AND client_id IS NOT NULL) OR
      (company_id = v_portal_access.company_id AND company_id IS NOT NULL)
    )
    AND id != v_portal_access.id
    AND is_active = true;

  -- Update portal_access to active
  UPDATE portal_access
  SET
    user_id = v_current_user_id,
    status = 'active',
    is_active = true,
    accepted_at = now(),
    invite_token = NULL,
    invite_expires_at = NULL,
    updated_at = now()
  WHERE id = v_portal_access.id;

  -- Write to audit_log
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    user_id,
    metadata
  ) VALUES (
    v_portal_access.organization_id,
    'portal_access',
    v_portal_access.id,
    'accepted',
    v_current_user_id,
    jsonb_build_object(
      'entity_type', v_entity_type,
      'entity_id', v_entity_id,
      'role', v_portal_access.role
    )
  );

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'portal_access_id', v_portal_access.id,
    'entity_type', v_entity_type,
    'entity_id', v_entity_id,
    'organization_id', v_portal_access.organization_id,
    'status', 'active'
  );
END;
$$;


--
-- Name: lifecycle_accept_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_accept_quote(p_quote_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote record;
  v_lead record;
  v_onboarding_id uuid;
  v_onboarding_status text;
  v_created_new_onboarding boolean := false;
  v_old_quote_status text;
BEGIN
  -- Fetch quote
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id;
  
  IF v_quote.id IS NULL THEN
    RAISE EXCEPTION 'Quote not found: %', p_quote_id;
  END IF;

  -- Verify caller has access to organization
  IF NOT user_has_organization_access(v_quote.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  -- Validate quote status (accept from draft or sent)
  IF v_quote.status NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'Quote cannot be accepted. Current status: %', v_quote.status;
  END IF;

  v_old_quote_status := v_quote.status;

  -- Update quote
  UPDATE quotes 
  SET 
    status = 'accepted',
    accepted_at = now(),
    sent_at = COALESCE(sent_at, now())
  WHERE id = p_quote_id;

  -- Write audit log for quote
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    old_value,
    new_value,
    user_id
  )
  VALUES (
    v_quote.organization_id,
    'quote',
    p_quote_id,
    'status_change',
    v_old_quote_status,
    'accepted',
    auth.uid()
  );

  -- Update linked lead if present
  IF v_quote.lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM leads WHERE id = v_quote.lead_id;
    
    UPDATE leads 
    SET 
      pipeline_stage = 'won',
      converted_at = now()
    WHERE id = v_quote.lead_id;

    -- Write audit log for lead
    INSERT INTO audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      old_value,
      new_value,
      user_id
    )
    VALUES (
      v_quote.organization_id,
      'lead',
      v_quote.lead_id,
      'status_change',
      v_lead.pipeline_stage,
      'won',
      auth.uid()
    );
  END IF;

  -- Check for existing onboarding application
  SELECT id, status INTO v_onboarding_id, v_onboarding_status
  FROM onboarding_applications 
  WHERE quote_id = p_quote_id
  LIMIT 1;

  -- Create onboarding application if none exists
  IF v_onboarding_id IS NULL THEN
    INSERT INTO onboarding_applications (
      organization_id,
      lead_id,
      quote_id,
      application_type,
      status,
      aml_status,
      first_name,
      last_name,
      email,
      phone
    )
    SELECT
      v_quote.organization_id,
      v_quote.lead_id,
      p_quote_id,
      CASE 
        WHEN v_lead.company_name IS NOT NULL THEN 'company'
        ELSE 'individual'
      END,
      'pending',
      'pending',
      COALESCE(v_lead.first_name, ''),
      COALESCE(v_lead.last_name, ''),
      COALESCE(v_lead.email, v_quote.client_email),
      v_lead.phone
    FROM (SELECT v_lead.*) AS lead_data
    RETURNING id, status INTO v_onboarding_id, v_onboarding_status;

    v_created_new_onboarding := true;

    -- Write audit log for onboarding creation
    INSERT INTO audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      user_id,
      metadata
    )
    VALUES (
      v_quote.organization_id,
      'onboarding',
      v_onboarding_id,
      'created',
      auth.uid(),
      jsonb_build_object('quote_id', p_quote_id, 'lead_id', v_quote.lead_id)
    );
  END IF;

  -- Return result
  RETURN jsonb_build_object(
    'quote_id', p_quote_id,
    'quote_status', 'accepted',
    'lead_id', v_quote.lead_id,
    'lead_stage', CASE WHEN v_quote.lead_id IS NOT NULL THEN 'won' ELSE NULL END,
    'onboarding_application_id', v_onboarding_id,
    'onboarding_status', v_onboarding_status,
    'created_new_onboarding', v_created_new_onboarding
  );
END;
$$;


--
-- Name: lifecycle_activate_client_services(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_activate_client_services(p_quote_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote        RECORD;
  v_client_id    uuid;
  v_company_id   uuid;
  v_lead         RECORD;
  v_line         RECORD;
  v_eng_id       uuid;
  v_created      int := 0;
  v_skipped      int := 0;
  v_results      jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF v_quote IS NULL THEN
    RAISE EXCEPTION 'Quote % not found', p_quote_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_quote.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_quote.organization_id) THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'canonical_spine_v1 flag disabled',
      'quote_id', p_quote_id
    );
  END IF;

  IF v_quote.status <> 'accepted' THEN
    RAISE EXCEPTION 'Quote % not accepted (status=%)', p_quote_id, v_quote.status;
  END IF;

  -- Resolve target client/company via lead -> conversion
  SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
  IF v_lead IS NULL THEN
    RAISE EXCEPTION 'Quote % has no lead', p_quote_id;
  END IF;

  v_client_id  := v_lead.converted_client_id;
  v_company_id := v_lead.converted_company_id;

  IF v_client_id IS NULL AND v_company_id IS NULL THEN
    RAISE EXCEPTION 'Lead % has not been converted to a client/company yet', v_lead.id;
  END IF;

  FOR v_line IN
    SELECT ql.*, sc.id AS svc_id
      FROM public.quote_lines ql
      JOIN public.services_catalog sc ON sc.id = ql.service_id
     WHERE ql.quote_id = p_quote_id
       AND ql.canonical_service_code IS NOT NULL
  LOOP
    -- Idempotent: find existing engagement keyed on (org, client/company, canonical_service_code)
    SELECT id INTO v_eng_id
      FROM public.engagements
     WHERE organization_id = v_quote.organization_id
       AND canonical_service_code = v_line.canonical_service_code
       AND COALESCE(client_id::text, '') = COALESCE(v_client_id::text, '')
       AND COALESCE(company_id::text, '') = COALESCE(v_company_id::text, '')
     LIMIT 1;

    IF v_eng_id IS NULL THEN
      INSERT INTO public.engagements (
        organization_id, client_id, company_id, service_id, quote_id,
        canonical_service_code, frequency, start_date, status, active, activated_at
      ) VALUES (
        v_quote.organization_id, v_client_id, v_company_id, v_line.service_id, p_quote_id,
        v_line.canonical_service_code,
        COALESCE(v_line.billing_frequency, 'one_off'),
        CURRENT_DATE, 'active', true, now()
      )
      RETURNING id INTO v_eng_id;
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'canonical_service_code', v_line.canonical_service_code,
        'engagement_id', v_eng_id,
        'action', 'created'
      );
    ELSE
      -- Re-activate if previously suspended/terminated
      UPDATE public.engagements
         SET status = 'active', active = true, activated_at = COALESCE(activated_at, now())
       WHERE id = v_eng_id AND status <> 'active';
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'canonical_service_code', v_line.canonical_service_code,
        'engagement_id', v_eng_id,
        'action', 'reused'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'ok',
    'quote_id', p_quote_id,
    'engagements_created', v_created,
    'engagements_reused', v_skipped,
    'results', v_results
  );
END;
$$;


--
-- Name: lifecycle_approve_onboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_approve_onboarding(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_onboarding record;
  v_questionnaire_instance record;
  v_questionnaire_responses jsonb;
  v_client_id uuid;
  v_company_id uuid;
  v_engagement_ids uuid[] := ARRAY[]::uuid[];
  v_job_ids uuid[] := ARRAY[]::uuid[];
  v_engagement_id uuid;
  v_job_id uuid;
  v_portal_access_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_primary_email text;
  v_quote_line record;
  v_trigger_date date;
  v_aml_expiry_date date;
  v_period_label text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;

  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_onboarding_id;
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  IF v_onboarding.status = 'approved' THEN
    RAISE EXCEPTION 'Onboarding application already approved';
  END IF;

  IF v_onboarding.status = 'rejected' THEN
    RAISE EXCEPTION 'Cannot approve rejected application';
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    DECLARE
      v_gates jsonb := public.lifecycle_onboarding_gates(p_onboarding_id);
    BEGIN
      -- T2b: gate on activation_ready (signatures/AML/submission) — billing no longer blocks.
      IF NOT COALESCE((v_gates->>'activation_ready')::boolean, false) THEN
        RAISE EXCEPTION 'Cannot approve onboarding %: outstanding activation gates %',
          p_onboarding_id, (v_gates->>'outstanding');
      END IF;
    END;
  END IF;

  v_aml_expiry_date := CURRENT_DATE + INTERVAL '5 years';

  IF v_onboarding.onboarding_questionnaire_instance_id IS NOT NULL THEN
    SELECT * INTO v_questionnaire_instance
    FROM questionnaire_instances
    WHERE id = v_onboarding.onboarding_questionnaire_instance_id;

    SELECT jsonb_object_agg(qr.question_id, qr.response_value)
    INTO v_questionnaire_responses
    FROM questionnaire_responses qr
    WHERE qr.questionnaire_instance_id = v_onboarding.onboarding_questionnaire_instance_id;
  END IF;

  IF v_onboarding.application_type = 'individual' THEN
    IF v_onboarding.client_id IS NOT NULL THEN
      v_client_id := v_onboarding.client_id;
      UPDATE clients
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        first_name = COALESCE(v_questionnaire_responses->>'first_name', first_name),
        last_name = COALESCE(v_questionnaire_responses->>'last_name', last_name),
        date_of_birth = COALESCE((v_questionnaire_responses->>'date_of_birth')::date, date_of_birth),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        national_insurance_number = COALESCE(v_questionnaire_responses->>'national_insurance_number', national_insurance_number),
        utr = COALESCE(v_questionnaire_responses->>'utr', utr)
      WHERE id = v_client_id;
    ELSE
      INSERT INTO clients (
        organization_id, first_name, last_name, email, phone, date_of_birth,
        address_line_1, address_line_2, city, postcode, country,
        national_insurance_number, utr, status, activated_at,
        aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'first_name', v_onboarding.first_name),
        COALESCE(v_questionnaire_responses->>'last_name', v_onboarding.last_name),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE((v_questionnaire_responses->>'date_of_birth')::date, v_onboarding.date_of_birth),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'national_insurance_number', v_onboarding.national_insurance_number),
        COALESCE(v_questionnaire_responses->>'utr', v_onboarding.utr),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_client_id;

      UPDATE onboarding_applications SET client_id = v_client_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'client', v_client_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'client';
    v_entity_id := v_client_id;

  ELSIF v_onboarding.application_type = 'company' THEN
    IF v_onboarding.company_id IS NOT NULL THEN
      v_company_id := v_onboarding.company_id;
      UPDATE companies
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        company_name = COALESCE(v_questionnaire_responses->>'company_name', company_name),
        company_number = COALESCE(v_questionnaire_responses->>'company_number', company_number),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        vat_number = COALESCE(v_questionnaire_responses->>'vat_number', vat_number),
        incorporation_date = COALESCE((v_questionnaire_responses->>'incorporation_date')::date, incorporation_date),
        year_end_month = COALESCE((v_questionnaire_responses->>'year_end_month')::integer, year_end_month),
        year_end_day = COALESCE((v_questionnaire_responses->>'year_end_day')::integer, year_end_day)
      WHERE id = v_company_id;
    ELSE
      INSERT INTO companies (
        organization_id, company_name, company_number, email, phone,
        address_line_1, address_line_2, city, postcode, country,
        vat_number, incorporation_date, year_end_month, year_end_day,
        status, activated_at, aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'company_name', v_onboarding.company_name),
        COALESCE(v_questionnaire_responses->>'company_number', v_onboarding.company_number),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'vat_number', v_onboarding.vat_number),
        COALESCE((v_questionnaire_responses->>'incorporation_date')::date, v_onboarding.incorporation_date),
        COALESCE((v_questionnaire_responses->>'year_end_month')::integer, v_onboarding.year_end_month),
        COALESCE((v_questionnaire_responses->>'year_end_day')::integer, v_onboarding.year_end_day),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_company_id;

      UPDATE onboarding_applications SET company_id = v_company_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'company', v_company_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'company';
    v_entity_id := v_company_id;
  END IF;

  IF v_onboarding.quote_id IS NOT NULL THEN
    -- Canonical engine: the SINGLE idempotent source for engagements + jobs + deadlines.
    PERFORM public.lifecycle_materialize_jobs(
      v_onboarding.organization_id, v_client_id, v_company_id, NULL,
      v_onboarding.quote_id, 'onboarding_approval:' || p_onboarding_id::text);

    FOR v_quote_line IN
      SELECT ql.*, sc.code AS service_code, sc.name AS service_name,
             sc.trigger_date_type, sc.trigger_date_offset_days, sc.information_request_template_id
      FROM quote_lines ql
      LEFT JOIN services_catalog sc ON sc.id = ql.service_id
      WHERE ql.quote_id = v_onboarding.quote_id
    LOOP
      SELECT id INTO v_engagement_id
      FROM engagements
      WHERE quote_id = v_onboarding.quote_id AND service_id = v_quote_line.service_id
      LIMIT 1;
      IF v_engagement_id IS NOT NULL THEN
        v_engagement_ids := array_append(v_engagement_ids, v_engagement_id);
      END IF;

      SELECT id INTO v_job_id
      FROM jobs
      WHERE organization_id = v_onboarding.organization_id
        AND service_type = COALESCE(v_quote_line.service_code, v_quote_line.service_id::text)
        AND COALESCE(client_id::text, '') = COALESCE(v_client_id::text, '')
        AND COALESCE(company_id::text, '') = COALESCE(v_company_id::text, '')
      ORDER BY created_at DESC
      LIMIT 1;
      IF v_job_id IS NOT NULL THEN
        v_job_ids := array_append(v_job_ids, v_job_id);
      END IF;

      IF v_quote_line.trigger_date_type IS NOT NULL AND v_quote_line.information_request_template_id IS NOT NULL THEN
        v_trigger_date := CASE v_quote_line.trigger_date_type
          WHEN 'tax_year_end' THEN
            CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              THEN make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              ELSE make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int - 1, 4, 5)
            END
          WHEN 'financial_year_end' THEN
            CASE WHEN v_company_id IS NOT NULL THEN
              (SELECT make_date(
                CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, COALESCE(c.year_end_month, 3), COALESCE(c.year_end_day, 31))
                  THEN EXTRACT(YEAR FROM CURRENT_DATE)::int
                  ELSE EXTRACT(YEAR FROM CURRENT_DATE)::int - 1
                END,
                COALESCE(c.year_end_month, 3),
                COALESCE(c.year_end_day, 31)
              ) FROM companies c WHERE c.id = v_company_id)
            ELSE CURRENT_DATE - INTERVAL '1 day'
            END
          ELSE CURRENT_DATE - INTERVAL '1 day'
        END;

        IF CURRENT_DATE > v_trigger_date + (COALESCE(v_quote_line.trigger_date_offset_days,0) || ' days')::interval THEN
          INSERT INTO email_queue (
            organization_id, to_email, to_name, subject, body_html,
            template_id, client_id, company_id, job_id, entity_type, entity_id,
            merge_data, status
          )
          SELECT
            v_onboarding.organization_id,
            v_onboarding.email,
            COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
            COALESCE(t.name, 'Information Request') || ' - ' || COALESCE(v_quote_line.service_name,'Service'),
            COALESCE(t.content->>'body_html', '<p>We need some information to complete your ' || COALESCE(v_quote_line.service_name,'service') || '.</p>'),
            v_quote_line.information_request_template_id,
            v_client_id,
            v_company_id,
            v_job_id,
            'job',
            v_job_id,
            jsonb_build_object(
              'client_name', COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
              'service_name', v_quote_line.service_name,
              'trigger_date', v_trigger_date::text
            ),
            'pending'
          FROM templates t WHERE t.id = v_quote_line.information_request_template_id;

          INSERT INTO client_tasks (
            organization_id, client_id, company_id, title, description,
            status, visibility, due_date
          )
          VALUES (
            v_onboarding.organization_id, v_client_id, v_company_id,
            'Provide information for ' || COALESCE(v_quote_line.service_name,'service'),
            'Please provide the required information to complete your ' || COALESCE(v_quote_line.service_name,'service'),
            'not_started', 'client_visible',
            CURRENT_DATE + INTERVAL '14 days'
          );
        END IF;
      END IF;

      IF v_engagement_id IS NOT NULL THEN
        INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
        VALUES (v_onboarding.organization_id, 'engagement', v_engagement_id, 'created', auth.uid(),
          jsonb_build_object('onboarding_id', p_onboarding_id, 'service_id', v_quote_line.service_id));
      END IF;
    END LOOP;
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    IF v_company_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND company_id = v_company_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_company_id, 'active', 'practice', now());
      END IF;
    ELSIF v_client_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND client_id = v_client_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_client_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  UPDATE onboarding_applications
  SET
    status = 'approved',
    approved_at = now(),
    approved_by = auth.uid(),
    aml_expiry_date = v_aml_expiry_date,
    aml_documents_migrated = true
  WHERE id = p_onboarding_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'approved', v_onboarding.status, 'approved', auth.uid());

  v_primary_email := v_onboarding.email;
  IF v_primary_email IS NOT NULL AND v_primary_email != '' AND v_entity_type IS NOT NULL AND v_entity_id IS NOT NULL THEN
    BEGIN
      v_portal_access_result := lifecycle_grant_portal_access(v_entity_type, v_entity_id, v_primary_email, 'primary_contact');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'portal_access_failed', auth.uid(),
        jsonb_build_object('error', SQLERRM, 'sqlstate', SQLSTATE, 'email', v_primary_email));
      v_portal_access_result := jsonb_build_object('ok', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
    END;
  ELSE
    v_portal_access_result := jsonb_build_object('ok', false, 'skipped', true, 'reason',
      CASE WHEN v_primary_email IS NULL OR v_primary_email = '' THEN 'no_email' ELSE 'no_entity' END);
  END IF;

  RETURN jsonb_build_object(
    'onboarding_id', p_onboarding_id,
    'status', 'approved',
    'client_id', v_client_id,
    'company_id', v_company_id,
    'engagement_ids', v_engagement_ids,
    'job_ids', v_job_ids,
    'portal_access', v_portal_access_result,
    'aml_expiry_date', v_aml_expiry_date,
    'questionnaire_data_populated', v_questionnaire_responses IS NOT NULL
  );
END;
$$;


--
-- Name: lifecycle_create_manual_job(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_create_manual_job(p_client_id uuid, p_company_id uuid, p_service_code text, p_tax_year_start integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_svc record;
  v_today date := CURRENT_DATE;
  v_company record;
  v_period_start date; v_period_end date; v_period_label text;
  v_job_id uuid;
BEGIN
  IF p_client_id IS NULL AND p_company_id IS NULL THEN
    RAISE EXCEPTION 'A client or company is required';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;
  IF NOT public.user_has_organization_access(v_org) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code AND organization_id = v_org LIMIT 1;
  IF v_svc.code IS NULL THEN
    SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code LIMIT 1;
  END IF;
  IF v_svc.code IS NULL THEN RAISE EXCEPTION 'Unknown service %', p_service_code; END IF;

  IF p_service_code IN ('sa_mtd','sa_non_mtd') THEN
    IF p_tax_year_start IS NULL THEN
      IF EXTRACT(MONTH FROM v_today) > 4 OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int;
      ELSE
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int - 1;
      END IF;
    END IF;
    v_period_start := make_date(p_tax_year_start, 4, 6);
    v_period_end := make_date(p_tax_year_start + 1, 4, 5);
    v_period_label := p_tax_year_start::text || '/' || substr((p_tax_year_start + 1)::text, 3, 2);
  ELSIF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
    IF v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;
  ELSE
    v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
  END IF;

  v_job_id := public.lifecycle_upsert_job_with_deadlines(
    v_org, p_client_id, p_company_id, NULL, v_svc.code, v_svc.name,
    v_period_start, v_period_end, v_period_label, 'manual');

  RETURN jsonb_build_object('job_id', v_job_id, 'period_label', v_period_label);
END;
$$;


--
-- Name: lifecycle_evaluate_onboarding_activation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_evaluate_onboarding_activation(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  a          public.onboarding_applications%ROWTYPE;
  v_flag     boolean;
  v_gates    jsonb;
  v_all_pass boolean;
  v_approve  jsonb;
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_application_id;
  END IF;

  IF NOT public.user_has_organization_access(a.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  v_flag     := public.is_canonical_lifecycle_enabled(a.organization_id);
  v_gates    := public.lifecycle_onboarding_gates(p_application_id);
  -- T2b: activation is driven by signatures/AML/submission (activation_ready), NOT billing.
  v_all_pass := COALESCE((v_gates->>'activation_ready')::boolean, false);

  IF NOT v_flag THEN
    RETURN jsonb_build_object('mode', 'dry_run', 'flag', false,
                              'would_activate', v_all_pass, 'gates', v_gates);
  END IF;

  IF a.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('mode', 'noop_closed', 'status', a.status, 'gates', v_gates);
  END IF;

  IF NOT v_all_pass THEN
    UPDATE public.onboarding_applications
       SET status = 'for_review',
           review_feedback = COALESCE(review_feedback, '') ||
             CASE WHEN COALESCE(review_feedback,'') = '' THEN '' ELSE E'\n' END ||
             'Auto-evaluation outstanding gates: ' || (v_gates->>'outstanding'),
           updated_at = now()
     WHERE id = p_application_id;
    RETURN jsonb_build_object('mode', 'routed_to_review', 'gates', v_gates);
  END IF;

  IF a.application_type = 'company' AND a.company_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND company_id = a.company_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.company_id, 'active', 'practice', now());
    END IF;
  ELSIF a.client_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND client_id = a.client_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.client_id, 'active', 'practice', now());
    END IF;
  END IF;

  v_approve := public.lifecycle_approve_onboarding(p_application_id);

  RETURN jsonb_build_object('mode', 'activated', 'gates', v_gates, 'approve', v_approve);
END;
$$;


--
-- Name: FUNCTION lifecycle_evaluate_onboarding_activation(p_application_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lifecycle_evaluate_onboarding_activation(p_application_id uuid) IS 'Sprint 1: flag-aware onboarding activation evaluator. Org-access gated (members only). Flag OFF => dry-run, no writes. Flag ON => activate (link + delegate to approve) when gates pass, else route to for_review. Dormant.';


--
-- Name: lifecycle_generate_deadlines_for_job(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_generate_deadlines_for_job(p_job_id uuid, p_facts jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job       RECORD;
  v_rule      RECORD;
  v_calc      jsonb;
  v_due       date;
  v_missing   text[];
  v_fact      text;
  v_created   int := 0;
  v_skipped   int := 0;
  v_missing_facts_logged int := 0;
  v_existing  uuid;
  v_results   jsonb := '[]'::jsonb;
  v_tax_year_end date;
  v_after_tax  boolean;
  v_fixed_txt  text;
  v_existing_dl record;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF v_job IS NULL THEN
    RAISE EXCEPTION 'Job % not found', p_job_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_job.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_job.job_template_code IS NULL OR v_job.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Job % is not mapped to a canonical job template', p_job_id;
  END IF;

  FOR v_rule IN
    SELECT * FROM public.canonical_deadline_rules
     WHERE active = true
       AND (job_template_code = v_job.job_template_code
            OR (job_template_code IS NULL AND canonical_service_code = v_job.canonical_service_code))
  LOOP
    v_calc := v_rule.calculation_method;
    v_due := NULL;
    v_missing := ARRAY[]::text[];

    -- Check required_facts presence in p_facts JSON
    IF v_rule.required_facts IS NOT NULL THEN
      FOREACH v_fact IN ARRAY v_rule.required_facts
      LOOP
        -- skip "fact" entries that actually reference another deadline_code we may have just made
        IF p_facts ? v_fact THEN
          CONTINUE;
        END IF;
        -- internal cross-deadline references are resolved later; not blocking
        IF v_fact IN ('companies_house_accounts_filing','ct600_filing','partnership_tax_return_filing') THEN
          CONTINUE;
        END IF;
        v_missing := v_missing || v_fact;
      END LOOP;
    END IF;

    IF array_length(v_missing, 1) > 0 THEN
      -- create a client_task as a missing-fact placeholder (idempotent on title+job)
      IF NOT EXISTS (
        SELECT 1 FROM public.client_tasks
         WHERE job_id = p_job_id
           AND title = 'Missing data: ' || v_rule.deadline_name
      ) THEN
        INSERT INTO public.client_tasks (
          organization_id, client_id, company_id, job_id,
          title, description, status, visibility
        ) VALUES (
          v_job.organization_id, v_job.client_id, v_job.company_id, p_job_id,
          'Missing data: ' || v_rule.deadline_name,
          'Cannot compute "' || v_rule.deadline_name || '" — missing fact(s): '
            || array_to_string(v_missing, ', '),
          'pending', 'internal'
        );
        v_missing_facts_logged := v_missing_facts_logged + 1;
      END IF;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'missing_facts',
        'missing', v_missing
      );
      CONTINUE;
    END IF;

    -- Compute due_date from calculation_method (covers the common shapes)
    IF v_calc ? 'add_months_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_months_to'))::date
                + ((v_calc->>'months')::int || ' months')::interval)::date;
    ELSIF v_calc ? 'add_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_to'))::date
                + ((COALESCE(v_calc->>'months','0'))::int || ' months')::interval
                + ((COALESCE(v_calc->>'days','0'))::int || ' days')::interval)::date;
    ELSIF v_calc ? 'fixed_date' AND COALESCE((v_calc->>'after_tax_year')::boolean, false) THEN
      -- tax year of form '2024/25' → year-end 5 April 2025 → due = fixed_date in calendar year after tax_year_end
      v_tax_year_end := (
        SELECT (split_part(p_facts->>'tax_year','/',1)::int + 1)::text || '-04-05'
      )::date;
      v_fixed_txt := v_calc->>'fixed_date';
      v_due := to_date(v_fixed_txt || ' ' || (extract(year FROM v_tax_year_end)::int + 1)::text, 'DD Month YYYY');
    ELSIF v_calc ? 'offset_days_before' THEN
      -- Resolve against a previously created deadline by deadline_code on this job
      SELECT due_date INTO v_due FROM public.deadlines
       WHERE job_id = p_job_id AND deadline_code = (v_calc->>'offset_days_before')
       ORDER BY created_at DESC LIMIT 1;
      IF v_due IS NOT NULL THEN
        v_due := v_due - ((v_calc->>'default_days')::int);
      END IF;
    END IF;

    IF v_due IS NULL THEN
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'unsupported_calculation'
      );
      CONTINUE;
    END IF;

    -- Idempotent upsert keyed on (job_id, deadline_code)
    SELECT id INTO v_existing FROM public.deadlines
     WHERE job_id = p_job_id AND deadline_code = v_rule.deadline_code
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.deadlines (
        organization_id, client_id, company_id, engagement_id, job_id,
        name, deadline_type, service_code, canonical_service_code, deadline_code,
        due_date, status
      ) VALUES (
        v_job.organization_id, v_job.client_id, v_job.company_id, NULL, p_job_id,
        v_rule.deadline_name, v_rule.deadline_type, v_job.canonical_service_code,
        v_job.canonical_service_code, v_rule.deadline_code,
        v_due, 'open'
      );
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'created'
      );
    ELSE
      UPDATE public.deadlines
         SET due_date = v_due, updated_at = now()
       WHERE id = v_existing AND status NOT IN ('completed','filed');
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'updated'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'job_id', p_job_id,
    'deadlines_created', v_created,
    'deadlines_updated', v_skipped,
    'missing_fact_tasks', v_missing_facts_logged,
    'results', v_results
  );
END;
$$;


--
-- Name: lifecycle_generate_jobs_for_service(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_generate_jobs_for_service(p_engagement_id uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_eng       RECORD;
  v_svc       RECORD;
  v_tpl       RECORD;
  v_job_id    uuid;
  v_existing  uuid;
  v_created   int := 0;
  v_skipped   int := 0;
  v_results   jsonb := '[]'::jsonb;
  v_period_label text;
BEGIN
  SELECT * INTO v_eng FROM public.engagements WHERE id = p_engagement_id;
  IF v_eng IS NULL THEN
    RAISE EXCEPTION 'Engagement % not found', p_engagement_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_eng.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_eng.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_eng.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Engagement % is not mapped to a canonical service', p_engagement_id;
  END IF;

  IF v_eng.status <> 'active' THEN
    RETURN jsonb_build_object('status','skipped','reason','engagement not active');
  END IF;

  SELECT * INTO v_svc FROM public.canonical_services WHERE code = v_eng.canonical_service_code;
  IF v_svc IS NULL OR NOT v_svc.creates_jobs THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical service does not create jobs');
  END IF;

  v_period_label := CASE
    WHEN p_period_start IS NOT NULL AND p_period_end IS NOT NULL
      THEN to_char(p_period_start,'YYYY-MM-DD') || ' to ' || to_char(p_period_end,'YYYY-MM-DD')
    ELSE NULL
  END;

  FOR v_tpl IN
    SELECT * FROM public.canonical_job_templates
     WHERE canonical_service_code = v_eng.canonical_service_code AND active = true
  LOOP
    -- Idempotency key: org + entity + job_template_code + period
    SELECT id INTO v_existing
      FROM public.jobs
     WHERE organization_id = v_eng.organization_id
       AND job_template_code = v_tpl.job_template_code
       AND COALESCE(client_id::text,'') = COALESCE(v_eng.client_id::text,'')
       AND COALESCE(company_id::text,'') = COALESCE(v_eng.company_id::text,'')
       AND COALESCE(period_start::text,'') = COALESCE(p_period_start::text,'')
       AND COALESCE(period_end::text,'')   = COALESCE(p_period_end::text,'')
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.jobs (
        organization_id, client_id, company_id, job_name, service_type,
        canonical_service_code, job_template_code,
        period_start, period_end, period_label,
        status, priority, is_auto_generated, auto_generated_at, generation_reason,
        automation_source
      ) VALUES (
        v_eng.organization_id, v_eng.client_id, v_eng.company_id,
        v_tpl.display_name || COALESCE(' — ' || v_period_label, ''),
        v_eng.canonical_service_code, -- service_type kept human readable; canonical codes carry truth
        v_eng.canonical_service_code, v_tpl.job_template_code,
        p_period_start, p_period_end, v_period_label,
        COALESCE(v_tpl.default_status, 'blank'), 'normal', true, now(),
        'canonical_lifecycle',
        'canonical_spine_v1'
      )
      RETURNING id INTO v_job_id;
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_job_id,
        'action', 'created'
      );
    ELSE
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_existing,
        'action', 'reused'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'engagement_id', p_engagement_id,
    'jobs_created', v_created,
    'jobs_reused', v_skipped,
    'results', v_results
  );
END;
$$;


--
-- Name: lifecycle_grant_portal_access(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_grant_portal_access(p_entity_type text, p_entity_id uuid, p_email text, p_role text DEFAULT 'primary_contact'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_organization_id uuid;
  v_user_id uuid;
  v_portal_access_id uuid;
  v_invite_token text;
  v_invite_expires_at timestamptz;
  v_entity_name text;
  v_firm_name text;
  v_portal_url text;
BEGIN
  IF p_entity_type = 'client' THEN
    SELECT organization_id, (first_name || ' ' || last_name)
    INTO v_organization_id, v_entity_name
    FROM clients WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Client not found: %', p_entity_id;
    END IF;
  ELSIF p_entity_type = 'company' THEN
    SELECT organization_id, company_name
    INTO v_organization_id, v_entity_name
    FROM companies WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Company not found: %', p_entity_id;
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid entity_type: %. Must be "client" or "company"', p_entity_type;
  END IF;

  IF NOT user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT name INTO v_firm_name FROM organizations WHERE id = v_organization_id;
  SELECT id INTO v_user_id FROM auth.users WHERE email = p_email LIMIT 1;

  v_invite_token := generate_invite_token();
  v_invite_expires_at := now() + interval '14 days';

  INSERT INTO portal_access (
    organization_id, user_id, client_id, company_id, role, status, is_active,
    invite_token, invite_expires_at, invited_at, created_by
  )
  VALUES (
    v_organization_id, v_user_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    p_role, 'invited', true, v_invite_token, v_invite_expires_at, now(), auth.uid()
  )
  RETURNING id INTO v_portal_access_id;

  v_portal_url := 'https://client.accountancyos.com/auth/portal-invite?token=' || v_invite_token;

  INSERT INTO email_queue (
    organization_id, to_email, subject, body_html, entity_type, entity_id, merge_data, status, context
  )
  VALUES (
    v_organization_id,
    p_email,
    'You have passed AML verification - set up your ' || v_firm_name || ' client portal',
    '<p>Hello ' || v_entity_name || ',</p>' ||
    '<p>Good news - you have successfully passed our AML (Anti-Money Laundering) verification checks with ' || v_firm_name || '.</p>' ||
    '<p>The final step is to set up your secure client portal login. From the portal you can view your jobs, share documents, approve work, and message us directly.</p>' ||
    '<p><a href="' || v_portal_url || '" style="display:inline-block;padding:10px 18px;background:#0f766e;color:#ffffff;text-decoration:none;border-radius:6px;">Set up your client portal</a></p>' ||
    '<p>This link is valid for 14 days. If it expires, just let us know and we will reissue it.</p>' ||
    '<p>Kind regards,<br/>' || v_firm_name || '</p>',
    'portal_access',
    v_portal_access_id,
    jsonb_build_object(
      'client_name', v_entity_name,
      'firm_name', v_firm_name,
      'portal_url', v_portal_url
    ),
    'pending',
    'onboarding'
  );

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (
    v_organization_id, 'portal_access', v_portal_access_id, 'invited', auth.uid(),
    jsonb_build_object('email', p_email, 'target_entity_type', p_entity_type, 'target_entity_id', p_entity_id, 'role', p_role)
  );

  RETURN jsonb_build_object(
    'portal_access_id', v_portal_access_id,
    'invite_token', v_invite_token,
    'invite_expires_at', v_invite_expires_at,
    'email_queued', true,
    'user_exists', v_user_id IS NOT NULL,
    'ok', true
  );
END;
$$;


--
-- Name: lifecycle_materialize_jobs(uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_materialize_jobs(p_org uuid, p_client_id uuid, p_company_id uuid, p_partnership_id uuid, p_quote_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := CURRENT_DATE;
  v_company record;
  v_tax_year_start date; v_tax_year_end date;
  v_line record; v_frequency text;
  v_target_client uuid; v_target_company uuid; v_engagement_id uuid;
  v_period_start date; v_period_end date; v_period_label text;
  v_jobs int := 0;
BEGIN
  IF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
  ELSE
    SELECT NULL::uuid AS id, NULL::int AS year_end_month, NULL::int AS year_end_day INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  FOR v_line IN
    SELECT ql.*, sc.entity_scope, sc.code, sc.name AS service_name
    FROM public.quote_lines ql
    JOIN public.services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
  LOOP
    v_frequency := CASE WHEN v_line.billing_frequency = 'monthly' THEN 'monthly' ELSE 'one_off' END;

    IF v_line.entity_scope = 'company'
       OR (v_line.entity_scope = 'either' AND p_company_id IS NOT NULL
           AND v_line.code NOT IN ('sa_mtd','sa_non_mtd','cgt_60_day')) THEN
      v_target_company := p_company_id; v_target_client := NULL;
    ELSIF v_line.entity_scope = 'partnership' THEN
      v_target_client := COALESCE(p_partnership_id, p_client_id); v_target_company := NULL;
    ELSE
      v_target_client := p_client_id; v_target_company := NULL;
    END IF;
    IF v_target_client IS NULL AND v_target_company IS NULL THEN CONTINUE; END IF;

    SELECT id INTO v_engagement_id FROM public.engagements
      WHERE quote_id = p_quote_id AND service_id = v_line.service_id LIMIT 1;
    IF v_engagement_id IS NULL THEN
      INSERT INTO public.engagements
        (organization_id, client_id, company_id, service_id, quote_id, frequency, start_date, status, activated_at)
      VALUES
        (p_org, v_target_client, v_target_company, v_line.service_id, p_quote_id, v_frequency, v_today, 'active', now())
      RETURNING id INTO v_engagement_id;
    END IF;

    v_period_start := NULL; v_period_end := NULL; v_period_label := NULL;
    IF v_target_company IS NOT NULL AND v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSIF v_line.code IN ('sa_mtd','sa_non_mtd') THEN
      v_period_start := v_tax_year_start; v_period_end := v_tax_year_end;
      v_period_label := EXTRACT(YEAR FROM v_tax_year_start)::text || '/' || substr(EXTRACT(YEAR FROM v_tax_year_end)::text, 3, 2);
    ELSIF v_line.code = 'payroll' THEN
      v_period_start := date_trunc('month', v_today)::date;
      v_period_end := (date_trunc('month', v_today) + INTERVAL '1 month - 1 day')::date;
      v_period_label := to_char(v_today, 'Mon YYYY');
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;

    -- Proposal Phase 1 T1 (the ONLY behavioural change): an explicit per-line period set on
    -- the quote_line wins over the computed fallback above. Fully backward-compatible — a NULL
    -- line period (every pre-existing line) falls straight through to the computed value.
    v_period_start := COALESCE(v_line.period_start, v_period_start);
    v_period_end   := COALESCE(v_line.period_end,   v_period_end);
    v_period_label := COALESCE(NULLIF(v_line.period_label, ''), v_period_label);

    PERFORM public.lifecycle_upsert_job_with_deadlines(
      p_org, v_target_client, v_target_company, v_engagement_id,
      v_line.code, v_line.service_name, v_period_start, v_period_end, v_period_label, p_source);
    v_jobs := v_jobs + 1;
  END LOOP;

  -- Proposal Phase 1 T6b-2 (the ONLY addition in this migration): a CT600 job depends on
  -- the finalised Accounts for the SAME company + SAME accounts year-end. Idempotent —
  -- only writes when the link differs, and only when we are materializing for a company.
  -- The ct.period_end IS NOT NULL guard prevents a NULL period_end from cross-linking a
  -- CT600 to an Accounts job of a different (or unknown) accounts year.
  IF p_company_id IS NOT NULL THEN
    UPDATE public.jobs ct
       SET prerequisite_job_id = acc.id
      FROM public.jobs acc
     WHERE ct.organization_id = p_org
       AND ct.company_id      = p_company_id
       AND ct.service_type    = 'corporation_tax'
       AND ct.period_end      IS NOT NULL
       AND acc.organization_id = p_org
       AND acc.company_id      = p_company_id
       AND acc.service_type    = 'company_accounts'
       AND acc.period_end      = ct.period_end          -- same accounts year-end
       AND ct.prerequisite_job_id IS DISTINCT FROM acc.id;
  END IF;

  RETURN jsonb_build_object('status','ok','services', v_jobs);
END;
$$;


--
-- Name: lifecycle_onboarding_gates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_onboarding_gates(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a                  public.onboarding_applications%ROWTYPE;
  v_el_signed        boolean := false;
  v_aml              boolean := false;
  v_billing          boolean := false;
  v_submitted        boolean := false;
  v_open             boolean := false;
  v_context          boolean := false;
  v_has_lines        boolean := false;
  v_activation_ready boolean := false;
  v_letter_id        uuid;
  v_sig              jsonb;
  v_outstanding      text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RETURN jsonb_build_object('error', 'application_not_found', 'all_pass', false,
                              'activation_ready', false,
                              'outstanding', to_jsonb(ARRAY['application_not_found']));
  END IF;

  -- T2b: engagement-letter signature via the signature RULE over engagement_letter_signatories,
  -- with the legacy single-signer check as fallback when no signatory rows exist.
  -- T2d-1: the rule itself now lives in public.el_signature_progress (one implementation).
  -- Equivalence with the T2b inline block: has_signatories mirrors the previous
  -- EXISTS(required rows) branch test, and `satisfied` computes the same
  -- 'any' => signed >= 1 / 'all' => total > 0 AND signed = total over the same rows.
  SELECT el.id INTO v_letter_id
    FROM public.engagement_letters el
   WHERE el.onboarding_application_id = p_application_id
   ORDER BY el.created_at DESC
   LIMIT 1;

  v_sig := public.el_signature_progress(v_letter_id);

  IF COALESCE((v_sig->>'has_signatories')::boolean, false) THEN
    v_el_signed := COALESCE((v_sig->>'satisfied')::boolean, false);
  ELSE
    -- Legacy fallback: unchanged from the live body (signed letter + contracts_signed_at).
    v_el_signed := (
      EXISTS (
        SELECT 1 FROM public.engagement_letters el
        WHERE el.onboarding_application_id = p_application_id AND el.signed_at IS NOT NULL
      )
      AND a.contracts_signed_at IS NOT NULL
    );
  END IF;

  v_aml       := (a.aml_status = 'verified');
  v_billing   := (a.billing_status IN ('completed','skipped','not_required'));
  v_submitted := (a.submitted_for_review_at IS NOT NULL OR a.status IN ('portal_pending','for_review'));
  v_open      := (a.status NOT IN ('approved','rejected','cancelled'));

  SELECT EXISTS (SELECT 1 FROM public.quote_lines ql WHERE ql.quote_id = a.quote_id) INTO v_has_lines;
  v_context := (
    a.organization_id IS NOT NULL
    AND a.quote_id IS NOT NULL
    AND v_has_lines
    AND (a.client_id IS NOT NULL OR a.company_id IS NOT NULL
         OR a.application_type IN ('individual','company'))
  );

  IF NOT v_el_signed THEN v_outstanding := v_outstanding || 'engagement_letter_signed'; END IF;
  IF NOT v_aml       THEN v_outstanding := v_outstanding || 'aml_passed'; END IF;
  IF NOT v_billing   THEN v_outstanding := v_outstanding || 'billing_settled'; END IF;
  IF NOT v_submitted THEN v_outstanding := v_outstanding || 'onboarding_submitted'; END IF;
  IF NOT v_open      THEN v_outstanding := v_outstanding || 'not_already_closed'; END IF;
  IF NOT v_context   THEN v_outstanding := v_outstanding || 'missing_activation_context'; END IF;

  -- T2b: activation gates on signatures/AML/submission/open/context — NOT billing.
  v_activation_ready := (v_el_signed AND v_aml AND v_submitted AND v_open AND v_context);

  RETURN jsonb_build_object(
    'gates', jsonb_build_object(
      'engagement_letter_signed', v_el_signed,
      'aml_passed', v_aml,
      'billing_settled', v_billing,
      'onboarding_submitted', v_submitted,
      'not_already_closed', v_open,
      'activation_context_present', v_context
    ),
    'all_pass', (array_length(v_outstanding, 1) IS NULL),
    'activation_ready', v_activation_ready,
    'billing_settled', v_billing,
    'outstanding', to_jsonb(v_outstanding)
  );
END;
$$;


--
-- Name: FUNCTION lifecycle_onboarding_gates(p_application_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lifecycle_onboarding_gates(p_application_id uuid) IS 'Sprint 1: read-only canonical activation gates for an onboarding application. Returns {gates, all_pass, outstanding}. Shared by lifecycle_evaluate_onboarding_activation and the lifecycle_approve_onboarding guard. Writes nothing.';


--
-- Name: lifecycle_reconciliation_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_reconciliation_report(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jobs_total       int;
  v_setup_pending    int;
  v_null_label       int;
  v_both_entity      int;
  v_dup_groups       int;
  v_dup_excess       int;
  v_null_dup_groups  int;
  v_active_links     int;
  v_accepted_no_onb  int;
  v_onb_unlinked     int;
  v_dup_onb_groups   int;
  v_present          text[];
  v_expected         text[] := ARRAY['jobs_client_period_uq','jobs_company_period_uq',
                                     'engagements_quote_service_uq','acl_active_client_uq',
                                     'acl_active_company_uq'];
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
     WHERE organization_id = p_organization_id AND user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  SELECT count(*) INTO v_jobs_total
    FROM public.jobs WHERE organization_id = p_organization_id;

  SELECT count(*) INTO v_setup_pending
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label ILIKE 'Setup Pending';

  SELECT count(*) INTO v_null_label
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label IS NULL AND status <> 'cancelled';

  SELECT count(*) INTO v_both_entity
    FROM public.jobs
   WHERE organization_id = p_organization_id
     AND client_id IS NOT NULL AND company_id IS NOT NULL;

  WITH grp AS (
    SELECT count(*) AS n FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled'
     GROUP BY service_type, client_id, company_id, period_label HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0), COALESCE(sum(n - 1),0) INTO v_dup_groups, v_dup_excess FROM grp;

  WITH ngrp AS (
    SELECT 1 FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled' AND period_label IS NULL
     GROUP BY service_type, client_id, company_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_null_dup_groups FROM ngrp;

  SELECT count(*) INTO v_active_links
    FROM public.accountant_client_links
   WHERE practice_id = p_organization_id AND status = 'active';

  SELECT count(*) INTO v_accepted_no_onb
    FROM public.quotes q
   WHERE q.organization_id = p_organization_id
     AND q.status = 'accepted'
     AND NOT EXISTS (
       SELECT 1 FROM public.onboarding_applications o
        WHERE o.quote_id = q.id AND o.status <> 'rejected');

  SELECT count(*) INTO v_onb_unlinked
    FROM public.onboarding_applications o
   WHERE o.organization_id = p_organization_id
     AND o.status NOT IN ('approved','rejected')
     AND o.client_id IS NULL AND o.company_id IS NULL;

  WITH og AS (
    SELECT quote_id FROM public.onboarding_applications
     WHERE organization_id = p_organization_id AND quote_id IS NOT NULL AND status <> 'rejected'
     GROUP BY quote_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_dup_onb_groups FROM og;

  SELECT COALESCE(array_agg(indexname), ARRAY[]::text[]) INTO v_present
    FROM pg_indexes
   WHERE schemaname = 'public' AND indexname = ANY(v_expected);

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', p_organization_id,
    'jobs_total', v_jobs_total,
    'setup_pending_jobs', v_setup_pending,
    'null_period_label_jobs', v_null_label,
    'both_entity_jobs', v_both_entity,
    'duplicate_job_groups', v_dup_groups,
    'duplicate_job_excess_rows', v_dup_excess,
    'null_label_duplicate_groups', v_null_dup_groups,
    'active_client_links', v_active_links,
    'accepted_quotes_without_onboarding', v_accepted_no_onb,
    'onboarding_apps_unlinked', v_onb_unlinked,
    'duplicate_onboarding_app_groups', v_dup_onb_groups,
    'backstop_indexes_present', to_jsonb(v_present),
    'backstop_indexes_missing', to_jsonb(ARRAY(SELECT unnest(v_expected) EXCEPT SELECT unnest(v_present)))
  );
END;
$$;


--
-- Name: lifecycle_require_onboarding_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_require_onboarding_token(p_application_id uuid, p_access_token text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_access_token IS NULL
     OR NOT public.validate_onboarding_access_token(p_application_id, p_access_token) THEN
    RAISE EXCEPTION 'Invalid or missing onboarding access token' USING ERRCODE='42501';
  END IF;
END;
$$;


--
-- Name: lifecycle_send_back_onboarding(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_send_back_onboarding(p_application_id uuid, p_step text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app RECORD;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Onboarding application % not found', p_application_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'needs_client_action',
         updated_at = now()
   WHERE id = p_application_id;

  IF v_app.email IS NOT NULL AND v_app.email <> '' THEN
    INSERT INTO public.email_queue (
      organization_id, to_email, to_name, subject, body_html,
      entity_type, entity_id, context, status
    ) VALUES (
      v_app.organization_id,
      v_app.email,
      COALESCE(v_app.company_name, TRIM(COALESCE(v_app.first_name,'') || ' ' || COALESCE(v_app.last_name,''))),
      'Action required to complete your onboarding',
      '<p>Hello,</p><p>Your accountant has reviewed your onboarding and needs you to revisit the <strong>' || p_step || '</strong> step.</p>' ||
      CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN '<p><em>' || p_reason || '</em></p>' ELSE '' END ||
      '<p>Please continue here: <a href="' || COALESCE(current_setting('app.public_url', true), '') || '/onboard/' || p_application_id || '">Resume onboarding</a></p>',
      'onboarding_application',
      p_application_id,
      'onboarding',
      'pending'
    );
  END IF;

  RETURN jsonb_build_object('status', 'needs_client_action');
END;
$$;


--
-- Name: lifecycle_send_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_send_quote(p_quote_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote               record;
  v_line_count          integer;
  v_recipient_email     text;
  v_recipient_name      text;
  v_recipient_first     text;
  v_preferred           text;
  v_first               text;
  v_last                text;
  v_email_queued        boolean := false;
  v_practice_name       text;
  v_template_id         uuid;
  v_template_content    jsonb;
  v_token               uuid;
  v_valid_until         date;
  v_lines_html          text := '';
  v_line                record;
  v_freq_label          text;
  v_unit_display        numeric;
  v_subtotal_display    numeric;
  v_unit_suffix         text;
  v_subtotal_suffix     text;
  v_total_now           numeric := 0;
  v_total_monthly       numeric := 0;
  v_base_url            text := 'https://app.accountancyos.com';
  v_subject             text;
  v_body_html           text;
  v_merge               jsonb;
  v_key                 text;
  v_val                 text;
  v_currency            text;
  v_accept_url          text;
  v_mailbox_id          uuid;
  v_mailbox_provider    text;
  v_mailbox_from        text;
  v_creator             uuid;
BEGIN
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id;
  IF v_quote.id IS NULL THEN RAISE EXCEPTION 'Quote not found: %', p_quote_id; END IF;
  IF NOT user_has_organization_access(v_quote.organization_id) THEN RAISE EXCEPTION 'Access denied to organization'; END IF;
  IF v_quote.status != 'draft' THEN RAISE EXCEPTION 'Quote cannot be sent. Current status: %. Only draft quotes can be sent.', v_quote.status; END IF;

  SELECT COUNT(*) INTO v_line_count FROM quote_lines WHERE quote_id = p_quote_id;
  IF v_line_count = 0 THEN RAISE EXCEPTION 'Quote has no line items. Add services before sending.'; END IF;

  v_valid_until := COALESCE(v_quote.valid_until, (now() + interval '30 days')::date);
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_creator := COALESCE(v_quote.created_by, auth.uid());

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT email, first_name, last_name
      INTO v_recipient_email, v_first, v_last
    FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT email, preferred_name, first_name, last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_email IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT c.email, c.preferred_name, c.first_name, c.last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients c
    WHERE c.company_id = v_quote.company_id
      AND c.email IS NOT NULL
    ORDER BY c.created_at ASC
    LIMIT 1;

    IF v_recipient_email IS NULL THEN
      SELECT email INTO v_recipient_email FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  v_recipient_first := COALESCE(NULLIF(trim(v_preferred), ''), NULLIF(trim(v_first), ''));
  v_recipient_name  := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_first,'') || ' ' || coalesce(v_last,'')), '')
  );

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    v_recipient_first := COALESCE(v_recipient_first, v_recipient_name);
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o
  LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_creator IS NOT NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND user_id = v_creator
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_mailbox_id IS NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  SELECT id, content INTO v_template_id, v_template_content
  FROM templates
  WHERE organization_id = v_quote.organization_id
    AND type = 'email'
    AND (
          COALESCE(tags, '[]'::jsonb) ? 'quote'
       OR name ILIKE '%quote%'
       OR name ILIKE '%proposal%'
        )
    AND COALESCE(status, 'active') = 'active'
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1;

  FOR v_line IN
    SELECT ql.*, sc.name AS service_name
    FROM quote_lines ql
    LEFT JOIN services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
    ORDER BY ql.line_order
  LOOP
    IF v_line.billing_frequency = 'monthly' THEN
      v_freq_label := 'Monthly';
      v_unit_display := ROUND(COALESCE(v_line.unit_price,0) / 12.0, 2);
      v_subtotal_display := ROUND(v_unit_display * COALESCE(v_line.quantity,1), 2);
      v_unit_suffix := '/mo';
      v_subtotal_suffix := '/mo';
      v_total_monthly := v_total_monthly + v_subtotal_display;
    ELSE
      v_freq_label := 'Bill Now';
      v_unit_display := COALESCE(v_line.unit_price, 0);
      v_subtotal_display := COALESCE(v_line.subtotal, v_unit_display * COALESCE(v_line.quantity,1));
      v_unit_suffix := '';
      v_subtotal_suffix := '';
      v_total_now := v_total_now + v_subtotal_display;
    END IF;

    v_lines_html := v_lines_html ||
      '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">' || COALESCE(v_line.service_name, 'Service') ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || COALESCE(v_line.quantity,1) ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_unit_display, 'FM999,999,990.00') || v_unit_suffix ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_subtotal_display, 'FM999,999,990.00') || v_subtotal_suffix ||
      '</td></tr>';
  END LOOP;

  v_lines_html :=
    '<table style="border-collapse:collapse;width:100%;margin:12px 0">' ||
    '<thead><tr>' ||
    '<th style="text-align:left;padding:6px 8px;border-bottom:2px solid #ccc">Service</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Qty</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Unit</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Subtotal</th>' ||
    '</tr></thead><tbody>' || v_lines_html || '</tbody></table>';

  v_token := gen_random_uuid();
  INSERT INTO quote_acceptance_tokens(token, quote_id, organization_id, expires_at)
  VALUES (v_token, p_quote_id, v_quote.organization_id, now() + interval '30 days');

  v_accept_url := v_base_url || '/q/' || v_token::text;

  v_merge := jsonb_build_object(
    'recipient_name', v_recipient_name,
    'recipient_first_name', v_recipient_first,
    'practice_name', v_practice_name,
    'quote_number', v_quote.quote_number,
    'currency', v_currency,
    'total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'total_amount', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'valid_until', to_char(v_valid_until, 'DD Mon YYYY'),
    'accept_url', v_accept_url,
    'lines_html', v_lines_html,
    'quote_total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'quote_total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'quote_total', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'accept_link', v_accept_url,
    'quote_lines_table', v_lines_html
  );

  IF v_template_content IS NOT NULL THEN
    v_subject   := COALESCE(v_template_content->>'subject', 'Proposal from ' || v_practice_name);
    v_body_html := COALESCE(
      NULLIF(v_template_content->>'htmlBody', ''),
      NULLIF(v_template_content->>'body_html', ''),
      NULLIF(v_template_content->>'body', ''),
      ''
    );
    FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_merge) LOOP
      v_subject   := replace(v_subject, '{{' || v_key || '}}', COALESCE(v_val,''));
      v_body_html := replace(v_body_html, '{{' || v_key || '}}', COALESCE(v_val,''));
    END LOOP;
  ELSE
    v_subject := 'Proposal ' || v_quote.quote_number || ' from ' || v_practice_name;
    v_body_html :=
      '<p>Dear ' || COALESCE(v_recipient_first, v_recipient_name, 'Client') || ',</p>' ||
      '<p>Please find your proposal below.</p>' ||
      v_lines_html ||
      '<p><strong>Payable Now:</strong> ' || v_currency || ' ' || to_char(v_total_now, 'FM999,999,990.00') || '<br/>' ||
      '<strong>Payable Monthly:</strong> ' || v_currency || ' ' || to_char(v_total_monthly, 'FM999,999,990.00') || '</p>' ||
      '<p><a href="' || v_accept_url || '">Review and accept your proposal</a></p>' ||
      '<p>Kind regards,<br/>' || v_practice_name || '</p>';
  END IF;

  IF v_body_html !~ '<[a-zA-Z]' THEN
    v_body_html := replace(v_body_html, E'\n', '<br/>');
  END IF;

  IF v_recipient_email IS NOT NULL THEN
    INSERT INTO email_queue (
      organization_id, client_id, company_id,
      entity_type, entity_id, context,
      to_email, to_name, subject, body_html,
      mailbox_id, provider, created_by, queued_by,
      status, scheduled_at, created_at
    ) VALUES (
      v_quote.organization_id, v_quote.client_id, v_quote.company_id,
      'quote', v_quote.id, 'quote',
      v_recipient_email, v_recipient_name, v_subject, v_body_html,
      v_mailbox_id, v_mailbox_provider, v_creator, auth.uid(),
      'pending', now() + interval '15 minutes', now()
    );
    v_email_queued := true;
  END IF;

  UPDATE quotes
     SET status = 'sent',
         sent_at = COALESCE(sent_at, now()),
         valid_until = v_valid_until,
         updated_at = now()
   WHERE id = p_quote_id;

  RETURN jsonb_build_object(
    'quote_id', p_quote_id,
    'status', 'sent',
    'email_queued', v_email_queued,
    'recipient_email', v_recipient_email,
    'recipient_name', v_recipient_name,
    'sender_mailbox', v_mailbox_from,
    'sender_provider', v_mailbox_provider
  );
END;
$$;


--
-- Name: lifecycle_upsert_job_with_deadlines(uuid, uuid, uuid, uuid, text, text, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_upsert_job_with_deadlines(p_org uuid, p_client_id uuid, p_company_id uuid, p_engagement_id uuid, p_service_code text, p_service_name text, p_period_start date, p_period_end date, p_period_label text, p_source text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing_deadline date;
  v_job_id uuid;
BEGIN
  v_filing_deadline := CASE p_service_code
    WHEN 'company_accounts' THEN public.calculate_deadline('companies_house_accounts', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'confirmation_statement' THEN public.calculate_deadline('companies_house_confirmation', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'corporation_tax' THEN public.calculate_deadline('corporation_tax_filing', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_non_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'vat_return' THEN public.calculate_deadline('vat_return', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'payroll' THEN public.calculate_deadline('payroll_fps', p_period_start, p_period_end, '{}'::jsonb)
    ELSE NULL
  END;

  SELECT id INTO v_job_id FROM public.jobs
    WHERE organization_id = p_org
      AND service_type = p_service_code
      AND COALESCE(client_id::text,'') = COALESCE(p_client_id::text,'')
      AND COALESCE(company_id::text,'') = COALESCE(p_company_id::text,'')
      AND COALESCE(period_label,'') = COALESCE(p_period_label,'')
    LIMIT 1;

  IF v_job_id IS NULL THEN
    INSERT INTO public.jobs (organization_id, client_id, company_id, job_name, service_type,
                             period_start, period_end, period_label, status, priority,
                             filing_deadline, automation_source, is_auto_generated, auto_generated_at,
                             generation_reason)
    VALUES (p_org, p_client_id, p_company_id,
            p_service_name || ' - ' || COALESCE(p_period_label,'Setup Pending'),
            p_service_code, p_period_start, p_period_end, p_period_label,
            'blank', 'normal', v_filing_deadline, 'template', true, now(),
            p_source)
    RETURNING id INTO v_job_id;
  END IF;

  IF v_filing_deadline IS NOT NULL AND p_service_code IN ('company_accounts','confirmation_statement','corporation_tax','sa_mtd','sa_non_mtd','vat_return','payroll') THEN
    INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                  name, deadline_type, filing_body, service_code,
                                  period_start, period_end, due_date, warning_date, status)
    SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
           p_service_name || ' - ' || COALESCE(p_period_label,''),
           'statutory',
           CASE p_service_code
             WHEN 'company_accounts' THEN 'COMPANIES_HOUSE'
             WHEN 'confirmation_statement' THEN 'COMPANIES_HOUSE'
             ELSE 'HMRC'
           END,
           p_service_code, p_period_start, p_period_end, v_filing_deadline,
           v_filing_deadline - INTERVAL '30 days', 'pending'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.deadlines
      WHERE job_id = v_job_id AND service_code = p_service_code AND due_date = v_filing_deadline
    );

    IF p_service_code = 'corporation_tax' THEN
      INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                    name, deadline_type, filing_body, service_code,
                                    period_start, period_end, due_date, warning_date, status)
      SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
             'Corporation Tax Payment - ' || COALESCE(p_period_label,''),
             'statutory', 'HMRC', 'corporation_tax_payment',
             p_period_start, p_period_end,
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb),
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb) - INTERVAL '30 days',
             'pending'
      WHERE NOT EXISTS (
        SELECT 1 FROM public.deadlines
        WHERE job_id = v_job_id AND service_code = 'corporation_tax_payment'
      );
    END IF;
  END IF;

  RETURN v_job_id;
END;
$$;


--
-- Name: link_onboarding_documents_on_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_onboarding_documents_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'approved'
     AND (TG_OP = 'INSERT'
          OR OLD.status IS DISTINCT FROM NEW.status
          OR OLD.client_id  IS DISTINCT FROM NEW.client_id
          OR OLD.company_id IS DISTINCT FROM NEW.company_id) THEN
    UPDATE public.onboarding_documents
       SET client_id  = NEW.client_id,
           company_id = NEW.company_id
     WHERE application_id = NEW.id
       AND (client_id  IS DISTINCT FROM NEW.client_id
         OR company_id IS DISTINCT FROM NEW.company_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: link_person_to_sa_client(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_person_to_sa_client(p_person_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_client_org_id uuid;
BEGIN
  SELECT organization_id INTO v_organization_id
  FROM public.company_persons WHERE id = p_person_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Person not found: %', p_person_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT organization_id INTO v_client_org_id
  FROM public.clients WHERE id = p_client_id;

  IF v_client_org_id IS NULL THEN
    RAISE EXCEPTION 'Client not found: %', p_client_id;
  END IF;

  IF v_client_org_id <> v_organization_id THEN
    RAISE EXCEPTION 'Client % belongs to a different organization than person %', p_client_id, p_person_id;
  END IF;

  UPDATE public.company_persons
  SET linked_client_id = p_client_id
  WHERE id = p_person_id;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'linked_client_id', p_client_id
  );
END;
$$;


--
-- Name: lock_period(uuid, text, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_lock_date date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_existing_lock date;
  v_unposted_count int;
  v_lock_id uuid;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF NOT (public.has_organization_role(p_organization_id, 'owner')
       OR public.has_organization_role(p_organization_id, 'admin')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only owners or admins may lock periods');
  END IF;
  IF p_entity_type NOT IN ('client','company') THEN
    RETURN jsonb_build_object('success', false, 'error', 'entity_type must be client or company');
  END IF;

  SELECT count(*) INTO v_unposted_count
  FROM public.journals j
  WHERE j.organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND j.client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND j.company_id = p_entity_id))
    AND j.journal_date <= p_lock_date
    AND j.status = 'DRAFT';

  IF v_unposted_count > 0 THEN
    RETURN jsonb_build_object('success', false,
      'error', format('%s draft journal(s) on or before %s must be posted or voided first', v_unposted_count, p_lock_date));
  END IF;

  SELECT lock_date INTO v_existing_lock FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND company_id = p_entity_id));

  IF v_existing_lock IS NOT NULL AND p_lock_date < v_existing_lock THEN
    RETURN jsonb_build_object('success', false,
      'error', format('Lock date cannot move backwards. Current lock: %s. Use unlock_period first.', v_existing_lock));
  END IF;

  INSERT INTO public.period_locks(organization_id, client_id, company_id, lock_date, locked_by, reason)
  VALUES (p_organization_id,
    CASE WHEN p_entity_type='client'  THEN p_entity_id END,
    CASE WHEN p_entity_type='company' THEN p_entity_id END,
    p_lock_date, v_user, p_reason)
  ON CONFLICT (organization_id, client_id, company_id)
  DO UPDATE SET lock_date = EXCLUDED.lock_date, locked_by = EXCLUDED.locked_by,
                locked_at = now(), reason = EXCLUDED.reason
  RETURNING id INTO v_lock_id;

  RETURN jsonb_build_object('success', true, 'lock_id', v_lock_id, 'lock_date', p_lock_date);
END; $$;


--
-- Name: log_onboarding_event(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_onboarding_event(p_application_id uuid, p_event_type text, p_from_status text DEFAULT NULL::text, p_to_status text DEFAULT NULL::text, p_actor_kind text DEFAULT 'system'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_event_id uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM onboarding_applications WHERE id = p_application_id;

  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO onboarding_events (
    organization_id, application_id, event_type, from_status, to_status,
    actor_user_id, actor_kind, metadata
  ) VALUES (
    v_org, p_application_id, p_event_type, p_from_status, p_to_status,
    auth.uid(), p_actor_kind, COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


--
-- Name: log_portal_bookkeeping_action(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_portal_bookkeeping_action(_entity_type text, _entity_id uuid, _action text, _details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_log_id uuid;
  v_client_id uuid;
  v_company_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF _entity_type NOT IN ('client','company') THEN RAISE EXCEPTION 'bad_entity_type'; END IF;

  IF _entity_type = 'client' THEN v_client_id := _entity_id; ELSE v_company_id := _entity_id; END IF;

  IF NOT public.portal_can_access_bookkeeping(v_client_id, v_company_id) THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  IF _entity_type = 'client' THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = _entity_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = _entity_id;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'entity_not_found'; END IF;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, metadata)
  VALUES (v_org, _entity_type, _entity_id, _action, v_uid, 'portal_client',
          jsonb_build_object('source','portal') || COALESCE(_details, '{}'::jsonb))
  RETURNING id INTO v_log_id;

  RETURN v_log_id;
END
$$;


--
-- Name: log_portal_bookkeeping_revocation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_portal_bookkeeping_revocation(_organization_id uuid, _client_id uuid, _company_id uuid, _reason text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, reason, actor_id)
  VALUES (
    _organization_id,
    CASE WHEN _client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(_client_id, _company_id),
    'portal_access_revoked',
    COALESCE(_reason, 'Bookkeeping service deactivated'),
    auth.uid()
  );
$$;


--
-- Name: mark_lead_dormant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_lead_dormant(p_lead_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.leads WHERE id = p_lead_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Lead not found'; END IF;
  IF NOT user_has_organization_access(v_org) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'LEAD_DORMANT', 'lead', p_lead_id, jsonb_build_object('reason', p_reason));
END;
$$;


--
-- Name: mark_lead_lost(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_lead_lost(p_lead_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.leads WHERE id = p_lead_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Lead not found'; END IF;
  IF NOT user_has_organization_access(v_org) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  UPDATE public.leads SET pipeline_stage = 'lost', lost_at = now(),
                          lost_reason = coalesce(p_reason, lost_reason)
   WHERE id = p_lead_id;
  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'LEAD_LOST', 'lead', p_lead_id, jsonb_build_object('reason', p_reason));
END;
$$;


--
-- Name: mcp_cron_job_health(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_cron_job_health(p_window_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.jobname), '[]'::jsonb)
  FROM (
    SELECT
      j.jobname,
      j.schedule,
      j.active,
      count(d.runid)                                                    AS runs,
      count(*) FILTER (WHERE d.status = 'succeeded')                    AS succeeded,
      count(*) FILTER (WHERE d.status IS NOT NULL
                         AND d.status <> 'succeeded')                   AS failed,
      max(d.start_time)                                                 AS last_run_at,
      (ARRAY_AGG(d.status ORDER BY d.start_time DESC)
         FILTER (WHERE d.status IS NOT NULL))[1]                        AS last_status,
      public.redact_secrets(
        (ARRAY_AGG(d.return_message ORDER BY d.start_time DESC)
           FILTER (WHERE d.return_message IS NOT NULL))[1]
      )                                                                 AS last_message,
      -- The DEF-018 signature. Surfaced explicitly so a regression is unmistakable
      -- rather than something to be inferred from an error string.
      count(*) FILTER (
        WHERE d.return_message ILIKE '%unrecognized configuration parameter%'
      )                                                                 AS unrecognized_parameter_failures
    FROM cron.job j
    LEFT JOIN cron.job_run_details d
      ON d.jobid = j.jobid
     AND d.start_time > now() - make_interval(mins => greatest(p_window_minutes, 1))
    GROUP BY j.jobname, j.schedule, j.active
  ) t;
$$;


--
-- Name: FUNCTION mcp_cron_job_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_cron_job_health(p_window_minutes integer) IS 'Read-only cron health projection. cron.job_run_details is unreadable by the executor role and by the database connector, which is why DEF-018 (26,208 silent failures) was undetectable. DEF-019.';


--
-- Name: mcp_http_delivery_health(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_http_delivery_health(p_window_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_result jsonb;
BEGIN
  -- pg_net's response relation is internal and has been renamed across versions. Report the
  -- fact rather than raising, so a verifier check fails with a legible reason.
  IF to_regclass('net._http_response') IS NULL THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'net._http_response is not present in this pg_net version; delivery cannot be verified from SQL.'
    );
  END IF;

  EXECUTE format($q$
    SELECT jsonb_build_object(
      'available', true,
      'window_minutes', %1$s,
      'total',        count(*),
      'succeeded_2xx',count(*) FILTER (WHERE status_code BETWEEN 200 AND 299),
      'unauthorized', count(*) FILTER (WHERE status_code IN (401, 403)),
      'client_error', count(*) FILTER (WHERE status_code BETWEEN 400 AND 499),
      'server_error', count(*) FILTER (WHERE status_code BETWEEN 500 AND 599),
      'timed_out',    count(*) FILTER (WHERE timed_out),
      'no_response',  count(*) FILTER (WHERE status_code IS NULL),
      'sample_errors', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'status_code', s.status_code,
                 'created', s.created,
                 'error', public.redact_secrets(s.error_msg)))
        FROM (
          SELECT status_code, created, error_msg
          FROM net._http_response
          WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
            AND (status_code IS NULL OR status_code >= 400)
          ORDER BY created DESC
          LIMIT 5
        ) s), '[]'::jsonb)
    )
    FROM net._http_response
    WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
  $q$, p_window_minutes)
  INTO v_result;

  RETURN v_result;
END;
$_$;


--
-- Name: FUNCTION mcp_http_delivery_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_http_delivery_health(p_window_minutes integer) IS 'Read-only HTTP delivery projection over net._http_response. pg_cron reports SQL success while net.http_post is asynchronous, so cron status alone cannot distinguish a delivered call from a 401. Never returns response content or headers. DEF-019.';


--
-- Name: mcp_list_cron_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_cron_jobs() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  result jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron')
     AND EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'cron') THEN
    EXECUTE $q$
      SELECT coalesce(jsonb_agg(row_to_json(j) ORDER BY j.jobname), '[]'::jsonb)
      FROM (
        SELECT jobid, schedule, jobname, command, active, database, username
        FROM cron.job
      ) j
    $q$ INTO result;
    RETURN coalesce(result, '[]'::jsonb);
  END IF;
  RETURN '[]'::jsonb;
END;
$_$;


--
-- Name: mcp_list_functions(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_functions(name_like text DEFAULT NULL::text, include_source boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                                     AS schema,
      p.proname                                     AS name,
      pg_get_function_identity_arguments(p.oid)     AS arguments,
      pg_get_function_result(p.oid)                 AS return_type,
      l.lanname                                     AS language,
      p.prosecdef                                   AS security_definer,
      CASE p.provolatile WHEN 'i' THEN 'immutable' WHEN 's' THEN 'stable' WHEN 'v' THEN 'volatile' END AS volatility,
      (
        SELECT string_agg(cfg, ', ')
        FROM unnest(coalesce(p.proconfig, ARRAY[]::text[])) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )                                             AS search_path,
      md5(pg_get_functiondef(p.oid))                AS definition_hash,
      CASE WHEN mcp_list_functions.include_source
           THEN pg_get_functiondef(p.oid)
           ELSE NULL END                            AS definition
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language  l ON l.oid = p.prolang
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      AND (mcp_list_functions.name_like IS NULL
           OR p.proname ILIKE '%' || mcp_list_functions.name_like || '%')
  ) t;
$$;


--
-- Name: mcp_list_grants(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_grants(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.grantee, t.privilege), '[]'::jsonb)
  FROM (
    SELECT
      g.table_schema   AS schema,
      g.table_name     AS "table",
      g.grantee,
      g.privilege_type AS privilege,
      g.is_grantable
    FROM information_schema.role_table_grants g
    WHERE g.table_schema = 'public'
      AND g.grantee IN ('anon','authenticated','service_role','postgres')
      AND (mcp_list_grants.table_name IS NULL OR g.table_name = mcp_list_grants.table_name)
  ) t;
$$;


--
-- Name: mcp_list_indexes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_indexes(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                          AS schema,
      c.relname                          AS "table",
      ic.relname                         AS name,
      i.indisunique                      AS is_unique,
      i.indisprimary                     AS is_primary,
      (i.indpred IS NOT NULL)            AS is_partial,
      pg_get_expr(i.indpred, i.indrelid) AS predicate,
      (
        SELECT array_agg(a.attname ORDER BY k.ord)
        FROM unnest(i.indkey) WITH ORDINALITY k(attnum, ord)
        JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = k.attnum
      )                                  AS columns,
      pg_get_indexdef(i.indexrelid)      AS definition
    FROM pg_index i
    JOIN pg_class    c  ON c.oid  = i.indrelid
    JOIN pg_class    ic ON ic.oid = i.indexrelid
    JOIN pg_namespace n ON n.oid  = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND (mcp_list_indexes.table_name IS NULL OR c.relname = mcp_list_indexes.table_name)
  ) t;
$$;


--
-- Name: mcp_list_policies(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_policies(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      pp.schemaname  AS schema,
      pp.tablename   AS "table",
      pp.policyname  AS name,
      pp.permissive,
      pp.roles,
      pp.cmd,
      pp.qual,
      pp.with_check
    FROM pg_policies pp
    WHERE pp.schemaname = 'public'
      AND (mcp_list_policies.table_name IS NULL OR pp.tablename = mcp_list_policies.table_name)
  ) t;
$$;


--
-- Name: mcp_list_rls_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_rls_status(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table"), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname             AS schema,
      c.relname             AS "table",
      c.relrowsecurity      AS rls_enabled,
      c.relforcerowsecurity AS rls_forced
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND (mcp_list_rls_status.table_name IS NULL OR c.relname = mcp_list_rls_status.table_name)
  ) t;
$$;


--
-- Name: mcp_list_schema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_schema() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb)
  FROM (
    SELECT c.table_name,
           jsonb_agg(jsonb_build_object(
             'column', c.column_name,
             'type', c.data_type,
             'nullable', c.is_nullable = 'YES',
             'default', c.column_default
           ) ORDER BY c.ordinal_position) AS cols
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND t.table_type = 'BASE TABLE'
    GROUP BY c.table_name
  ) s;
$$;


--
-- Name: mcp_list_triggers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_triggers(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                              AS schema,
      c.relname                              AS "table",
      tg.tgname                              AS name,
      CASE WHEN (tg.tgtype & 2) = 2 THEN 'BEFORE'
           WHEN (tg.tgtype & 64) = 64 THEN 'INSTEAD OF'
           ELSE 'AFTER' END                  AS timing,
      array_remove(ARRAY[
        CASE WHEN (tg.tgtype & 4)  = 4  THEN 'INSERT' END,
        CASE WHEN (tg.tgtype & 8)  = 8  THEN 'DELETE' END,
        CASE WHEN (tg.tgtype & 16) = 16 THEN 'UPDATE' END,
        CASE WHEN (tg.tgtype & 32) = 32 THEN 'TRUNCATE' END
      ], NULL)                               AS events,
      pn.nspname                             AS function_schema,
      p.proname                              AS function_name,
      tg.tgenabled <> 'D'                    AS enabled,
      pg_get_triggerdef(tg.oid)              AS definition
    FROM pg_trigger tg
    JOIN pg_class     c  ON c.oid  = tg.tgrelid
    JOIN pg_namespace n  ON n.oid  = c.relnamespace
    JOIN pg_proc      p  ON p.oid  = tg.tgfoid
    JOIN pg_namespace pn ON pn.oid = p.pronamespace
    WHERE NOT tg.tgisinternal
      AND n.nspname = 'public'
      AND (mcp_list_triggers.table_name IS NULL OR c.relname = mcp_list_triggers.table_name)
  ) t;
$$;


--
-- Name: mcp_vault_secret_present(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_vault_secret_present(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_secret text;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO v_secret
    FROM vault.decrypted_secrets
    WHERE name = p_name
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    -- Owner of this function cannot read the vault either. Say so rather than
    -- returning false, which would read as "the secret is missing".
    RAISE EXCEPTION 'vault.decrypted_secrets is not readable even as the function owner (%)', SQLERRM;
  END;

  RETURN v_secret IS NOT NULL AND length(btrim(v_secret)) > 0;
END;
$$;


--
-- Name: FUNCTION mcp_vault_secret_present(p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_vault_secret_present(p_name text) IS 'TRUE when a vault secret exists and is non-empty. Never returns the value. Cannot prove the value is current or valid — a rotated key is present, non-empty, and 401s on every call; only mcp_http_delivery_health can show that. DEF-019.';


--
-- Name: move_to_dlq(text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$$;


--
-- Name: notify_onboarding_approved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_onboarding_approved() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recipient_name text;
BEGIN
  IF NEW.status = 'approved' AND COALESCE(OLD.status,'') <> 'approved' THEN
    v_recipient_name := COALESCE(
      NULLIF(TRIM(CONCAT_WS(' ', NEW.first_name, NEW.last_name)), ''),
      NEW.company_name,
      'there'
    );

    INSERT INTO notifications (organization_id, user_id, type, title, message, entity_type, entity_id)
    SELECT
      NEW.organization_id, om.user_id,
      'onboarding_approved',
      'Client activated',
      v_recipient_name || ' has been approved and activated.',
      'onboarding', NEW.id
    FROM public.organization_users om
    WHERE om.organization_id = NEW.organization_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: notify_onboarding_for_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_onboarding_for_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member RECORD;
  v_label TEXT;
BEGIN
  IF NEW.status = 'for_review' AND (OLD.status IS DISTINCT FROM 'for_review') THEN
    v_label := COALESCE(
      NEW.company_name,
      NULLIF(TRIM(COALESCE(NEW.first_name,'') || ' ' || COALESCE(NEW.last_name,'')), ''),
      NEW.email,
      'New onboarding'
    );

    FOR v_member IN
      SELECT user_id FROM public.organization_users
      WHERE organization_id = NEW.organization_id
    LOOP
      INSERT INTO public.notifications (
        organization_id, user_id, type, title, message, entity_type, entity_id, payload
      ) VALUES (
        NEW.organization_id,
        v_member.user_id,
        'onboarding_for_review',
        'Onboarding ready for review',
        v_label || ' has completed onboarding and is ready for your review.',
        'onboarding_application',
        NEW.id,
        jsonb_build_object('application_id', NEW.id, 'recipient', v_label)
      );
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: on_cgt_disposal_date_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.on_cgt_disposal_date_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_client_id uuid;
  v_deadline_date date;
BEGIN
  IF NEW.disposal_date IS NOT NULL AND (OLD.disposal_date IS NULL OR OLD.disposal_date != NEW.disposal_date) THEN
    v_deadline_date := NEW.disposal_date::date + INTERVAL '60 days';
    
    SELECT c.organization_id, c.id INTO v_org_id, v_client_id
    FROM public.clients c
    WHERE c.id = NEW.client_id;
    
    IF v_org_id IS NOT NULL THEN
      INSERT INTO public.deadlines (
        organization_id, client_id, service_code, deadline_type,
        due_date, title, status, created_at
      ) VALUES (
        v_org_id, v_client_id, 'CGT', 'filing',
        v_deadline_date, 'CGT Return - 60 Day Deadline',
        CASE WHEN v_deadline_date < CURRENT_DATE THEN 'overdue' ELSE 'upcoming' END,
        now()
      )
      ON CONFLICT (organization_id, client_id, service_code, deadline_type)
      DO UPDATE SET
        due_date = EXCLUDED.due_date,
        title = EXCLUDED.title,
        status = CASE WHEN EXCLUDED.due_date < CURRENT_DATE THEN 'overdue' ELSE 'upcoming' END,
        updated_at = now();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: override_bill_lock_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_bill_lock_safe(p_bill_id uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_bill RECORD;
  v_org_id UUID;
  v_override_entry JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  v_org_id := v_bill.organization_id;
  IF NOT can_override_locked_records(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: admin+ required');
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Override reason must be at least 10 characters');
  END IF;

  v_override_entry := jsonb_build_object(
    'at', now(),
    'by', v_user_id,
    'reason', p_reason,
    'changes', p_changes,
    'before', to_jsonb(v_bill)
  );

  UPDATE bills SET
    supplier_id = COALESCE((p_changes->>'supplier_id')::UUID, supplier_id),
    issue_date = COALESCE((p_changes->>'issue_date')::DATE, issue_date),
    due_date = COALESCE((p_changes->>'due_date')::DATE, due_date),
    total_net = COALESCE((p_changes->>'total_net')::NUMERIC, total_net),
    total_vat = COALESCE((p_changes->>'total_vat')::NUMERIC, total_vat),
    total_gross = COALESCE((p_changes->>'total_gross')::NUMERIC, total_gross),
    notes = COALESCE(p_changes->>'notes', notes),
    override_history = COALESCE(override_history, '[]'::jsonb) || v_override_entry,
    updated_at = now()
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata, actor_role)
  VALUES (v_org_id, 'bill', p_bill_id, 'lock_overridden', v_user_id,
    jsonb_build_object('reason', p_reason, 'changes', p_changes),
    (SELECT role FROM organization_users WHERE user_id = v_user_id AND organization_id = v_org_id LIMIT 1));

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;


--
-- Name: override_invoice_lock_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_invoice_lock_safe(p_invoice_id uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_before_state JSONB;
  v_override_entry JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF p_reason IS NULL OR p_reason = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reason is required for lock override');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  
  IF v_invoice.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  
  v_org_id := v_invoice.organization_id;
  
  -- Check permission - admin/owner only
  IF NOT can_override_invoice_lock(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: only admin/owner can override locks');
  END IF;
  
  v_before_state := to_jsonb(v_invoice);
  
  -- Build override history entry
  v_override_entry := jsonb_build_object(
    'timestamp', now(),
    'user_id', v_user_id,
    'reason', p_reason,
    'changes', p_changes,
    'before_values', jsonb_build_object()
  );
  
  -- Apply changes (this is intentionally permissive for admin override)
  UPDATE invoices SET
    customer_id = COALESCE((p_changes->>'customer_id')::UUID, customer_id),
    contact_name = COALESCE(p_changes->>'contact_name', contact_name),
    contact_email = COALESCE(p_changes->>'contact_email', contact_email),
    issue_date = COALESCE((p_changes->>'issue_date')::DATE, issue_date),
    due_date = COALESCE((p_changes->>'due_date')::DATE, due_date),
    notes = COALESCE(p_changes->>'notes', notes),
    override_history = COALESCE(override_history, '[]'::JSONB) || v_override_entry,
    updated_at = now()
  WHERE id = p_invoice_id;
  
  -- Write detailed audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice',
    p_invoice_id,
    'override_lock',
    NULL,
    NULL,
    NULL,
    v_before_state,
    (SELECT to_jsonb(i) FROM invoices i WHERE i.id = p_invoice_id),
    jsonb_build_object('changes', p_changes, 'reason', p_reason, 'override_type', 'admin_override')
  );
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: pause_automation(uuid, text, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pause_automation(p_org_id uuid, p_scope text, p_target_id uuid, p_rule_id uuid, p_reason text, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT user_in_organization(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'not a member of organization';
  END IF;
  INSERT INTO automation_pauses(organization_id, scope, target_id, rule_id, reason, paused_by, expires_at)
  VALUES (p_org_id, p_scope, p_target_id, p_rule_id, p_reason, auth.uid(), p_expires_at)
  RETURNING id INTO v_id;
  INSERT INTO automation_audit_logs(organization_id, actor_id, entity_type, entity_id, action, after_state)
  VALUES (p_org_id, auth.uid(), 'automation_pause', v_id, 'pause',
          jsonb_build_object('scope',p_scope,'target_id',p_target_id,'rule_id',p_rule_id,'reason',p_reason));
  RETURN v_id;
END;$$;


--
-- Name: pause_workflow_instance(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pause_workflow_instance(p_instance_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.automation_workflow_instances
     SET status = 'PAUSED', paused_at = now(), last_error = COALESCE(p_reason, last_error), updated_at = now()
   WHERE id = p_instance_id
     AND org_id IN (SELECT organization_id FROM organization_users WHERE user_id = auth.uid());
END;
$$;


--
-- Name: port_quote_to_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.port_quote_to_client(p_quote_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote record;
  v_lead record;
  v_client_id uuid;
  v_org_id uuid;
BEGIN
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
  IF v_quote.ported_to_client_id IS NOT NULL THEN RETURN v_quote.ported_to_client_id; END IF;
  v_org_id := v_quote.organization_id;
  IF NOT user_has_organization_access(v_org_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;

  v_client_id := v_quote.client_id;
  IF v_client_id IS NULL THEN
    IF v_quote.lead_id IS NULL THEN RAISE EXCEPTION 'Quote has no client or lead to port from'; END IF;
    SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Lead not found'; END IF;

    SELECT id INTO v_client_id FROM public.clients
      WHERE organization_id = v_org_id AND lower(email) = lower(v_lead.email)
      LIMIT 1;

    IF v_client_id IS NULL THEN
      INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status)
      VALUES (v_org_id, v_lead.first_name, v_lead.last_name, v_lead.email, v_lead.phone,
              coalesce(v_lead.lead_type,'other'), 'pending')
      RETURNING id INTO v_client_id;
    END IF;
  END IF;

  UPDATE public.quotes SET ported_to_client_id = v_client_id, ported_at = now(), client_id = v_client_id WHERE id = p_quote_id;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, new_value, metadata)
  VALUES (v_org_id, 'CLIENT_ONBOARDING_STARTED', 'client', v_client_id,
          jsonb_build_object('quote_id', p_quote_id),
          jsonb_build_object('source','port_quote_to_client'));

  RETURN v_client_id;
END;
$$;


--
-- Name: portal_approve_vat_return(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_approve_vat_return(_vat_return_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ret public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'vat_return_not_found'; END IF;

  IF NOT public.portal_has_perm(v_ret.client_id, v_ret.company_id, 'allow_vat_approval') THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  IF NOT COALESCE(v_ret.client_approval_required, false) THEN
    RAISE EXCEPTION 'approval_not_requested';
  END IF;

  IF v_ret.client_approved_at IS NOT NULL THEN
    RAISE EXCEPTION 'already_approved';
  END IF;

  UPDATE public.vat_returns
     SET client_approved_at = now(),
         client_approved_by = v_uid,
         updated_at         = now()
   WHERE id = _vat_return_id;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, after_state, metadata)
  VALUES (
    v_ret.organization_id,
    CASE WHEN v_ret.client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(v_ret.client_id, v_ret.company_id),
    'portal.vat_return.approved',
    v_uid,
    'portal_client',
    jsonb_build_object('vat_return_id', _vat_return_id),
    jsonb_build_object('source','portal')
  );

  RETURN _vat_return_id;
END
$$;


--
-- Name: portal_can_access_bookkeeping(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_can_access_bookkeeping(_client_id uuid, _company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.portal_user_has_entity_access(auth.uid(), _client_id, _company_id)
    AND public.entity_has_active_bookkeeping(_client_id, _company_id);
$$;


--
-- Name: portal_categorise_transaction(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_categorise_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client  uuid;
  v_company uuid;
  v_result  jsonb;
BEGIN
  SELECT client_id, company_id INTO v_client, v_company
  FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction not found';
  END IF;

  IF NOT public.portal_has_perm(v_client, v_company, 'allow_client_post_to_ledger') THEN
    RAISE EXCEPTION 'Not permitted to categorise transactions' USING ERRCODE = '42501';
  END IF;

  v_result := public.post_bank_transaction(
    p_bank_transaction_id, p_contra_account_id, p_vat_code_id, p_vat_amount, p_description);

  IF COALESCE((v_result->>'success')::boolean, false) THEN
    UPDATE public.bank_transactions
       SET client_explained_by     = auth.uid(),
           client_explained_status = 'client_posted'
     WHERE id = p_bank_transaction_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: portal_explain_transaction(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_explain_transaction(_transaction_id uuid, _explanation text, _suggested_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn public.bank_transactions%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = _transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found'; END IF;

  IF NOT public.portal_has_perm(v_txn.client_id, v_txn.company_id, 'allow_transaction_explain') THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  UPDATE public.bank_transactions
     SET client_explanation          = _explanation,
         client_suggested_account_id = _suggested_account_id,
         client_explained_status     = 'client_explained',
         client_explained_at         = now(),
         client_explained_by         = v_uid,
         updated_at                  = now()
   WHERE id = _transaction_id;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, after_state, metadata)
  VALUES (
    v_txn.organization_id,
    CASE WHEN v_txn.client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(v_txn.client_id, v_txn.company_id),
    'portal.transaction.explained',
    v_uid,
    'portal_client',
    jsonb_build_object(
      'transaction_id', _transaction_id,
      'explanation', _explanation,
      'suggested_account_id', _suggested_account_id
    ),
    jsonb_build_object('source','portal')
  );

  RETURN _transaction_id;
END
$$;


--
-- Name: portal_has_bookkeeping(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_has_bookkeeping(_entity_type text, _entity_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.portal_user_has_entity_access(auth.uid(),
      CASE WHEN _entity_type = 'client' THEN _entity_id END,
      CASE WHEN _entity_type = 'company' THEN _entity_id END)
    AND public.entity_has_active_bookkeeping(
      CASE WHEN _entity_type = 'client' THEN _entity_id END,
      CASE WHEN _entity_type = 'company' THEN _entity_id END);
$$;


--
-- Name: portal_has_perm(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_has_perm(_client_id uuid, _company_id uuid, _permission text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v boolean; v_master boolean; v_settings_col text;
BEGIN
  -- Hard accountant-only — never granted to portal regardless of settings
  IF _permission IN (
    'vat.submit','filings.submit','periods.close','lock_dates.manage',
    'journals.create','workpapers.finalise','org.settings'
  ) THEN
    RETURN false;
  END IF;

  -- Known permissions (legacy + new)
  IF _permission NOT IN (
    'allow_bank_connect','allow_transaction_explain','allow_receipt_upload',
    'allow_invoice_create','allow_invoice_send','show_bills','allow_bill_create',
    'show_vat_returns','allow_vat_approval',
    'show_reports_summary','show_reports_detail','allow_reports_download',
    'show_bank_accounts','show_transactions','show_invoices','show_trial_balance',
    'show_detailed_ledger','full_bookkeeping',
    'allow_customer_create','allow_supplier_create','allow_receipt_match','allow_query_respond',
    'allow_client_reconcile','allow_client_post_to_ledger'
  ) THEN RETURN false; END IF;

  IF NOT public.portal_can_access_bookkeeping(_client_id, _company_id) THEN RETURN false; END IF;

  IF _client_id IS NOT NULL THEN
    SELECT COALESCE(full_bookkeeping_access, false) INTO v_master
      FROM public.portal_visibility_settings WHERE client_id = _client_id LIMIT 1;
  ELSIF _company_id IS NOT NULL THEN
    SELECT COALESCE(full_bookkeeping_access, false) INTO v_master
      FROM public.portal_visibility_settings WHERE company_id = _company_id LIMIT 1;
  END IF;

  IF COALESCE(v_master, false) THEN RETURN true; END IF;
  IF _permission = 'full_bookkeeping' THEN RETURN false; END IF;

  IF _client_id IS NOT NULL THEN
    EXECUTE format('SELECT COALESCE(%I, false) FROM public.portal_visibility_settings WHERE client_id = $1 LIMIT 1', _permission)
      INTO v USING _client_id;
  ELSIF _company_id IS NOT NULL THEN
    EXECUTE format('SELECT COALESCE(%I, false) FROM public.portal_visibility_settings WHERE company_id = $1 LIMIT 1', _permission)
      INTO v USING _company_id;
  ELSE RETURN false; END IF;

  RETURN COALESCE(v, false);
END $_$;


--
-- Name: portal_list_ledger_accounts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_ledger_accounts(p_client_id uuid, p_company_id uuid) RETURNS TABLE(id uuid, code text, name text, account_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF NOT public.portal_can_access_bookkeeping(p_client_id, p_company_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;

  RETURN QUERY
    SELECT a.id, a.code, a.name, a.account_type
    FROM public.bookkeeping_accounts a
    WHERE a.organization_id = v_org
      AND COALESCE(a.is_active, true) = true
      AND COALESCE(a.is_bank_account, false) = false
    ORDER BY a.account_type, a.code;
END;
$$;


--
-- Name: portal_send_message(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_send_message(p_client_id uuid, p_company_id uuid, p_body text, p_subject text DEFAULT NULL::text, p_parent_message_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_id  uuid;
BEGIN
  IF p_body IS NULL OR length(btrim(p_body)) = 0 THEN
    RAISE EXCEPTION 'Message body is required';
  END IF;

  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Provide exactly one of client or company';
  END IF;

  IF NOT public.client_has_portal_access(auth.uid(), p_client_id, p_company_id) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Entity not found';
  END IF;

  INSERT INTO public.client_messages (
    organization_id, client_id, company_id, sender_id, sender_type,
    message_type, visibility, content, subject, parent_message_id
  ) VALUES (
    v_org, p_client_id, p_company_id, auth.uid(), 'client',
    'message', 'client_visible', btrim(p_body), p_subject, p_parent_message_id
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: portal_user_has_entity_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_user_has_entity_access(_user_id uuid, _client_id uuid, _company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.portal_access pa
    WHERE pa.user_id = _user_id AND pa.is_active = true
      AND ((_client_id IS NOT NULL AND pa.client_id = _client_id)
        OR (_company_id IS NOT NULL AND pa.company_id = _company_id))
  );
$$;


--
-- Name: post_bank_transaction(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_bank_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_bank record;
  v_bank_account_ledger_id uuid;
  v_vat_account_id uuid;
  v_org_settings record;
  v_amount numeric;
  v_gross numeric;
  v_net numeric;
  v_vat numeric;
  v_entries jsonb;
  v_result jsonb;
  v_journal_id uuid;
  v_actor uuid := auth.uid();
  v_is_receive boolean;
BEGIN
  -- Load transaction
  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_matched',
                              'error_message', 'Transaction is already matched');
  END IF;

  -- Load bank account and its ledger account
  SELECT * INTO v_bank FROM bank_accounts WHERE id = v_txn.bank_account_id;
  IF NOT FOUND OR v_bank.account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_unmapped',
                              'error_message', 'Bank account is not mapped to a ledger account');
  END IF;
  v_bank_account_ledger_id := v_bank.account_id;

  -- VAT split
  v_gross := abs(v_txn.amount);
  v_vat   := COALESCE(p_vat_amount, 0);
  IF v_vat < 0 OR v_vat > v_gross THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_vat_amount',
                              'error_message', 'VAT amount must be between zero and the gross amount');
  END IF;
  v_net := v_gross - v_vat;
  v_is_receive := v_txn.amount > 0;

  -- VAT control account (from org_settings)
  IF v_vat > 0 THEN
    SELECT * INTO v_org_settings FROM org_settings
      WHERE organization_id = v_txn.organization_id LIMIT 1;
    v_vat_account_id := v_org_settings.vat_control_account_id;
    IF v_vat_account_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'vat_control_not_set',
                                'error_message', 'VAT control account is not configured for this organisation');
    END IF;
  END IF;

  -- Build entries:
  --   RECEIVE: Dr Bank (gross), Cr Contra (net) [, Cr VAT (vat)]
  --   SPEND:   Dr Contra (net) [, Dr VAT (vat)], Cr Bank (gross)
  IF v_is_receive THEN
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_bank_account_ledger_id, 'debit', v_gross,
                         'description', COALESCE(p_description, v_txn.description)),
      jsonb_build_object('account_id', p_contra_account_id, 'credit', v_net,
                         'vat_code_id', p_vat_code_id,
                         'description', COALESCE(p_description, v_txn.description))
    );
    IF v_vat > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_vat_account_id, 'credit', v_vat,
                           'vat_code_id', p_vat_code_id,
                           'description', 'VAT on ' || COALESCE(p_description, v_txn.description))
      );
    END IF;
  ELSE
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', p_contra_account_id, 'debit', v_net,
                         'vat_code_id', p_vat_code_id,
                         'description', COALESCE(p_description, v_txn.description))
    );
    IF v_vat > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_vat_account_id, 'debit', v_vat,
                           'vat_code_id', p_vat_code_id,
                           'description', 'VAT on ' || COALESCE(p_description, v_txn.description))
      );
    END IF;
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_bank_account_ledger_id, 'credit', v_gross,
                         'description', COALESCE(p_description, v_txn.description))
    );
  END IF;

  v_result := post_to_ledger(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id,
    v_txn.transaction_date,
    COALESCE(NULLIF(v_txn.description, ''), 'Bank transaction'),
    COALESCE(p_description, v_txn.description, 'Bank transaction'),
    CASE WHEN v_is_receive THEN 'BANK_RECEIVE' ELSE 'BANK_SPEND' END,
    'BANK_TRANSACTION', p_bank_transaction_id,
    COALESCE(v_txn.currency, 'GBP'), 1.0, v_actor, v_entries
  );

  IF NOT COALESCE((v_result->>'success')::boolean, false) THEN
    RETURN v_result;
  END IF;

  v_journal_id := (v_result->>'journal_id')::uuid;

  UPDATE bank_transactions
     SET status = 'MATCHED',
         matched_ledger_entry_id = (
           SELECT id FROM ledger_entries
            WHERE journal_id = v_journal_id AND account_id = v_bank_account_ledger_id
            LIMIT 1
         ),
         updated_at = now()
   WHERE id = p_bank_transaction_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: post_bank_transfer(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_bank_transfer(p_source_transaction_id uuid, p_destination_bank_account_id uuid, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_src record;
  v_dst record;
  v_entries jsonb;
  v_result jsonb;
  v_actor uuid := auth.uid();
  v_amount numeric;
BEGIN
  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_source_transaction_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;
  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_matched',
                              'error_message', 'Transaction is already matched');
  END IF;

  SELECT * INTO v_src FROM bank_accounts WHERE id = v_txn.bank_account_id;
  SELECT * INTO v_dst FROM bank_accounts WHERE id = p_destination_bank_account_id;
  IF v_src IS NULL OR v_dst IS NULL OR v_src.account_id IS NULL OR v_dst.account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_unmapped',
                              'error_message', 'Source or destination bank account is unmapped');
  END IF;
  IF v_src.organization_id <> v_dst.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'cross_org_transfer',
                              'error_message', 'Transfers across organisations are not permitted');
  END IF;

  v_amount := abs(v_txn.amount);

  -- If source amount is negative (money out), src is source; otherwise reverse.
  IF v_txn.amount < 0 THEN
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_dst.account_id, 'debit',  v_amount,
                         'description', COALESCE(p_description, 'Transfer to ' || v_dst.name)),
      jsonb_build_object('account_id', v_src.account_id, 'credit', v_amount,
                         'description', COALESCE(p_description, 'Transfer from ' || v_src.name))
    );
  ELSE
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_src.account_id, 'debit',  v_amount,
                         'description', COALESCE(p_description, 'Transfer into ' || v_src.name)),
      jsonb_build_object('account_id', v_dst.account_id, 'credit', v_amount,
                         'description', COALESCE(p_description, 'Transfer out of ' || v_dst.name))
    );
  END IF;

  v_result := post_to_ledger(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id,
    v_txn.transaction_date,
    'Bank transfer',
    COALESCE(p_description, 'Bank transfer'),
    'BANK_TRANSFER',
    'BANK_TRANSACTION', p_source_transaction_id,
    COALESCE(v_txn.currency, 'GBP'), 1.0, v_actor, v_entries
  );

  IF NOT COALESCE((v_result->>'success')::boolean, false) THEN
    RETURN v_result;
  END IF;

  UPDATE bank_transactions
     SET status = 'MATCHED', updated_at = now()
   WHERE id = p_source_transaction_id;

  RETURN v_result;
END;
$$;


--
-- Name: post_monthly_depreciation(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_monthly_depreciation(p_asset_id uuid, p_period_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_asset public.fixed_assets%ROWTYPE;
  v_user uuid := auth.uid();
  v_period_start date := date_trunc('month', p_period_end)::date;
  v_period_end date := (date_trunc('month', p_period_end) + interval '1 month - 1 day')::date;
  v_reference text;
  v_existing uuid;
  v_dep_acct uuid;
  v_accum_acct uuid;
  v_asset_acct uuid;
  v_depreciable numeric;
  v_charge numeric := 0;
  v_remaining numeric;
  v_entries jsonb;
  v_result jsonb;
BEGIN
  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Asset not found'; END IF;

  IF NOT public.has_role(v_user, 'owner') AND NOT public.has_role(v_user, 'admin') AND NOT public.has_role(v_user, 'staff') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organization_users WHERE user_id = v_user AND organization_id = v_asset.organization_id) THEN
    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  IF v_asset.status <> 'active' THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'asset_not_active');
  END IF;

  IF v_asset.depreciation_method = 'NONE' THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'no_depreciation');
  END IF;

  IF v_asset.depreciation_start_date IS NULL OR v_period_end < v_asset.depreciation_start_date THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'before_start_date');
  END IF;

  v_reference := 'DEPN-' || p_asset_id::text || '-' || to_char(v_period_end, 'YYYYMM');
  SELECT id INTO v_existing FROM public.journals
    WHERE organization_id = v_asset.organization_id AND source_type = 'DEPRECIATION' AND reference = v_reference;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'already_posted', 'journal_id', v_existing);
  END IF;

  v_dep_acct := COALESCE(v_asset.depreciation_expense_account_id,
    (SELECT depreciation_expense_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_accum_acct := COALESCE(v_asset.accumulated_depreciation_account_id,
    (SELECT accumulated_depreciation_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_asset_acct := v_asset.fixed_asset_account_id;

  IF v_dep_acct IS NULL OR v_accum_acct IS NULL THEN
    RAISE EXCEPTION 'Depreciation expense or accumulated depreciation account not configured';
  END IF;

  v_depreciable := GREATEST(v_asset.cost - COALESCE(v_asset.residual_value,0), 0);
  v_remaining := GREATEST(v_depreciable - COALESCE(v_asset.accumulated_depreciation,0), 0);

  IF v_asset.depreciation_method = 'SL' THEN
    IF v_asset.useful_life_months IS NULL OR v_asset.useful_life_months <= 0 THEN
      RAISE EXCEPTION 'Useful life (months) required for straight-line';
    END IF;
    v_charge := round(v_depreciable / v_asset.useful_life_months, 2);
  ELSIF v_asset.depreciation_method = 'RB' THEN
    IF v_asset.depreciation_rate_pct IS NULL OR v_asset.depreciation_rate_pct <= 0 THEN
      RAISE EXCEPTION 'Depreciation rate required for reducing balance';
    END IF;
    v_charge := round((v_asset.cost - COALESCE(v_asset.accumulated_depreciation,0)) * (v_asset.depreciation_rate_pct/100.0) / 12.0, 2);
  END IF;

  v_charge := LEAST(v_charge, v_remaining);

  IF v_charge <= 0 THEN
    UPDATE public.fixed_assets SET status='fully_depreciated', updated_at=now() WHERE id=p_asset_id;
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'fully_depreciated');
  END IF;

  v_entries := jsonb_build_array(
    jsonb_build_object('account_id', v_dep_acct, 'debit', v_charge, 'credit', 0,
                       'description', 'Depreciation: ' || v_asset.asset_name),
    jsonb_build_object('account_id', v_accum_acct, 'debit', 0, 'credit', v_charge,
                       'description', 'Accumulated depreciation: ' || v_asset.asset_name)
  );

  v_result := public.post_to_ledger(
    p_organization_id := v_asset.organization_id,
    p_client_id       := NULL,
    p_company_id      := v_asset.company_id,
    p_journal_date    := v_period_end,
    p_reference       := v_reference,
    p_description     := 'Monthly depreciation - ' || v_asset.asset_name,
    p_journal_type    := 'DEPRECIATION',
    p_source_type     := 'DEPRECIATION',
    p_source_id       := p_asset_id,
    p_currency        := 'GBP',
    p_fx_rate         := 1.0,
    p_created_by      := v_user,
    p_entries         := v_entries,
    p_lock_override_reason := NULL,
    p_idempotency_key := v_reference
  );

  IF (v_result->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'post_to_ledger failed: %', v_result->>'error';
  END IF;

  UPDATE public.fixed_assets
     SET accumulated_depreciation = COALESCE(accumulated_depreciation,0) + v_charge,
         last_depreciation_date = v_period_end,
         status = CASE WHEN COALESCE(accumulated_depreciation,0) + v_charge >= v_depreciable
                       THEN 'fully_depreciated' ELSE status END,
         updated_at = now()
   WHERE id = p_asset_id;

  INSERT INTO public.bookkeeping_audit_log(organization_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (v_asset.organization_id, 'fixed_asset', p_asset_id, 'post_depreciation', v_user,
          jsonb_build_object('period_end', v_period_end, 'charge', v_charge, 'journal_id', v_result->>'journal_id'));

  RETURN jsonb_build_object('success', true, 'charge', v_charge, 'journal_id', v_result->>'journal_id', 'period_end', v_period_end);
END; $$;


--
-- Name: post_to_ledger(uuid, uuid, uuid, date, text, text, text, text, uuid, text, numeric, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_to_ledger(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_journal_date date, p_reference text, p_description text, p_journal_type text, p_source_type text, p_source_id uuid, p_currency text DEFAULT 'GBP'::text, p_fx_rate numeric DEFAULT 1.0, p_created_by uuid DEFAULT NULL::uuid, p_entries jsonb DEFAULT '[]'::jsonb, p_lock_override_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_journal_id uuid;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
  v_entry jsonb;
  v_line_number int := 0;
  v_ledger_ids uuid[] := '{}';
  v_ledger_id uuid;
  v_lock_date date;
  v_actor uuid := COALESCE(p_created_by, auth.uid());
  v_is_admin boolean;
  v_account_record record;
  v_dup_count int;
  v_err_code text;
  v_err_msg text;
  v_entity_type text;
  v_entity_id uuid;
  v_debit numeric;
  v_credit numeric;
  v_account_id uuid;
  v_allow_duplicate_sources text[] :=
    ARRAY['JOURNAL','REVERSAL','PAYMENT','CREDIT_NOTE','VAT_ADJUSTMENT','OPENING_BALANCE_REVERSAL'];
BEGIN
  -- ---- Header validations ---------------------------------------------------
  IF p_organization_id IS NULL THEN
    v_err_code := 'missing_organization'; v_err_msg := 'organization_id is required';
    PERFORM 1; RAISE EXCEPTION '%', v_err_msg;
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL)
     OR (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    v_err_code := 'invalid_entity_scope';
    v_err_msg  := 'Exactly one of client_id or company_id must be provided';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  v_entity_type := CASE WHEN p_client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(p_client_id, p_company_id);

  -- caller must belong to organization (defense in depth; RPC is SECURITY DEFINER)
  IF v_actor IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM organization_users
       WHERE organization_id = p_organization_id AND user_id = v_actor
     ) THEN
    v_err_code := 'cross_tenant';
    v_err_msg  := 'Caller is not a member of the target organization';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  IF jsonb_array_length(COALESCE(p_entries, '[]'::jsonb)) < 2 THEN
    v_err_code := 'insufficient_lines';
    v_err_msg  := 'At least two ledger lines are required';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  -- ---- Line validations + totals -------------------------------------------
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_entries) LOOP
    v_account_id := (v_entry->>'account_id')::uuid;
    v_debit  := COALESCE((v_entry->>'debit')::numeric,  0);
    v_credit := COALESCE((v_entry->>'credit')::numeric, 0);

    IF v_account_id IS NULL THEN
      v_err_code := 'missing_account';
      v_err_msg  := 'Every line requires account_id';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF v_debit < 0 OR v_credit < 0 THEN
      v_err_code := 'negative_amount';
      v_err_msg  := 'Negative debit or credit values are not permitted';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF (v_debit > 0 AND v_credit > 0) OR (v_debit = 0 AND v_credit = 0) THEN
      v_err_code := 'invalid_line';
      v_err_msg  := 'Each line must have exactly one of debit or credit set';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    SELECT id, organization_id, client_id, company_id, is_active, is_system_account
      INTO v_account_record
      FROM bookkeeping_accounts
     WHERE id = v_account_id;

    IF NOT FOUND THEN
      v_err_code := 'account_not_found';
      v_err_msg  := format('Account %s does not exist', v_account_id);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF v_account_record.organization_id <> p_organization_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account belongs to a different organization';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    -- system accounts (org-scoped templates) may have null entity; entity-specific must match
    IF v_account_record.client_id IS NOT NULL
       AND v_account_record.client_id IS DISTINCT FROM p_client_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account is scoped to a different client';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;
    IF v_account_record.company_id IS NOT NULL
       AND v_account_record.company_id IS DISTINCT FROM p_company_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account is scoped to a different company';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF COALESCE(v_account_record.is_active, true) = false THEN
      v_err_code := 'account_inactive';
      v_err_msg  := 'Posting to an inactive account is not permitted';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    v_total_debit  := v_total_debit  + v_debit;
    v_total_credit := v_total_credit + v_credit;
  END LOOP;

  IF round(v_total_debit, 2) <> round(v_total_credit, 2) THEN
    v_err_code := 'unbalanced';
    v_err_msg  := format('Journal is unbalanced: debits %s != credits %s',
                         v_total_debit, v_total_credit);
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  -- ---- Period lock enforcement ---------------------------------------------
  SELECT MAX(lock_date) INTO v_lock_date
    FROM period_locks
   WHERE organization_id = p_organization_id
     AND ((p_client_id  IS NOT NULL AND client_id  = p_client_id)
       OR (p_company_id IS NOT NULL AND company_id = p_company_id));

  IF v_lock_date IS NOT NULL AND p_journal_date <= v_lock_date THEN
    IF p_lock_override_reason IS NULL
       OR length(btrim(p_lock_override_reason)) = 0 THEN
      v_err_code := 'period_locked';
      v_err_msg  := format('Period is locked through %s; override reason required', v_lock_date);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    SELECT (has_organization_role(p_organization_id, 'owner')
         OR has_organization_role(p_organization_id, 'admin'))
      INTO v_is_admin;

    IF NOT COALESCE(v_is_admin, false) THEN
      v_err_code := 'period_locked_no_role';
      v_err_msg  := 'Only owners/admins may override a locked period';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    INSERT INTO bookkeeping_audit_log
      (organization_id, entity_type, entity_id, action, actor_id, reason, metadata)
    VALUES (p_organization_id, v_entity_type, v_entity_id, 'period_lock_override',
            v_actor, p_lock_override_reason,
            jsonb_build_object('journal_date', p_journal_date, 'lock_date', v_lock_date,
                               'source_type', p_source_type, 'source_id', p_source_id));
  END IF;

  -- ---- Duplicate-source guard ----------------------------------------------
  IF p_source_id IS NOT NULL
     AND NOT (upper(COALESCE(p_source_type,'')) = ANY (v_allow_duplicate_sources)) THEN
    SELECT count(*) INTO v_dup_count
      FROM journals
     WHERE organization_id = p_organization_id
       AND ((p_client_id IS NOT NULL AND client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND company_id = p_company_id))
       AND id IN (
         SELECT journal_id FROM ledger_entries
          WHERE source_type = p_source_type AND source_id = p_source_id
       );

    IF v_dup_count > 0 THEN
      v_err_code := 'duplicate_source';
      v_err_msg  := format('Source %s/%s already posted', p_source_type, p_source_id);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;
  END IF;

  -- ---- Persist journal + lines + ledger entries ----------------------------
  INSERT INTO journals
    (organization_id, client_id, company_id, journal_date, reference, description,
     journal_type, total_debit, total_credit, transaction_currency, fx_rate_to_base,
     is_posted, posted_at, created_by)
  VALUES
    (p_organization_id, p_client_id, p_company_id, p_journal_date, p_reference, p_description,
     p_journal_type, v_total_debit, v_total_credit, p_currency, p_fx_rate,
     true, now(), v_actor)
  RETURNING id INTO v_journal_id;

  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_entries) LOOP
    v_line_number := v_line_number + 1;
    v_debit  := NULLIF(COALESCE((v_entry->>'debit')::numeric,  0), 0);
    v_credit := NULLIF(COALESCE((v_entry->>'credit')::numeric, 0), 0);

    INSERT INTO journal_lines
      (journal_id, line_number, account_id, debit, credit, vat_code_id, description)
    VALUES
      (v_journal_id, v_line_number, (v_entry->>'account_id')::uuid,
       v_debit, v_credit, (v_entry->>'vat_code_id')::uuid, v_entry->>'description');

    INSERT INTO ledger_entries
      (organization_id, client_id, company_id, transaction_date, entry_date,
       account_id, debit, credit, description, reference, journal_id,
       source_type, source_id, vat_code_id, transaction_currency,
       transaction_debit, transaction_credit, fx_rate_to_base, base_currency, created_by)
    VALUES
      (p_organization_id, p_client_id, p_company_id, p_journal_date, p_journal_date,
       (v_entry->>'account_id')::uuid,
       CASE WHEN v_debit  IS NULL THEN NULL ELSE v_debit  * p_fx_rate END,
       CASE WHEN v_credit IS NULL THEN NULL ELSE v_credit * p_fx_rate END,
       v_entry->>'description', p_reference, v_journal_id,
       p_source_type, p_source_id, (v_entry->>'vat_code_id')::uuid, p_currency,
       v_debit, v_credit, p_fx_rate, 'GBP', v_actor)
    RETURNING id INTO v_ledger_id;
    v_ledger_ids := v_ledger_ids || v_ledger_id;
  END LOOP;

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, after_state, metadata)
  VALUES
    (p_organization_id, v_entity_type, v_entity_id, 'ledger_post', v_actor,
     jsonb_build_object('journal_id', v_journal_id, 'total_debit', v_total_debit,
                        'total_credit', v_total_credit, 'line_count', v_line_number),
     jsonb_build_object('source_type', p_source_type, 'source_id', p_source_id,
                        'journal_type', p_journal_type, 'idempotency_key', p_idempotency_key));

  RETURN jsonb_build_object('success', true,
                            'journal_id', v_journal_id,
                            'ledger_entry_ids', to_jsonb(v_ledger_ids));

EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO bookkeeping_audit_log
      (organization_id, entity_type, entity_id, action, actor_id, reason, metadata)
    VALUES
      (COALESCE(p_organization_id, '00000000-0000-0000-0000-000000000000'::uuid),
       COALESCE(v_entity_type, 'unknown'),
       COALESCE(v_entity_id, '00000000-0000-0000-0000-000000000000'::uuid),
       'ledger_post_blocked', v_actor,
       COALESCE(v_err_msg, SQLERRM),
       jsonb_build_object('error_code', COALESCE(v_err_code, 'unknown'),
                          'source_type', p_source_type,
                          'source_id',   p_source_id,
                          'journal_date', p_journal_date));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN jsonb_build_object('success', false,
                            'error_code',    COALESCE(v_err_code, 'unknown'),
                            'error_message', COALESCE(v_err_msg, SQLERRM));
END;
$$;


--
-- Name: prevent_accepted_quote_line_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_accepted_quote_line_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_quote_id uuid;
BEGIN
  v_quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  SELECT status INTO v_status FROM public.quotes WHERE id = v_quote_id;
  IF v_status = 'accepted' THEN
    RAISE EXCEPTION 'Cannot modify line items on an accepted quote (quote_id: %). Issue a new quote instead.', v_quote_id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: prevent_signed_document_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_signed_document_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.signed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot delete a signed document (id: %). Signed documents must be retained for compliance.', OLD.id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: prevent_snapshot_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_snapshot_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'filing_model_snapshots is immutable - modifications not allowed';
END;
$$;


--
-- Name: process_due_recurring_invoices(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_due_recurring_invoices(p_organization_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_result jsonb;
  v_processed int := 0;
  v_failed int := 0;
  v_details jsonb := '[]'::jsonb;
BEGIN
  FOR v_row IN
    SELECT id FROM recurring_invoice_schedules
     WHERE status = 'active'
       AND next_run_at IS NOT NULL
       AND next_run_at <= now()
       AND (p_organization_id IS NULL OR organization_id = p_organization_id)
     ORDER BY next_run_at ASC
     LIMIT p_limit
  LOOP
    v_result := public.generate_recurring_invoice(v_row.id, NULL);
    IF COALESCE((v_result->>'success')::boolean, false) THEN
      v_processed := v_processed + 1;
    ELSE
      v_failed := v_failed + 1;
    END IF;
    v_details := v_details || jsonb_build_array(jsonb_build_object('schedule_id', v_row.id, 'result', v_result));
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed', v_processed,
    'failed', v_failed,
    'details', v_details
  );
END $$;


--
-- Name: process_questionnaire_submission(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_questionnaire_submission(p_questionnaire_instance_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_instance questionnaire_instances%ROWTYPE;
  v_job_link job_questionnaire_instances%ROWTYPE;
  v_job jobs%ROWTYPE;
  v_workpaper workpaper_instances%ROWTYPE;
  v_response record;
  v_field_values jsonb;
  v_file record;
BEGIN
  -- Get questionnaire instance
  SELECT * INTO v_instance FROM questionnaire_instances WHERE id = p_questionnaire_instance_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Questionnaire instance not found');
  END IF;
  
  -- Get job link
  SELECT * INTO v_job_link FROM job_questionnaire_instances 
  WHERE questionnaire_instance_id = p_questionnaire_instance_id;
  
  IF FOUND AND v_job_link.feeds_workpaper THEN
    -- Get job
    SELECT * INTO v_job FROM jobs WHERE id = v_job_link.job_id;
    
    -- Get workpaper
    IF v_job.workpaper_instance_id IS NOT NULL THEN
      SELECT * INTO v_workpaper FROM workpaper_instances WHERE id = v_job.workpaper_instance_id;
      
      -- Merge questionnaire responses into workpaper field_values
      -- This is a simplified merge - the full implementation is in the TypeScript service
      v_field_values := COALESCE(v_workpaper.field_values, '{}'::jsonb);
      
      -- Mark as questionnaire source
      v_field_values := v_field_values || jsonb_build_object(
        '_questionnaire_merged', true,
        '_questionnaire_instance_id', p_questionnaire_instance_id,
        '_questionnaire_merged_at', now()
      );
      
      UPDATE workpaper_instances 
      SET field_values = v_field_values,
          updated_at = now()
      WHERE id = v_job.workpaper_instance_id;
    END IF;
    
    -- Update job status to info_received
    UPDATE jobs 
    SET status = 'in_progress',
        info_received_at = now(),
        updated_at = now()
    WHERE id = v_job_link.job_id;
    
    -- Log audit
    INSERT INTO audit_log (organization_id, entity_type, entity_id, action, metadata)
    VALUES (
      v_job.organization_id,
      'job',
      v_job_link.job_id,
      'questionnaire_submitted',
      jsonb_build_object('questionnaire_instance_id', p_questionnaire_instance_id)
    );
  END IF;
  
  -- Update questionnaire status
  UPDATE questionnaire_instances 
  SET status = 'submitted',
      submitted_at = now()
  WHERE id = p_questionnaire_instance_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'job_updated', v_job_link IS NOT NULL
  );
END;
$$;


--
-- Name: profiles_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: protect_engagement_letter_signatures(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_engagement_letter_signatures() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.signed_at IS NOT NULL AND (
       OLD.signed_at            IS DISTINCT FROM NEW.signed_at OR
       OLD.signature_ip         IS DISTINCT FROM NEW.signature_ip OR
       OLD.signature_user_agent IS DISTINCT FROM NEW.signature_user_agent OR
       OLD.signed_by            IS DISTINCT FROM NEW.signed_by OR
       OLD.signer_name          IS DISTINCT FROM NEW.signer_name OR
       OLD.signer_email         IS DISTINCT FROM NEW.signer_email OR
       OLD.document_content     IS DISTINCT FROM NEW.document_content
  ) THEN
    RAISE EXCEPTION 'Cannot modify signature fields on a signed engagement letter';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_signatory_signature(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_signatory_signature() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.signed_at IS NOT NULL AND (
       OLD.signed_at            IS DISTINCT FROM NEW.signed_at OR
       OLD.signer_name          IS DISTINCT FROM NEW.signer_name OR
       OLD.signer_email         IS DISTINCT FROM NEW.signer_email OR
       OLD.signature_ip         IS DISTINCT FROM NEW.signature_ip OR
       OLD.signature_user_agent IS DISTINCT FROM NEW.signature_user_agent
  ) THEN
    RAISE EXCEPTION 'Cannot modify signature fields on a signed signatory';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_system_vat_codes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_system_vat_codes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'System VAT code "%" cannot be deleted', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.is_system AND (
       NEW.code IS DISTINCT FROM OLD.code
       OR NEW.rate IS DISTINCT FROM OLD.rate
       OR NEW.vat_type IS DISTINCT FROM OLD.vat_type
       OR NEW.is_system IS DISTINCT FROM OLD.is_system
    ) THEN
      RAISE EXCEPTION 'System VAT code "%" core fields (code/rate/type/is_system) cannot be modified', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: public_accept_quote_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_accept_quote_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record;
  v_quote record;
  v_lead record;
  v_org uuid;
  v_canonical boolean;
  v_client_id uuid;
  v_company_id uuid;
  v_partnership_id uuid;
  v_has_individual boolean := false;
  v_has_company boolean := false;
  v_has_partnership boolean := false;
  v_has_cgt boolean := false;
  v_is_mtd boolean := false;
  v_company_name text;
  v_company record;
  v_today date := current_date;
  v_tax_year_start date;
  v_tax_year_end date;
  v_token_uuid uuid;
  v_director record;
  v_sa_first text;
  v_sa_last text;
  v_sa_email text;
  v_sa_phone text;
  v_sa_blocked boolean := false;
BEGIN
  BEGIN
    v_token_uuid := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error','invalid');
  END;

  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = v_token_uuid;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;

  IF v_quote.status = 'accepted' THEN
    UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid AND used_at IS NULL;
    RETURN jsonb_build_object('success', true, 'client_id', v_quote.ported_to_client_id, 'company_id', v_quote.ported_to_company_id, 'replay', true);
  END IF;

  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','not_open');
  END IF;

  v_org := v_quote.organization_id;
  v_canonical := public.is_canonical_lifecycle_enabled(v_org);

  SELECT
    bool_or(sc.entity_scope = 'individual') OR bool_or(sc.code IN ('sa_mtd','sa_non_mtd','cgt_60_day')),
    bool_or(sc.entity_scope = 'company'),
    bool_or(sc.entity_scope = 'partnership'),
    bool_or(sc.code = 'sa_mtd'),
    bool_or(sc.code = 'cgt_60_day')
  INTO v_has_individual, v_has_company, v_has_partnership, v_is_mtd, v_has_cgt
  FROM public.quote_lines ql
  JOIN public.services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  v_has_individual := COALESCE(v_has_individual, false);
  v_has_company := COALESCE(v_has_company, false);
  v_has_partnership := COALESCE(v_has_partnership, false);
  v_has_cgt := COALESCE(v_has_cgt, false);

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
  END IF;

  v_client_id := v_quote.client_id;
  v_company_id := v_quote.company_id;

  IF v_has_company AND v_company_id IS NULL AND v_lead.id IS NOT NULL THEN
    v_company_name := COALESCE(
      NULLIF(v_lead.ch_company_profile->>'company_name',''),
      NULLIF(v_lead.ch_company_profile->>'title',''),
      trim(coalesce(v_lead.first_name,'') || ' ' || coalesce(v_lead.last_name,''))
    );

    SELECT id INTO v_company_id FROM public.companies
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
      LIMIT 1;
    IF v_company_id IS NULL THEN
      INSERT INTO public.companies (organization_id, company_name, email, phone, company_number,
                                    ch_company_profile, status, notes)
      VALUES (v_org, v_company_name, v_lead.email, v_lead.phone,
              v_lead.ch_company_profile->>'company_number',
              v_lead.ch_company_profile, 'pending', v_lead.notes)
      RETURNING id INTO v_company_id;

      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (v_org, v_company_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  IF v_has_individual AND v_client_id IS NULL AND v_lead.id IS NOT NULL THEN
    IF v_has_company THEN
      SELECT * INTO v_director FROM public.resolve_company_director(v_company_id, v_quote.lead_id, v_org);
      IF v_director.first_name IS NOT NULL OR v_director.last_name IS NOT NULL THEN
        v_sa_first := v_director.first_name;
        v_sa_last  := v_director.last_name;
        v_sa_email := COALESCE(v_director.email, v_lead.email);
        v_sa_phone := COALESCE(v_director.phone, v_lead.phone);
      ELSE
        v_sa_blocked := true;
        INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
        VALUES (v_org, 'SA_DIRECTOR_DETAILS_REQUIRED', 'company', v_company_id,
                jsonb_build_object(
                  'quote_id', v_quote.id,
                  'lead_id', v_quote.lead_id,
                  'reason', 'no_director_on_file'
                ));
      END IF;
    ELSE
      v_sa_first := v_lead.first_name;
      v_sa_last  := v_lead.last_name;
      v_sa_email := v_lead.email;
      v_sa_phone := v_lead.phone;
    END IF;

    IF NOT v_sa_blocked THEN
      SELECT id INTO v_client_id FROM public.clients
        WHERE organization_id = v_org AND lower(email) = lower(v_sa_email)
          AND client_type IN ('sa_non_mtd','sa_mtd')
        LIMIT 1;
      IF v_client_id IS NULL THEN
        INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
        VALUES (v_org, v_sa_first, v_sa_last, v_sa_email, v_sa_phone,
                CASE WHEN v_is_mtd THEN 'sa_mtd' ELSE 'sa_non_mtd' END,
                'pending', v_lead.notes)
        RETURNING id INTO v_client_id;

        INSERT INTO public.client_detail_sa (client_id, organization_id, is_mtd)
        VALUES (v_client_id, v_org, v_is_mtd)
        ON CONFLICT DO NOTHING;

        IF NOT v_canonical THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_org, v_client_id, 'active', 'practice', now());
        END IF;
      END IF;

      IF v_has_cgt THEN
        INSERT INTO public.client_detail_cgt (client_id, organization_id)
        VALUES (v_client_id, v_org)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END IF;

  IF v_has_partnership AND v_lead.id IS NOT NULL THEN
    SELECT id INTO v_partnership_id FROM public.clients
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
        AND client_type = 'partnership'
      LIMIT 1;
    IF v_partnership_id IS NULL THEN
      INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
      VALUES (v_org, v_lead.first_name, v_lead.last_name, v_lead.email, v_lead.phone,
              'partnership', 'pending',
              coalesce(v_lead.notes,'') || E'\n[Action required] Partnership second contact required.')
      RETURNING id INTO v_partnership_id;
      INSERT INTO public.client_detail_partnership (client_id, organization_id)
      VALUES (v_partnership_id, v_org) ON CONFLICT DO NOTHING;
      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (v_org, v_partnership_id, 'active', 'practice', now());
      END IF;

      INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
      VALUES (v_org, 'PARTNERSHIP_SECOND_CONTACT_REQUIRED', 'client', v_partnership_id,
              jsonb_build_object('quote_id', v_quote.id, 'lead_id', v_lead.id));
    END IF;
    IF v_client_id IS NULL THEN v_client_id := v_partnership_id; END IF;
  END IF;

  IF v_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = v_company_id;
  ELSE
    SELECT NULL::uuid AS id,
           NULL::int  AS year_end_month,
           NULL::int  AS year_end_day
    INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  IF NOT v_canonical THEN
    PERFORM public.lifecycle_materialize_jobs(
      v_org, v_client_id, v_company_id, v_partnership_id, v_quote.id,
      'quote_acceptance:' || v_quote.id::text);
  END IF;

  UPDATE public.quotes
     SET status = 'accepted',
         accepted_at = now(),
         sent_at = COALESCE(sent_at, now()),
         client_id = COALESCE(client_id, v_client_id),
         company_id = COALESCE(company_id, v_company_id),
         ported_to_client_id = COALESCE(ported_to_client_id, v_client_id),
         ported_to_company_id = COALESCE(ported_to_company_id, v_company_id),
         ported_at = COALESCE(ported_at, now())
   WHERE id = v_quote.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads SET pipeline_stage = 'won', updated_at = now() WHERE id = v_quote.lead_id;
  END IF;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_ACCEPTED', 'quote', v_quote.id,
          jsonb_build_object('client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id));

  RETURN jsonb_build_object('success', true, 'client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id);
END;
$$;


--
-- Name: public_complete_billing(uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_complete_billing(p_application_id uuid, p_stripe_session_id text, p_amount numeric, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  UPDATE public.onboarding_applications
     SET billing_status = 'completed',
         billing_amount = COALESCE(p_amount, billing_amount),
         stripe_checkout_session_id = COALESCE(p_stripe_session_id, stripe_checkout_session_id),
         billing_completed_at = now(),
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status','portal_pending');
END;
$$;


--
-- Name: public_get_engagement_letter_for_signing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_engagement_letter_for_signing(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uuid     uuid;
  v_sig      public.engagement_letter_signatories%ROWTYPE;
  v_letter   public.engagement_letters%ROWTYPE;
  v_org_name text;
  v_progress jsonb;
  v_expired  boolean;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('found', false, 'error', 'Missing signing token');
  END IF;

  -- A signatory token is a uuid; a letter token is free text. A non-uuid string simply
  -- means "this can only be a letter token".
  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_uuid := NULL;
  END;

  IF v_uuid IS NOT NULL THEN
    SELECT * INTO v_sig
      FROM public.engagement_letter_signatories
     WHERE signature_token = v_uuid;
  END IF;

  IF v_sig.id IS NOT NULL THEN
    SELECT * INTO v_letter FROM public.engagement_letters WHERE id = v_sig.engagement_letter_id;
  ELSE
    SELECT * INTO v_letter FROM public.engagement_letters WHERE signature_token = trim(p_token);
  END IF;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('found', false,
      'error', 'This engagement letter link is invalid or has expired.');
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
    FROM public.organizations o
    LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
   WHERE o.id = v_letter.organization_id;

  v_progress := public.el_signature_progress(v_letter.id);
  v_expired  := (v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now());

  RETURN jsonb_build_object(
    'found', true,
    'firm_name', COALESCE(v_org_name, 'Your Accountant'),
    'letter', jsonb_build_object(
      'id',             v_letter.id,
      'document_content', v_letter.document_content,
      'status',         v_letter.status,
      'signing_rule',   COALESCE(v_letter.signing_rule, 'all'),
      'signed_at',      v_letter.signed_at,
      'expired',        v_expired
    ),
    'signer', CASE WHEN v_sig.id IS NULL THEN NULL ELSE jsonb_build_object(
      'kind',         'signatory',
      'signatory_id', v_sig.id,
      'name',         v_sig.signer_name,
      'email',        v_sig.signer_email,
      'required',     v_sig.required,
      'signed_at',    v_sig.signed_at
    ) END,
    'progress', v_progress,
    'requires_personal_link', (
      v_sig.id IS NULL AND COALESCE((v_progress->>'has_signatories')::boolean, false)
    )
  );
END;
$$;


--
-- Name: FUNCTION public_get_engagement_letter_for_signing(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.public_get_engagement_letter_for_signing(p_token text) IS 'Public (anon) read for the engagement-letter signing page. Resolves a per-signatory token or the letter-level token. Exists because engagement_letters has RLS with no anon SELECT policy — the page must never query that table directly.';


--
-- Name: public_get_onboarding(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_onboarding(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app record;
  v_org record;
  v_brand record;
  v_quote record;
  v_docs jsonb;
  v_engagement record;
  v_has_connect boolean;
  v_display_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Onboarding application not found' USING ERRCODE='P0002'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT id, name, logo_url, stripe_connect_account_id INTO v_org
    FROM public.organizations WHERE id = v_app.organization_id;
  v_has_connect := v_org.stripe_connect_account_id IS NOT NULL;

  SELECT trading_name, legal_name INTO v_brand
    FROM public.organization_branding WHERE organization_id = v_app.organization_id;

  v_display_name := COALESCE(NULLIF(v_brand.trading_name, ''), NULLIF(v_brand.legal_name, ''), v_org.name);

  SELECT id, quote_number, accepted_snapshot, currency
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id, 'document_type', document_type, 'file_name', file_name,
    'file_path', file_path, 'created_at', created_at
  ) ORDER BY created_at), '[]'::jsonb) INTO v_docs
    FROM public.onboarding_documents WHERE application_id = p_application_id;

  SELECT id, signed_at, sent_at, document_content INTO v_engagement
    FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id
   ORDER BY created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'application', to_jsonb(v_app) - 'access_token' - 'access_token_expires_at',
    'organization', jsonb_build_object(
      'id', v_org.id,
      'name', v_display_name,
      'logo_url', v_org.logo_url,
      'has_stripe_connect', v_has_connect
    ),
    'quote', to_jsonb(v_quote),
    'documents', v_docs,
    'engagement_letter', to_jsonb(v_engagement)
  );
END;
$$;


--
-- Name: public_get_quote_by_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_quote_by_token(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record; v_quote record; v_practice_name text; v_recipient_name text; v_lines jsonb;
  v_onboarding_id uuid;
  v_access_token text;
  v_lead record;
  v_app_type text;
  v_first_name text;
  v_last_name text;
  v_preferred text;
  v_email text;
  v_phone text;
  v_company_name text;
  v_company_number text;
  v_has_company boolean;
  v_snapshot jsonb;
  v_total_now numeric;
  v_total_monthly numeric;
  v_total_annual numeric;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), '')
      INTO v_recipient_name FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(preferred_name), ''),
                    NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), ''))
      INTO v_recipient_name FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(c.preferred_name), ''),
                    NULLIF(trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''))
      INTO v_recipient_name
    FROM clients c
    WHERE c.company_id = v_quote.company_id
    ORDER BY c.created_at ASC LIMIT 1;

    IF v_recipient_name IS NULL THEN
      SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'service_id', ql.service_id,
    'service_code', sc.code,
    'service_name', COALESCE(NULLIF(ql.description_override, ''), sc.name),
    'quantity', ql.quantity, 'unit_price', ql.unit_price,
    'subtotal', ql.subtotal, 'billing_frequency', ql.billing_frequency
  ) ORDER BY ql.line_order, ql.created_at), '[]'::jsonb)
    INTO v_lines
  FROM quote_lines ql JOIN services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  SELECT id, access_token INTO v_onboarding_id, v_access_token
  FROM onboarding_applications
  WHERE quote_id = v_quote.id
    AND status <> 'cancelled'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_onboarding_id IS NULL AND v_quote.status = 'accepted' THEN
    IF v_quote.lead_id IS NOT NULL THEN
      SELECT * INTO v_lead FROM leads WHERE id = v_quote.lead_id;
      v_first_name := v_lead.first_name;
      v_last_name := v_lead.last_name;
      v_email := v_lead.email;
      v_phone := v_lead.phone;
    ELSIF v_quote.client_id IS NOT NULL THEN
      SELECT first_name, last_name, email, phone
        INTO v_first_name, v_last_name, v_email, v_phone
        FROM clients WHERE id = v_quote.client_id;
    END IF;

    v_has_company := v_quote.company_id IS NOT NULL;
    IF v_has_company THEN
      SELECT company_name, company_number INTO v_company_name, v_company_number
        FROM companies WHERE id = v_quote.company_id;
    END IF;

    v_app_type := CASE WHEN v_has_company THEN 'company' ELSE 'individual' END;

    INSERT INTO onboarding_applications (
      organization_id, lead_id, quote_id, application_type, status,
      first_name, last_name, email, phone,
      company_name, company_number, client_id, company_id
    ) VALUES (
      v_quote.organization_id, v_quote.lead_id, v_quote.id, v_app_type, 'in_progress',
      v_first_name, v_last_name, v_email, v_phone,
      v_company_name, v_company_number, v_quote.client_id, v_quote.company_id
    )
    RETURNING id, access_token INTO v_onboarding_id, v_access_token;
  END IF;

  IF v_quote.status <> 'accepted' THEN
    v_access_token := NULL;

  ELSIF v_onboarding_id IS NOT NULL AND (v_access_token IS NULL OR v_access_token = '') THEN
    UPDATE onboarding_applications
       SET access_token = public.gen_onboarding_access_token(),
           access_token_expires_at = COALESCE(access_token_expires_at, now() + interval '90 days')
     WHERE id = v_onboarding_id
    RETURNING access_token INTO v_access_token;
  END IF;

  IF v_quote.status = 'accepted' AND (v_quote.accepted_snapshot IS NULL OR v_quote.accepted_snapshot = 'null'::jsonb) THEN
    SELECT
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') NOT IN ('monthly','annual') THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'monthly' THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'annual'  THEN COALESCE(subtotal,0) ELSE 0 END), 0)
      INTO v_total_now, v_total_monthly, v_total_annual
    FROM jsonb_to_recordset(v_lines)
      AS x(subtotal numeric, billing_frequency text);

    v_snapshot := jsonb_build_object(
      'lines', v_lines,
      'currency', COALESCE(v_quote.currency, 'GBP'),
      'quote_number', v_quote.quote_number,
      'accepted_at', COALESCE(v_quote.accepted_at, now()),
      'valid_until', v_quote.valid_until,
      'total_now', v_total_now,
      'total_monthly', v_total_monthly,
      'total_annual', v_total_annual,
      'total_amount', COALESCE(v_quote.total_amount, v_total_now + v_total_monthly + v_total_annual)
    );

    UPDATE quotes SET accepted_snapshot = v_snapshot WHERE id = v_quote.id;
    v_quote.accepted_snapshot := v_snapshot;
  END IF;

  RETURN jsonb_build_object(
    'quote_id', v_quote.id, 'quote_number', v_quote.quote_number, 'status', v_quote.status,
    'currency', v_quote.currency, 'total_amount', v_quote.total_amount,
    'valid_until', v_quote.valid_until, 'sent_at', v_quote.sent_at,
    'accepted_at', v_quote.accepted_at, 'rejected_at', v_quote.rejected_at,
    'notes', v_quote.notes, 'practice_name', v_practice_name,
    'recipient_name', v_recipient_name, 'lines', v_lines,
    'used', v_tok.used_at IS NOT NULL,
    'onboarding_application_id', v_onboarding_id,
    'onboarding_access_token', v_access_token
  );
END;
$$;


--
-- Name: public_preview_engagement_letter(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_preview_engagement_letter(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RETURN NULL; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
    IF v_rendered IS NOT NULL THEN RETURN v_rendered; END IF;
  END IF;

  RETURN '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2>' ||
    '<p>One-off fees due now total ' || v_currency || ' ' || v_total_now::text || '. ' ||
    'Ongoing monthly fees total ' || v_currency || ' ' || v_total_monthly::text || ' per month.</p>' ||
    '<h2>Confidentiality</h2>' ||
    '<p>The Firm will treat all information received in the course of this engagement as confidential, except where disclosure is required by law or regulatory authority.</p>' ||
    '<h2>Acceptance</h2>' ||
    '<p>By signing below the Client confirms acceptance of the terms above, in respect of the proposal accepted on ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>';
END;
$$;


--
-- Name: public_record_aml_upload(uuid, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_record_aml_upload(p_application_id uuid, p_document_type text, p_file_name text, p_file_path text, p_file_size integer, p_mime_type text, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_has_id boolean;
  v_has_poa boolean;
  v_next_status text;
BEGIN
  IF p_document_type NOT IN ('id','proof_of_address','incorporation_cert','other') THEN
    RAISE EXCEPTION 'Invalid document type';
  END IF;

  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  INSERT INTO public.onboarding_documents (
    organization_id, application_id, document_type, file_name, file_path, file_size, mime_type
  ) VALUES (
    v_app.organization_id, p_application_id, p_document_type, p_file_name, p_file_path, p_file_size, p_mime_type
  );

  v_has_id := v_app.id_document_uploaded OR p_document_type = 'id';
  v_has_poa := v_app.proof_of_address_uploaded OR p_document_type = 'proof_of_address';

  v_next_status := v_app.status;
  IF v_has_id AND v_has_poa AND v_app.status IN ('engagement_pending','aml_pending') THEN
    v_next_status := 'billing_pending';
  END IF;

  UPDATE public.onboarding_applications
     SET id_document_uploaded = v_has_id,
         proof_of_address_uploaded = v_has_poa,
         additional_documents_uploaded = CASE WHEN p_document_type IN ('incorporation_cert','other')
                                              THEN true ELSE additional_documents_uploaded END,
         aml_submitted_at = COALESCE(aml_submitted_at,
                                     CASE WHEN v_has_id AND v_has_poa THEN now() ELSE NULL END),
         status = v_next_status,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status', v_next_status);
END;
$$;


--
-- Name: public_reject_quote_by_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_reject_quote_by_token(p_token text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record;
  v_quote record;
  v_org uuid;
BEGIN
  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_quote.status NOT IN ('draft','sent') THEN RETURN jsonb_build_object('error','not_open'); END IF;

  v_org := v_quote.organization_id;

  UPDATE public.quotes
     SET status = 'rejected',
         rejected_at = now(),
         rejection_reason = COALESCE(NULLIF(p_reason,''), 'Declined by client')
   WHERE id = v_quote.id;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE id = v_tok.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads
       SET pipeline_stage = 'lost',
           lost_at = now(),
           lost_reason = COALESCE(NULLIF(p_reason,''), 'Quote declined')
     WHERE id = v_quote.lead_id
       AND pipeline_stage <> 'won';
  END IF;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_REJECTED', 'quote', v_quote.id,
          jsonb_build_object('reason', p_reason, 'source','public_token'));

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: public_reject_quote_by_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_reject_quote_by_token(p_token uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tok record; v_quote record; v_old_status text;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error', 'already_used'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','invalid_status','status', v_quote.status);
  END IF;
  v_old_status := v_quote.status;

  UPDATE quotes SET status='rejected', rejected_at=now(),
                   rejection_reason=COALESCE(p_reason,'Declined by client')
  WHERE id = v_quote.id;
  UPDATE quote_acceptance_tokens SET used_at=now() WHERE token = p_token;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id, metadata)
  VALUES (v_quote.organization_id, 'quote', v_quote.id, 'status_change', v_old_status, 'rejected', NULL,
          jsonb_build_object('source','public_token','reason', p_reason));

  RETURN jsonb_build_object('success', true, 'quote_id', v_quote.id, 'status','rejected');
END;
$$;


--
-- Name: public_save_onboarding_details(uuid, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_save_onboarding_details(p_application_id uuid, p_access_token text, p_utr text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_paye_reference text DEFAULT NULL::text, p_personal_details jsonb DEFAULT NULL::jsonb, p_ch_correction_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  UPDATE public.onboarding_applications
     SET utr = COALESCE(p_utr, utr),
         vat_number = COALESCE(p_vat_number, vat_number),
         paye_reference = COALESCE(p_paye_reference, paye_reference),
         personal_details = COALESCE(p_personal_details, personal_details),
         ch_correction_note = COALESCE(p_ch_correction_note, ch_correction_note),
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: public_sign_engagement_letter(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter(p_application_id uuid, p_signature_data jsonb, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_content text;
  v_letter_id uuid;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
  END IF;

  v_content := COALESCE(
    v_rendered,
    '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2><p>Total commercial terms as per accepted proposal dated ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>' ||
    '<h2>Acceptance</h2><p>By signing below the Client confirms acceptance of the terms above.</p>'
  );

  SELECT id INTO v_letter_id FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id ORDER BY created_at DESC LIMIT 1;

  IF v_letter_id IS NULL THEN
    INSERT INTO public.engagement_letters (
      organization_id, onboarding_application_id, document_content,
      sent_at, signed_at, signature_ip, signature_user_agent
    ) VALUES (
      v_app.organization_id, p_application_id, v_content,
      now(), now(),
      p_signature_data->>'ip', p_signature_data->>'user_agent'
    ) RETURNING id INTO v_letter_id;
  ELSE
    UPDATE public.engagement_letters
       SET document_content = v_content,
           signed_at = now(),
           sent_at = COALESCE(sent_at, now()),
           signature_ip = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           updated_at = now()
     WHERE id = v_letter_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'aml_pending',
         contracts_signed_at = now(),
         contracts_sent_at = COALESCE(contracts_sent_at, now()),
         signature_data = p_signature_data,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('engagement_letter_id', v_letter_id, 'status','aml_pending');
END;
$$;


--
-- Name: public_sign_engagement_letter_as_signatory(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uuid       uuid;
  v_sig        public.engagement_letter_signatories%ROWTYPE;
  v_letter     public.engagement_letters%ROWTYPE;
  v_app        public.onboarding_applications%ROWTYPE;
  v_name       text;
  v_progress   jsonb;
  v_satisfied  boolean;
  v_status     text;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END;

  -- Lock signatory then letter then application — always in that order, so two
  -- signatories of the same letter signing at the same moment serialise instead of
  -- deadlocking.
  SELECT * INTO v_sig
    FROM public.engagement_letter_signatories
   WHERE signature_token = v_uuid
   FOR UPDATE;

  IF v_sig.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE id = v_sig.engagement_letter_id
   FOR UPDATE;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  -- Idempotent: re-opening the emailed link and signing again is a no-op success, never
  -- a second signature.
  IF v_sig.signed_at IS NOT NULL THEN
    v_progress := public.el_signature_progress(v_letter.id);
    RETURN jsonb_build_object(
      'success', true, 'already_signed', true, 'signed_at', v_sig.signed_at,
      'all_signed', COALESCE((v_progress->>'satisfied')::boolean, false),
      'progress', v_progress, 'letter_status', v_letter.status
    );
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  SELECT * INTO v_app
    FROM public.onboarding_applications
   WHERE id = COALESCE(v_sig.onboarding_application_id, v_letter.onboarding_application_id)
   FOR UPDATE;

  IF v_app.id IS NOT NULL AND v_app.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This engagement is no longer open for signature. Please contact your accountant.');
  END IF;

  v_name := COALESCE(NULLIF(trim(p_signature_data->>'full_name'), ''), v_sig.signer_name);

  UPDATE public.engagement_letter_signatories
     SET signed_at            = now(),
         signer_name          = v_name,
         signature_ip         = p_signature_data->>'ip',
         signature_user_agent = p_signature_data->>'user_agent'
   WHERE id = v_sig.id;

  -- The rule lives in ONE place (T2d-1) — the same function the activation gate calls.
  v_progress  := public.el_signature_progress(v_letter.id);
  v_satisfied := COALESCE((v_progress->>'satisfied')::boolean, false);

  IF v_satisfied THEN
    UPDATE public.engagement_letters
       SET signed_at            = COALESCE(signed_at, now()),
           status               = 'signed',
           signature_name       = COALESCE(signature_name, v_name),
           signature_ip         = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           viewed_at            = COALESCE(viewed_at, now()),
           updated_at           = now()
     WHERE id = v_letter.id;

    -- The application-side write the emailed-link path has always been missing.
    IF v_app.id IS NOT NULL THEN
      UPDATE public.onboarding_applications
         SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
             contracts_sent_at   = COALESCE(contracts_sent_at, now()),
             signature_data      = COALESCE(signature_data, p_signature_data),
             status = CASE
               WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
               ELSE status
             END,
             updated_at = now()
       WHERE id = v_app.id;
    END IF;
  ELSE
    UPDATE public.engagement_letters
       SET status     = CASE WHEN status = 'signed' THEN 'signed' ELSE 'partially_signed' END,
           viewed_at  = COALESCE(viewed_at, now()),
           updated_at = now()
     WHERE id = v_letter.id;
  END IF;

  SELECT status INTO v_status FROM public.engagement_letters WHERE id = v_letter.id;

  RETURN jsonb_build_object(
    'success', true, 'signed_at', now(), 'all_signed', v_satisfied,
    'progress', v_progress, 'letter_status', v_status
  );
END;
$$;


--
-- Name: FUNCTION public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb) IS 'Records ONE signatory''s signature from their own emailed link, then evaluates the signing rule via el_signature_progress: letter status becomes partially_signed until the rule is satisfied, then signed + onboarding contracts_signed_at. Idempotent.';


--
-- Name: public_sign_engagement_letter_by_token(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter_by_token(p_signature_token text, p_signature_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_letter   record;
  v_progress jsonb;
BEGIN
  IF p_signature_token IS NULL OR length(trim(p_signature_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE signature_token = p_signature_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  IF v_letter.signed_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_signed', true, 'signed_at', v_letter.signed_at);
  END IF;

  -- T2d-2 (1): per-signatory letters must be signed through each signatory's own link.
  v_progress := public.el_signature_progress(v_letter.id);
  IF COALESCE((v_progress->>'has_signatories')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'requires_personal_link', true,
      'error', 'This engagement letter is signed by each signatory using the personal link emailed to them. Please use your own link, or ask your accountant to resend it.');
  END IF;

  UPDATE public.engagement_letters
     SET signed_at = now(),
         signature_name = COALESCE(signature_name, NULLIF(trim(p_signature_data->>'full_name'), '')),
         signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
         viewed_at = COALESCE(viewed_at, now())
   WHERE id = v_letter.id;

  -- T2d-2 (2): the application-side write this path always omitted.
  UPDATE public.engagement_letters
     SET status = 'signed', updated_at = now()
   WHERE id = v_letter.id;

  UPDATE public.onboarding_applications
     SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
         contracts_sent_at   = COALESCE(contracts_sent_at, now()),
         signature_data      = COALESCE(signature_data, p_signature_data),
         status = CASE
           WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
           ELSE status
         END,
         updated_at = now()
   WHERE id = v_letter.onboarding_application_id
     AND status NOT IN ('approved','rejected','cancelled');

  RETURN jsonb_build_object('success', true, 'signed_at', now());
END;
$$;


--
-- Name: public_skip_billing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_skip_billing(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  UPDATE public.onboarding_applications
     SET billing_status = 'skipped',
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id
     AND status NOT IN ('approved','rejected','cancelled');
  RETURN jsonb_build_object('status','portal_pending');
END;
$$;


--
-- Name: public_submit_onboarding_for_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_submit_onboarding_for_review(p_application_id uuid, p_portal_email text, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_org_name text;
  v_member record;
  v_client_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status = 'for_review' THEN
    RETURN jsonb_build_object('status','for_review','already', true);
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'for_review',
         portal_email = COALESCE(p_portal_email, portal_email),
         submitted_for_review_at = now(),
         updated_at = now()
   WHERE id = p_application_id;

  SELECT name INTO v_org_name FROM public.organizations WHERE id = v_app.organization_id;
  v_client_name := COALESCE(v_app.company_name,
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.email, 'New onboarding');

  FOR v_member IN
    SELECT user_id FROM public.organization_users WHERE organization_id = v_app.organization_id
  LOOP
    INSERT INTO public.notifications (
      organization_id, user_id, type, title, message, entity_type, entity_id
    ) VALUES (
      v_app.organization_id, v_member.user_id, 'onboarding_for_review',
      'New onboarding ready for review',
      v_client_name || ' has completed onboarding and is ready for review.',
      'onboarding_application', p_application_id
    );
  END LOOP;

  INSERT INTO public.email_queue (
    organization_id, to_email, to_name, subject, body_html, status, context, entity_type, entity_id
  )
  SELECT v_app.organization_id,
         u.email,
         COALESCE(u.raw_user_meta_data->>'full_name', u.email),
         'Onboarding ready for review: ' || v_client_name,
         '<p>' || v_client_name || ' has completed the onboarding wizard.</p>' ||
         '<p>Please review in AccountancyOS.</p>',
         'pending', 'onboarding', 'onboarding_application', p_application_id
    FROM public.organization_users om
    JOIN auth.users u ON u.id = om.user_id
   WHERE om.organization_id = v_app.organization_id
     AND om.role = 'owner'
     AND u.email IS NOT NULL;

  RETURN jsonb_build_object('status','for_review','already', false);
END;
$$;


--
-- Name: queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_email_safe(p_organization_id uuid, p_to_email text, p_to_name text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid, p_merge_data jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_email_id uuid;
  v_status text;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Draft if no scheduled_at, queued otherwise
  v_status := CASE WHEN p_scheduled_at IS NULL THEN 'draft' ELSE 'queued' END;

  INSERT INTO email_queue (
    organization_id, to_email, to_name, subject, body_html, template_id,
    merge_data, scheduled_at, status, entity_type, entity_id, created_by
  ) VALUES (
    p_organization_id, p_to_email, p_to_name, p_subject, p_body_html, p_template_id,
    p_merge_data, p_scheduled_at, v_status, p_entity_type, p_entity_id, v_user_id
  ) RETURNING id INTO v_email_id;

  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, after_state)
  VALUES (p_organization_id, v_user_id, 'email', v_email_id, 'queued',
    jsonb_build_object('status', v_status, 'to_email', p_to_email));

  RETURN jsonb_build_object('success', true, 'email_id', v_email_id, 'status', v_status);
END;
$$;


--
-- Name: queue_filing_for_submission(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_filing_for_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_validation JSONB;
  v_filing RECORD;
  v_snapshot_hash TEXT;
  v_idempotency_key TEXT;
  v_queue_id UUID;
  v_existing_queue RECORD;
BEGIN
  -- Validate first
  v_validation := public.validate_filing_submission(p_filing_id, p_filing_type, p_user_id);
  
  IF NOT (v_validation->>'valid')::boolean THEN
    RETURN v_validation;
  END IF;
  
  -- Get filing and snapshot hash
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;
  
  IF p_filing_type = 'ACCOUNTS_CH' THEN
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.accounts_model_snapshots WHERE id = v_filing.accounts_snapshot_id;
  ELSE
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.ct_computation_snapshots WHERE id = v_filing.ct_snapshot_id;
  END IF;
  
  -- Generate idempotency key
  v_idempotency_key := v_filing.organization_id || ':' || p_filing_type || ':' || 
    COALESCE(v_filing.company_id::text, v_filing.client_id::text) || ':' ||
    v_filing.period_start || ':' || v_filing.period_end || ':' || v_snapshot_hash;
  
  -- Check for existing queue entry
  SELECT * INTO v_existing_queue 
  FROM public.filing_queue 
  WHERE idempotency_key = v_idempotency_key AND status NOT IN ('failed', 'cancelled');
  
  IF v_existing_queue.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'valid', false,
      'errors', ARRAY['Filing already queued or submitted with this snapshot'],
      'existing_queue_id', v_existing_queue.id
    );
  END IF;
  
  -- Insert queue entry
  INSERT INTO public.filing_queue (
    organization_id, filing_id, filing_type, idempotency_key, snapshot_hash, 
    approval_id, status
  )
  VALUES (
    v_filing.organization_id, p_filing_id, p_filing_type, v_idempotency_key, 
    v_snapshot_hash, (v_validation->>'approval_id')::uuid, 'queued'
  )
  RETURNING id INTO v_queue_id;
  
  -- Update filing status
  UPDATE public.filings SET status = 'queued' WHERE id = p_filing_id;
  
  RETURN jsonb_build_object(
    'valid', true,
    'queue_id', v_queue_id,
    'idempotency_key', v_idempotency_key
  );
END;
$$;


--
-- Name: quote_acceptance_tokens_backfill_org(); Type: FUNCTION; Schema: public; Owner: -
