--
-- Name: trigger_records_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_records_request(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job jobs%ROWTYPE;
  v_service services_catalog%ROWTYPE;
  v_template templates%ROWTYPE;
  v_questionnaire_instance_id uuid;
  v_client_email text;
  v_client_name text;
  v_access_token text;
BEGIN
  -- Get job
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job not found');
  END IF;
  
  -- Get service
  IF v_job.service_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job has no service assigned');
  END IF;
  
  SELECT * INTO v_service FROM services_catalog WHERE id = v_job.service_id;
  IF v_service.records_request_template_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Service has no records request template');
  END IF;
  
  -- Get template
  SELECT * INTO v_template FROM templates WHERE id = v_service.records_request_template_id;
  
  -- Get client email
  IF v_job.client_id IS NOT NULL THEN
    SELECT email, first_name || ' ' || last_name INTO v_client_email, v_client_name
    FROM clients WHERE id = v_job.client_id;
  ELSIF v_job.company_id IS NOT NULL THEN
    SELECT email, company_name INTO v_client_email, v_client_name
    FROM companies WHERE id = v_job.company_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Job has no client or company');
  END IF;
  
  -- Generate access token
  v_access_token := encode(gen_random_bytes(32), 'hex');
  
  -- Create questionnaire instance
  INSERT INTO questionnaire_instances (
    organization_id,
    template_id,
    client_id,
    company_id,
    job_id,
    status,
    access_token,
    token_expires_at
  ) VALUES (
    v_job.organization_id,
    v_service.records_request_template_id,
    v_job.client_id,
    v_job.company_id,
    p_job_id,
    'sent',
    v_access_token,
    now() + interval '30 days'
  ) RETURNING id INTO v_questionnaire_instance_id;
  
  -- Link to job
  INSERT INTO job_questionnaire_instances (
    job_id,
    questionnaire_instance_id,
    questionnaire_type,
    trigger_status,
    feeds_workpaper
  ) VALUES (
    p_job_id,
    v_questionnaire_instance_id,
    'records_request',
    'awaiting_info',
    true
  );
  
  -- Update job
  UPDATE jobs SET info_requested_at = now() WHERE id = p_job_id;
  
  -- Queue email (will be sent via connected mailbox)
  INSERT INTO email_queue (
    organization_id,
    to_email,
    to_name,
    subject,
    body_html,
    status,
    entity_type,
    entity_id,
    job_id,
    client_id,
    company_id,
    context,
    merge_data
  ) VALUES (
    v_job.organization_id,
    v_client_email,
    v_client_name,
    'Information Request: ' || v_job.name,
    '<p>Dear ' || v_client_name || ',</p>' ||
    '<p>We need some information from you to complete your ' || v_job.name || '.</p>' ||
    '<p>Please click the link below to provide the required information:</p>' ||
    '<p><a href="{{questionnaire_url}}">Complete Information Request</a></p>' ||
    '<p>This link will expire in 30 days.</p>',
    'queued',
    'questionnaire',
    v_questionnaire_instance_id,
    p_job_id,
    v_job.client_id,
    v_job.company_id,
    'records_request',
    jsonb_build_object(
      'questionnaire_url', '{{BASE_URL}}/questionnaire/' || v_access_token,
      'job_name', v_job.name,
      'client_name', v_client_name
    )
  );
  
  -- Log audit
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, metadata)
  VALUES (
    v_job.organization_id,
    'job',
    p_job_id,
    'records_request_sent',
    jsonb_build_object('questionnaire_instance_id', v_questionnaire_instance_id)
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'questionnaire_instance_id', v_questionnaire_instance_id
  );
END;
$$;


--
-- Name: trigger_records_request(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_records_request(p_job_id uuid, p_questionnaire_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job jobs%ROWTYPE;
  v_questionnaire_instance_id uuid;
  v_access_token text;
  v_client_email text;
  v_client_name text;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % not found', p_job_id;
  END IF;

  SELECT COALESCE(c.email, co.email),
         COALESCE(TRIM(c.first_name || ' ' || c.last_name), co.company_name)
    INTO v_client_email, v_client_name
    FROM public.jobs j
    LEFT JOIN public.clients   c  ON c.id  = j.client_id
    LEFT JOIN public.companies co ON co.id = j.company_id
   WHERE j.id = p_job_id;

  IF v_client_email IS NULL OR v_client_email = '' THEN
    RAISE EXCEPTION 'No client email on job %', p_job_id;
  END IF;

  v_access_token := encode(gen_random_bytes(24), 'hex');
  INSERT INTO public.questionnaire_instances (
    organization_id, template_id, job_id, client_id, company_id,
    status, access_token, expires_at
  ) VALUES (
    v_job.organization_id, p_questionnaire_template_id, p_job_id, v_job.client_id, v_job.company_id,
    'sent', v_access_token, now() + interval '30 days'
  ) RETURNING id INTO v_questionnaire_instance_id;

  INSERT INTO public.email_queue (
    organization_id,
    to_email,
    to_name,
    subject,
    body_html,
    status,
    entity_type,
    entity_id,
    job_id,
    client_id,
    company_id,
    context,
    merge_data
  ) VALUES (
    v_job.organization_id,
    v_client_email,
    v_client_name,
    'Information Request: ' || v_job.name,
    '<p>Dear ' || v_client_name || ',</p>' ||
    '<p>We need some information from you to complete your ' || v_job.name || '.</p>' ||
    '<p>Please click the link below to provide the required information:</p>' ||
    '<p><a href="{{questionnaire_url}}">Complete Information Request</a></p>' ||
    '<p>This link will expire in 30 days.</p>',
    'pending',
    'questionnaire',
    v_questionnaire_instance_id,
    p_job_id,
    v_job.client_id,
    v_job.company_id,
    'job',
    jsonb_build_object(
      'questionnaire_url', '{{BASE_URL}}/questionnaire/' || v_access_token,
      'job_name', v_job.name,
      'client_name', v_client_name
    )
  );

  RETURN jsonb_build_object('status', 'sent', 'questionnaire_instance_id', v_questionnaire_instance_id);
END;
$$;


--
-- Name: try_parse_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_parse_numeric(val text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF val IS NULL OR val = '' THEN
    RETURN NULL;
  END IF;
  RETURN val::numeric;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


--
-- Name: unlock_period(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF NOT public.has_organization_role(p_organization_id, 'owner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only owners may unlock periods');
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'A reason is required to unlock a period');
  END IF;
  DELETE FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND company_id = p_entity_id));
  RETURN jsonb_build_object('success', true);
END; $$;


--
-- Name: unmatch_bank_transaction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmatch_bank_transaction(p_bank_transaction_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn RECORD;
  v_user_id UUID := auth.uid();
  v_reverse JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  IF upper(COALESCE(v_txn.status,'')) = 'RECONCILED' THEN
    RAISE EXCEPTION 'Cannot unmatch a reconciled transaction; reopen reconciliation first';
  END IF;
  IF upper(COALESCE(v_txn.status,'')) <> 'MATCHED' THEN
    RAISE EXCEPTION 'Transaction is not matched';
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  v_before := to_jsonb(v_txn);

  -- Delete linked payments (Phase 3 triggers recompute aged balances)
  DELETE FROM public.invoice_payments WHERE bank_transaction_id = p_bank_transaction_id;
  DELETE FROM public.bill_payments    WHERE bank_transaction_id = p_bank_transaction_id;

  -- Reverse the journal if present and not already reversed
  IF v_txn.matched_ledger_entry_id IS NOT NULL THEN
    v_reverse := public.reverse_journal(
      v_txn.matched_ledger_entry_id,
      CURRENT_DATE,
      COALESCE(p_reason, 'Bank match unmatched')
    );
  END IF;

  UPDATE public.bank_transactions
     SET status = 'UNREVIEWED',
         matched_ledger_entry_id = NULL,
         rule_id = NULL
   WHERE id = p_bank_transaction_id;

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, reason, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'unmatch_bank_transaction', v_user_id,
    v_before,
    jsonb_build_object('status','UNREVIEWED'),
    p_reason,
    jsonb_build_object('reverse_result', v_reverse)
  );

  RETURN jsonb_build_object('success', true, 'reverse_result', v_reverse);
END;
$$;


--
-- Name: update_automation_rule_safe(uuid, text, text, jsonb, text, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_automation_rule_safe(p_rule_id uuid, p_name text DEFAULT NULL::text, p_trigger_type text DEFAULT NULL::text, p_trigger_config jsonb DEFAULT NULL::jsonb, p_action_type text DEFAULT NULL::text, p_action_config jsonb DEFAULT NULL::jsonb, p_is_active boolean DEFAULT NULL::boolean, p_email_mode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_rule record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rule not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_rule.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_rule.organization_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Manager role required');
  END IF;

  UPDATE automation_rules SET
    name = COALESCE(p_name, name),
    trigger_type = COALESCE(p_trigger_type, trigger_type),
    trigger_config = COALESCE(p_trigger_config, trigger_config),
    action_type = COALESCE(p_action_type, action_type),
    action_config = COALESCE(p_action_config, action_config),
    is_active = COALESCE(p_is_active, is_active),
    email_mode = COALESCE(p_email_mode, email_mode),
    updated_at = now()
  WHERE id = p_rule_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_rule.organization_id, 'automation_rule', p_rule_id, 'updated', v_user_id);

  RETURN jsonb_build_object('success', true, 'rule_id', p_rule_id);
END;
$$;


--
-- Name: update_bill_draft_safe(uuid, uuid, text, text, date, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_bill_draft_safe(p_bill_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_bill_number text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date date DEFAULT NULL::date, p_due_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_bill record;
  v_line jsonb;
  v_line_number int := 0;
  v_total_net numeric := 0;
  v_total_vat numeric := 0;
  v_total_gross numeric := 0;
  v_quantity numeric;
  v_unit_price numeric;
  v_vat_rate numeric;
  v_net numeric;
  v_vat numeric;
  v_gross numeric;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;
  
  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  
  IF v_bill.status NOT IN ('DRAFT', 'draft') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT bills can be updated');
  END IF;

  IF p_lines IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      IF v_quantity IS NULL OR v_unit_price IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid line data');
      END IF;
    END LOOP;
  END IF;

  UPDATE bills SET
    supplier_id = COALESCE(p_supplier_id, supplier_id),
    bill_number = COALESCE(p_bill_number, bill_number),
    reference = COALESCE(p_reference, reference),
    issue_date = COALESCE(p_issue_date, issue_date),
    due_date = COALESCE(p_due_date, due_date),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_bill_id;

  IF p_lines IS NOT NULL THEN
    DELETE FROM bill_lines WHERE bill_id = p_bill_id;
    
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);
      
      v_net := ROUND(v_quantity * v_unit_price, 2);
      v_vat := ROUND(v_net * v_vat_rate / 100, 2);
      v_gross := v_net + v_vat;
      
      v_total_net := v_total_net + v_net;
      v_total_vat := v_total_vat + v_vat;
      v_total_gross := v_total_gross + v_gross;
      
      INSERT INTO bill_lines (
        bill_id, line_number, description, quantity, unit_price,
        vat_rate, net_amount, vat_amount, gross_amount, account_id, vat_code_id
      ) VALUES (
        p_bill_id, v_line_number, v_line->>'description',
        v_quantity, v_unit_price, v_vat_rate, v_net, v_vat, v_gross,
        NULLIF(v_line->>'account_id', '')::uuid,
        NULLIF(v_line->>'vat_code_id', '')::uuid
      );
    END LOOP;

    UPDATE bills SET total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross
    WHERE id = p_bill_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;


--
-- Name: update_bill_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_bill_payment_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_paid NUMERIC;
  v_bill_total NUMERIC;
  v_bill_id UUID;
BEGIN
  v_bill_id := COALESCE(NEW.bill_id, OLD.bill_id);
  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid FROM bill_payments WHERE bill_id = v_bill_id;
  SELECT total_gross INTO v_bill_total FROM bills WHERE id = v_bill_id;
  UPDATE bills
  SET 
    amount_paid = v_total_paid,
    status = CASE
      WHEN v_total_paid = 0 THEN 'AWAITING_PAYMENT'
      WHEN v_total_paid >= v_bill_total THEN 'PAID'
      ELSE 'PART_PAID'
    END,
    updated_at = now()
  WHERE id = v_bill_id AND status NOT IN ('DRAFT', 'VOID');
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_bill_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_bill_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE bills
  SET 
    total_net = COALESCE((SELECT SUM(net_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    total_vat = COALESCE((SELECT SUM(vat_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    total_gross = COALESCE((SELECT SUM(gross_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.bill_id, OLD.bill_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_credit_note_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_credit_note_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE credit_notes
  SET 
    subtotal = COALESCE((SELECT SUM(net_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    vat_total = COALESCE((SELECT SUM(vat_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    total = COALESCE((SELECT SUM(gross_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.credit_note_id, OLD.credit_note_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_deadline_safe(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_deadline_safe(p_deadline_id uuid, p_updates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deadline record;
BEGIN
  -- Fetch deadline
  SELECT * INTO v_deadline FROM deadlines WHERE id = p_deadline_id;
  
  IF v_deadline.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Deadline not found');
  END IF;
  
  -- Check permission
  IF NOT can_modify_jobs(auth.uid(), v_deadline.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  -- Update deadline
  UPDATE deadlines SET 
    name = COALESCE(p_updates->>'name', name),
    due_date = COALESCE((p_updates->>'due_date')::date, due_date),
    status = COALESCE(p_updates->>'status', status),
    updated_at = now()
  WHERE id = p_deadline_id;
  
  -- Write audit log
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_deadline.organization_id, 'deadline', p_deadline_id, 'update', auth.uid(), p_updates);
  
  RETURN jsonb_build_object('success', true);
END;
$$;


