  RETURN NEW;
END;
$$;


--
-- Name: update_invoice_draft_safe(uuid, uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoice_draft_safe(p_invoice_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_contact_name text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date text DEFAULT NULL::text, p_due_date text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_line jsonb;
  v_line_number int := 0;
  v_quantity numeric; v_unit_price numeric; v_vat_rate numeric;
  v_net_amount numeric; v_vat_amount numeric; v_gross_amount numeric;
  v_total_net numeric := 0; v_total_vat numeric := 0; v_total_gross numeric := 0;
  v_validated_lines jsonb[] := ARRAY[]::jsonb[];
  v_is_portal boolean := false;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF v_invoice IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42704';
  END IF;

  -- Scoped to THIS invoice's owning entity: a portal user cannot reach another client's
  -- invoice, and portal authority covers draft create/edit only.
  v_is_portal := public.portal_has_perm(v_invoice.client_id, v_invoice.company_id, 'allow_invoice_create');

  IF NOT v_is_portal THEN
    IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
      RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
    END IF;
    -- INTENTIONAL TIGHTENING (owner ruling): update now requires the invoice capability.
    -- A member without can_create_invoices could previously edit drafts and no longer can.
    IF NOT public.can_create_invoices(v_user_id, v_invoice.organization_id) THEN
      RAISE EXCEPTION 'Permission denied: cannot edit invoices' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_invoice.status != 'DRAFT' THEN
    RAISE EXCEPTION 'Can only edit DRAFT invoices' USING ERRCODE = '42501';
  END IF;

  IF p_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customers WHERE id = p_customer_id AND organization_id = v_invoice.organization_id
  ) THEN
    RAISE EXCEPTION 'Customer does not belong to organization' USING ERRCODE = '42501';
  END IF;

  UPDATE invoices SET
    customer_id   = COALESCE(p_customer_id, customer_id),
    contact_name  = COALESCE(p_contact_name, contact_name),
    contact_email = COALESCE(p_contact_email, contact_email),
    reference     = COALESCE(p_reference, reference),
    issue_date    = COALESCE(p_issue_date::date, issue_date),
    due_date      = COALESCE(p_due_date::date, due_date),
    notes         = COALESCE(p_notes, notes),
    updated_at    = now()
  WHERE id = p_invoice_id;

  IF p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0 THEN
    -- PHASE 1 — validate everything before destroying anything.
    v_line_number := 0;
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);

      IF v_quantity IS NULL OR v_unit_price IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity or unit_price is missing/invalid', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_quantity <= 0 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity must be > 0', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_unit_price < 0 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: unit_price must be >= 0', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_vat_rate < 0 OR v_vat_rate > 100 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_rate must be between 0 and 100', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'account_id', '') IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is required', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'account_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is not a valid identifier', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'vat_code_id', '') IS NOT NULL
         AND NULLIF(v_line->>'vat_code_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_code_id is not a valid identifier', v_line_number), ERRCODE = '22023';
      END IF;

      v_validated_lines := array_append(v_validated_lines, v_line);
    END LOOP;

    -- PHASE 2 — only now is mutation safe.
    DELETE FROM invoice_lines WHERE invoice_id = p_invoice_id;

    v_line_number := 0;
    FOREACH v_line IN ARRAY v_validated_lines
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);

      v_net_amount := ROUND(v_quantity * v_unit_price, 2);
      v_vat_amount := ROUND(v_net_amount * (v_vat_rate / 100), 2);
      v_gross_amount := v_net_amount + v_vat_amount;
      v_total_net := v_total_net + v_net_amount;
      v_total_vat := v_total_vat + v_vat_amount;
      v_total_gross := v_total_gross + v_gross_amount;

      INSERT INTO invoice_lines (
        invoice_id, line_number, description, quantity, unit_price, vat_rate,
        vat_code_id, account_id, net_amount, vat_amount, gross_amount
      ) VALUES (
        p_invoice_id, v_line_number, COALESCE(v_line->>'description', ''),
        v_quantity, v_unit_price, v_vat_rate,
        NULLIF(v_line->>'vat_code_id', '')::uuid, NULLIF(v_line->>'account_id', '')::uuid,
        v_net_amount, v_vat_amount, v_gross_amount
      );
    END LOOP;

    UPDATE invoices SET
      total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross,
      remaining_balance = v_total_gross - COALESCE(amount_paid, 0),
      updated_at = now()
    WHERE id = p_invoice_id;
  END IF;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_invoice.organization_id, 'invoice', p_invoice_id, 'updated', v_user_id,
    jsonb_build_object('lines_updated', p_lines IS NOT NULL,
                       'via', CASE WHEN v_is_portal THEN 'portal' ELSE 'staff' END));

  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id);
END;
$_$;


--
-- Name: update_invoice_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoice_payment_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_paid NUMERIC;
  v_invoice_total NUMERIC;
  v_invoice_id UUID;
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
  FROM invoice_payments
  WHERE invoice_id = v_invoice_id;

  SELECT total_gross INTO v_invoice_total
  FROM invoices
  WHERE id = v_invoice_id;

  UPDATE invoices
  SET
    amount_paid = v_total_paid,
    status = CASE
      WHEN v_total_paid = 0 THEN 'sent'
      WHEN v_total_paid >= v_invoice_total THEN 'paid'
      ELSE 'part_paid'
    END,
    updated_at = now()
  WHERE id = v_invoice_id
    AND status NOT IN ('draft', 'voided', 'cancelled');

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_invoice_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoice_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE invoices
  SET 
    total_net = COALESCE((
      SELECT SUM(net_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    total_vat = COALESCE((
      SELECT SUM(vat_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    total_gross = COALESCE((
      SELECT SUM(gross_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_issued_invoice_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_issued_invoice_safe(p_invoice_id uuid, p_updates jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_user_role TEXT;
  v_before_state JSONB;
  v_allowed_fields TEXT[] := ARRAY['notes', 'internal_notes', 'tags', 'attachments', 'message_to_customer'];
  v_manager_fields TEXT[] := ARRAY['due_date'];
  v_key TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  
  IF v_invoice.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  
  v_org_id := v_invoice.organization_id;
  
  -- Check basic permission
  IF NOT user_in_organization(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  -- Get user role
  SELECT role INTO v_user_role FROM organization_users 
  WHERE user_id = v_user_id AND organization_id = v_org_id;
  
  -- Validate status - only issued, part_paid, or paid invoices
  IF v_invoice.status NOT IN ('ISSUED', 'PART_PAID', 'PAID', 'AWAITING_PAYMENT') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot update invoice in ' || v_invoice.status || ' status');
  END IF;
  
  v_before_state := to_jsonb(v_invoice);
  
  -- Validate each field in updates
  FOR v_key IN SELECT jsonb_object_keys(p_updates)
  LOOP
    -- Check if field is allowed for all users
    IF v_key = ANY(v_allowed_fields) THEN
      CONTINUE;
    -- Check if field is allowed for manager+
    ELSIF v_key = ANY(v_manager_fields) THEN
      IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied: ' || v_key || ' requires manager role');
      END IF;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Field ' || v_key || ' is locked on issued invoices');
    END IF;
  END LOOP;
  
  -- Apply updates
  UPDATE invoices SET
    notes = COALESCE(p_updates->>'notes', notes),
    due_date = COALESCE((p_updates->>'due_date')::DATE, due_date),
    updated_at = now()
  WHERE id = p_invoice_id;
  
  -- Write audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice',
    p_invoice_id,
    'update_issued',
    NULL,
    NULL,
    NULL,
    v_before_state,
    (SELECT to_jsonb(i) FROM invoices i WHERE i.id = p_invoice_id),
    jsonb_build_object('updates', p_updates, 'reason', p_reason)
  );
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: update_job_status_safe(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_job_status_safe(p_job_id uuid, p_new_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job record;
  v_old_status text;
BEGIN
  -- Fetch job
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;
  
  IF v_job.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job not found');
  END IF;
  
  -- Check permission
  IF NOT can_modify_jobs(auth.uid(), v_job.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  v_old_status := v_job.status;
  
  -- Update job
  UPDATE jobs SET status = p_new_status, updated_at = now() WHERE id = p_job_id;
  
  -- Write audit log
  INSERT INTO audit_log (
    organization_id, entity_type, entity_id, action,
    field_name, old_value, new_value, user_id, metadata
  ) VALUES (
    v_job.organization_id, 'job', p_job_id, 'status_change',
    'status', v_old_status, p_new_status, auth.uid(),
    jsonb_build_object('reason', p_reason)
  );
  
  RETURN jsonb_build_object('success', true, 'old_status', v_old_status, 'new_status', p_new_status);
END;
$$;


--
-- Name: update_queued_email_safe(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_queued_email_safe(p_email_id uuid, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_to_email text DEFAULT NULL::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  -- FIXED: Block edits to failed emails and sending/sent
  IF v_email.status NOT IN ('draft', 'pending', 'queued') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only edit draft, pending, or queued emails');
  END IF;

  UPDATE email_queue SET
    subject = COALESCE(p_subject, subject),
    body_html = COALESCE(p_body_html, body_html),
    to_email = COALESCE(p_to_email, to_email),
    scheduled_at = COALESCE(p_scheduled_at, scheduled_at),
    updated_at = now()
  WHERE id = p_email_id;

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: update_shareholder_on_allotment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_shareholder_on_allotment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update shareholder shares_held
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_allotted,
    as_at_date = NEW.allotment_date,
    updated_at = now()
  WHERE id = NEW.shareholder_id;
  
  -- Update share class total
  UPDATE company_share_classes
  SET 
    total_shares_issued = total_shares_issued + NEW.shares_allotted,
    updated_at = now()
  WHERE id = NEW.share_class_id;
  
  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    shareholder_id, allotment_id, created_by
  )
  VALUES (
    NEW.company_id, 'allotment', NEW.allotment_date, 'workpaper',
    jsonb_build_object(
      'shares_allotted', NEW.shares_allotted,
      'price_per_share', NEW.price_per_share,
      'total_consideration', NEW.total_consideration
    ),
    NEW.shareholder_id, NEW.id, auth.uid()
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: update_shareholders_on_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_shareholders_on_transfer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Decrease from_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held - NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.from_shareholder_id;
  
  -- Increase to_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.to_shareholder_id;
  
  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    transfer_id, created_by
  )
  VALUES (
    NEW.company_id, 'transfer', NEW.transfer_date, 'workpaper',
    jsonb_build_object(
      'shares_transferred', NEW.shares_transferred,
      'from_shareholder_id', NEW.from_shareholder_id,
      'to_shareholder_id', NEW.to_shareholder_id,
      'consideration', NEW.consideration
    ),
    NEW.id, auth.uid()
  );
  
  RETURN NEW;
END;
$$;


