--
-- Name: user_has_org_role(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_org_role(check_user_id uuid, check_org_id uuid, required_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users 
    WHERE user_id = check_user_id 
      AND organization_id = check_org_id
      AND role = required_role
  );
