    locked_by uuid,
    partnership_allocation_id uuid,
    CONSTRAINT chk_filing_status CHECK ((status = ANY (ARRAY['not_started'::text, 'draft'::text, 'in_progress'::text, 'ready_for_review'::text, 'sent_to_client'::text, 'client_changes_requested'::text, 'awaiting_approval'::text, 'approved'::text, 'ready_to_file'::text, 'submitted'::text, 'accepted'::text, 'rejected'::text, 'filed'::text]))),
    CONSTRAINT filings_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT valid_status CHECK ((status = ANY (ARRAY['draft'::text, 'awaiting_approval'::text, 'approved'::text, 'ready_to_file'::text, 'filed'::text, 'rejected'::text])))
);


