--
-- Name: portal_access Accountants can manage portal access in their organization; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Accountants can manage portal access in their organization" ON public.portal_access TO authenticated USING (public.has_portal_role(auth.uid(), 'accountant'::public.portal_role, organization_id));


--
-- Name: user_roles Accountants can manage roles in their organization; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Accountants can manage roles in their organization" ON public.user_roles TO authenticated USING (public.has_portal_role(auth.uid(), 'accountant'::public.portal_role, organization_id));


--
-- Name: user_roles Accountants can view org roles; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Accountants can view org roles" ON public.user_roles FOR SELECT USING (public.user_in_organization(auth.uid(), organization_id));


--
-- Name: bookkeeping_queries Accountants manage org queries; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Accountants manage org queries" ON public.bookkeeping_queries TO authenticated USING (public.user_has_organization_access(organization_id)) WITH CHECK (public.user_has_organization_access(organization_id));


--
-- Name: payroll_journal_mapping Admin+ can delete payroll mapping; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admin+ can delete payroll mapping" ON public.payroll_journal_mapping FOR DELETE TO authenticated USING (public.user_role_is_at_least(auth.uid(), organization_id, 'admin'::text));


--
-- Name: payroll_journal_mapping Admin+ can manage payroll mapping; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admin+ can manage payroll mapping" ON public.payroll_journal_mapping FOR INSERT TO authenticated WITH CHECK (public.user_role_is_at_least(auth.uid(), organization_id, 'admin'::text));


--
-- Name: payroll_journal_mapping Admin+ can update payroll mapping; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admin+ can update payroll mapping" ON public.payroll_journal_mapping FOR UPDATE TO authenticated USING (public.user_role_is_at_least(auth.uid(), organization_id, 'admin'::text));


--
-- Name: team_invitations Admins and owners can create invitations; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins and owners can create invitations" ON public.team_invitations FOR INSERT WITH CHECK ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text))));


--
-- Name: team_invitations Admins and owners can delete invitations; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins and owners can delete invitations" ON public.team_invitations FOR DELETE USING ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text))));


--
-- Name: template_versions Admins can insert template versions; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can insert template versions" ON public.template_versions FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM public.templates
  WHERE ((templates.id = template_versions.template_id) AND public.user_has_organization_access(templates.organization_id) AND (public.has_organization_role(templates.organization_id, 'owner'::text) OR public.has_organization_role(templates.organization_id, 'admin'::text))))));


--
-- Name: sla_definitions Admins can manage SLA definitions; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage SLA definitions" ON public.sla_definitions USING ((organization_id IN ( SELECT organization_users.organization_id
   FROM public.organization_users
  WHERE ((organization_users.user_id = auth.uid()) AND (organization_users.role = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text]))))));


--
-- Name: automation_rules Admins can manage automation rules; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage automation rules" ON public.automation_rules USING ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text))));


--
-- Name: workpaper_category_mappings Admins can manage category mappings; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage category mappings" ON public.workpaper_category_mappings USING ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text))));


--
-- Name: period_locks Admins can manage period locks; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage period locks" ON public.period_locks USING ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text)))) WITH CHECK ((public.user_has_organization_access(organization_id) AND (public.has_organization_role(organization_id, 'owner'::text) OR public.has_organization_role(organization_id, 'admin'::text))));


--
-- Name: template_blocks Admins can manage template blocks; Type: POLICY; Schema: public; Owner: -
--

